import{n as e,r as t,t as n}from"./helpers-ClX0bpsp.js";var r={building:`backup-archive`,overview:[n(`Backups cost money in several ways: how much is stored, how long it is kept, and which tier it sits in. Cost-effective backup design keeps only what the recovery requirement needs, stores changes rather than full copies where possible, and moves old backups to a cheaper tier. Archive Annex covers the compliance side (immutability and retention rules); Disaster Bunker covers how backups fit the recovery strategies.`,[`backup-what-is`,`ebs-snapshots`,`ebs-snapshot-archive`],[`backup-what-is|AWS Backup is a fully-managed service that makes it easy to centralize and automate data protection across AWS services, in the cloud, and on premises.`,`ebs-snapshots|This minimizes the time required to create the snapshot and saves on storage costs by not duplicating data.`,`ebs-snapshot-archive|Amazon EBS Snapshots Archive is a storage tier that you can use for low-cost, long-term storage of your rarely-accessed snapshots that do not need frequent or fast retrieval.`])],bullets:[{id:`4.1-K5`,concepts:[n(`A backup strategy decides what to back up, how often, where the copies live and how long they are kept. How often you back up determines the recovery point you can achieve, and AWS does not automatically back up the data on your EBS volumes: it is your responsibility to create snapshots regularly or automate them with Amazon Data Lifecycle Manager or AWS Backup.`,[`dr-options`,`ebs-snapshots`],[`dr-options|How often you run your backup will determine your achievable recovery point (which should align to meet your RPO).`,`ebs-snapshots|AWS does not automatically back up the data stored on your EBS volumes.`,`ebs-snapshots|For data resiliency and disaster recovery, it is your responsibility to create EBS snapshots on a regular basis, or to set up automatic snapshot creation by using Automate backups with Amazon Data Lifecycle Manager or AWS Backup.`]),n(`Incremental backups keep storage costs down. An EBS snapshot is incremental: it saves only the blocks that changed since the most recent snapshot, which saves time and storage cost. AWS Backup also stores periodic backups incrementally for supported resource types: the first backup is a full copy and later backups store only changes; resource types that do not support incremental backups store a full copy every time, which can result in higher storage costs.`,[`ebs-snapshots`,`backup-what-is`],[`ebs-snapshots|incremental backup, which means that we save only the blocks on the volume that have changed since the most recent snapshot.`,`backup-what-is|The first backup of an AWS resource backs up a full copy of your data. For each successive incremental backup, only the changes to your AWS resources are backed up.`,`backup-what-is|For resources that do not support incremental backups, each backup is a full copy, which can result in higher storage costs.`]),n(`Amazon RDS takes automated backups during the backup window and keeps them for the backup retention period you specify, so you can recover to any point in time within that period.`,`rds-automated-backups`,[`Amazon RDS creates and saves automated backups of your DB instance or Multi-AZ DB cluster during the backup window of your DB instance.`,`RDS saves the automated backups of your DB instance according to the backup retention period that you specify.`,`If necessary, you can recover your DB instance to any point in time during the backup retention period.`]),n(`AWS Backup centralises policy-based backups using backup plans that define your requirements and apply to resources across services, and backups can be copied to other Regions on demand or as part of a scheduled plan.`,`backup-what-is`,[`Use these backup plans to define your backup requirements and then apply them to the AWS resources that you want to protect across the AWS services that you use.`,`Using AWS Backup, you can copy backups to multiple different AWS Regions on demand or automatically as part of a scheduled backup plan.`])],services:[`AWS Backup`,`Amazon S3 Glacier`],design:[n(`Cue: "meet the RPO with the least storage" → incremental snapshots and backups on the schedule the RPO needs; "recover a database to any point in the last N days" → the RDS backup retention period.`,[`dr-options`,`ebs-snapshots`,`rds-automated-backups`],[`dr-options|How often you run your backup will determine your achievable recovery point (which should align to meet your RPO).`,`ebs-snapshots|This minimizes the time required to create the snapshot and saves on storage costs by not duplicating data.`,`rds-automated-backups|RDS saves the automated backups of your DB instance according to the backup retention period that you specify.`])]},{id:`4.1-S6`,concepts:[n(`For backups you rarely need, EBS Snapshots Archive is a lower-cost tier for rarely accessed snapshots that do not need frequent or fast retrieval: snapshots in the standard tier are incremental, and archiving converts the incremental snapshot to a full snapshot in the archive tier.`,`ebs-snapshot-archive`,[`Amazon EBS Snapshots Archive is a storage tier that you can use for low-cost, long-term storage of your rarely-accessed snapshots that do not need frequent or fast retrieval.`,`Snapshots stored in the standard tier are incremental.`,`When you archive a snapshot, the incremental snapshot is converted to a full snapshot, and it is moved from the standard tier to the Amazon EBS Snapshots Archive tier (archive tier).`]),n(`Archiving is not always cheaper. The minimum archive period is 90 days, and deleting or permanently restoring an archived snapshot before then is billed for the remaining days. It can take up to 72 hours to restore an archived snapshot to the standard tier, restores are billed, and archived snapshots are always full snapshots, which will likely be larger than the incremental snapshot they were created from. AWS describes the saving as applying to snapshots you plan to store for at least the minimum period and rarely need to access.`,[`ebs-archive-considerations`,`ebs-archive-pricing`,`ebs-snapshot-archive`],[`ebs-archive-considerations|The minimum archive period is 90 days.`,`ebs-archive-considerations|If you delete or permanently restore an archived snapshot before the minimum archive period of 90 days, you are billed for remaining days in the archive tier, rounded to the nearest hour.`,`ebs-archive-considerations|It can take up to 72 hours to restore an archived snapshot from the archive tier to the standard tier, depending on the size of the snapshot.`,`ebs-archive-considerations|Archived snapshots are always full snapshots.`,`ebs-archive-considerations|The full snapshot will likely be larger than the incremental snapshot from which it was created.`,`ebs-archive-pricing|Snapshot restores are billed at a rate of`,`ebs-snapshot-archive|for snapshots that you plan to store for 90 days or longer and that you rarely need to access.`]),n(`AWS Backup has its own cold tier: the backup plan lifecycle can transition eligible resource types to cold storage on a timetable within the total retention period, and to use cold storage the total retention period must be at least 90 days. AWS recommends not moving a backup to cold storage until after at least 8 days, because a transition that is too early makes AWS Backup create another warm full backup.`,`backup-create-plan`,[`Cold storage: Select this box to let eligible resource types transition to cold storage in accordance with the timetable you specify in the total retention period.`,`To use cold storage, you must have a total retention period of 90 days or greater.`,`AWS Backup recommends that you set your lifecycle settings to not move your backup to cold storage until after at least 8 days.`,`If the full backup is transitioned to cold storage too soon (for example, a transition to cold storage after 1 day), AWS Backup will create another warm full backup.`]),n(`Tape Gateway lets you cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive (see Cold Cellar for the classes).`,`sgw-tape`,[`With Tape Gateway, you can cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`]),n(`Backup and archive are different tools. AWS Backup centralizes and automates data protection across services, while some S3 Glacier storage classes are archival: the objects stored in them are archived and not available for real-time access.`,[`backup-what-is`,`s3-glacier-classes`],[`backup-what-is|AWS Backup is a fully-managed service that makes it easy to centralize and automate data protection across AWS services, in the cloud, and on premises.`,`s3-glacier-classes|Some S3 Glacier storage classes are archival, which means the objects stored in those classes are archived and not available for real-time access.`])],services:[`AWS Backup`,`Amazon S3 Glacier`],design:[n(`Cue: "back up several AWS services centrally with one policy" → AWS Backup; "old EBS snapshots must be kept cheaply for years and rarely restored" → Snapshots Archive; "AWS Backup recoveries kept for months" → lifecycle to cold storage; "backup application writes to tape" → Tape Gateway; "long-term archive in S3" → Glacier classes.`,[`backup-what-is`,`ebs-snapshot-archive`,`sgw-tape`],[`backup-what-is|Use these backup plans to define your backup requirements and then apply them to the AWS resources that you want to protect across the AWS services that you use.`,`ebs-snapshot-archive|Amazon EBS Snapshots Archive is a storage tier that you can use for low-cost, long-term storage of your rarely-accessed snapshots that do not need frequent or fast retrieval.`,`sgw-tape|Tape Gateway provides cloud-backed virtual tape storage.`],{newer:[`backup-ebs-cold-storage`]})]}],cues:[e(`back up many AWS services centrally with one policy`,`AWS Backup (backup plans)`,n(`Backup plans define backup requirements and apply to resources across services.`,`backup-what-is`,[`Use these backup plans to define your backup requirements and then apply them to the AWS resources that you want to protect across the AWS services that you use.`])),e(`reduce backup storage: only changes after the first backup`,`Incremental snapshots and backups`,n(`Incremental backups store only the changes after the first full copy.`,`backup-what-is`,[`The first backup of an AWS resource backs up a full copy of your data. For each successive incremental backup, only the changes to your AWS resources are backed up.`])),e(`old EBS snapshots must be kept long-term at low cost`,`EBS Snapshots Archive`,n(`Snapshots Archive is low-cost, long-term storage for rarely accessed snapshots.`,`ebs-snapshot-archive`,[`Amazon EBS Snapshots Archive is a storage tier that you can use for low-cost, long-term storage of your rarely-accessed snapshots that do not need frequent or fast retrieval.`])),e(`restore the database to any point in time in the last N days`,`RDS automated backups with a retention period`,n(`RDS lets you recover to any point in time during the backup retention period.`,`rds-automated-backups`,[`If necessary, you can recover your DB instance to any point in time during the backup retention period.`])),e(`backup software that writes to tapes, archive in the cloud`,`Tape Gateway`,n(`Tape Gateway archives backup data cost-effectively in Glacier Flexible Retrieval or Deep Archive.`,`sgw-tape`,[`With Tape Gateway, you can cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`]))],examples:[],confuse:[],azure:[{concept:`Azure Backup`,aws:`AWS Backup`,mapping:n(`Learn pairs AWS Backup with Azure Backup, used to back up and recover files, databases, disks and virtual machines.`,[`learn-storage`,`backup-what-is`],[`learn-storage|Azure Backup This option is used to back up and recover files, databases, disks, and virtual machines.`,`backup-what-is|AWS Backup is a fully-managed service that makes it easy to centralize and automate data protection across AWS services, in the cloud, and on premises.`]),breaks:n(`On AWS, EBS Snapshots Archive is a storage tier for low-cost, long-term storage of rarely-accessed snapshots. Learn pairs AWS Backup with Azure Backup by function, backing up and recovering files, databases, disks and virtual machines.`,[`ebs-snapshot-archive`,`learn-storage`],[`ebs-snapshot-archive|Amazon EBS Snapshots Archive is a storage tier that you can use for low-cost, long-term storage of your rarely-accessed snapshots that do not need frequent or fast retrieval.`,`learn-storage|Azure Backup This option is used to back up and recover files, databases, disks, and virtual machines.`],{newer:[`backup-ebs-cold-storage`]})},{concept:`Storage archive access tier`,aws:`S3 Glacier storage classes`,mapping:n(`Learn pairs the Azure archive tier with S3 Glacier Flexible Retrieval and S3 Glacier Deep Archive: store data there for at least 180 days and expect retrieval latency measured in hours.`,[`learn-storage`,`s3-glacier-classes`],[`learn-storage|Azure archive Blob Storage is comparable to S3 Glacier Flexible Retrieval and S3 Glacier Deep Archive.`,`learn-storage|Store data there for at least 180 days and expect retrieval latency measured in hours.`,`s3-glacier-classes|Storage classes designed for less frequent access patterns with longer retrieval times offer lower storage costs.`]),breaks:n(`Learn pairs S3 Glacier Instant Retrieval with the Azure cold tier, an online tier for rarely accessed data that needs millisecond retrieval, and S3 Glacier Flexible Retrieval and Deep Archive with the Azure archive tier, an offline tier with the lowest storage cost and the highest retrieval cost. On AWS, the Glacier classes range from Instant Retrieval with millisecond retrieval to Flexible Retrieval at minutes to 12 hours and Deep Archive at 9 to 48 hours (Cold Cellar).`,[`s3-glacier-classes`,`learn-storage`],[`s3-glacier-classes|S3 Glacier Instant Retrieval 90 days Quarterly Milliseconds No S3 Glacier Flexible Retrieval 90 days Semi-annually Minutes to 12 hours Yes S3 Glacier Deep Archive 180 days Annually 9 to 48 hours Yes`,`learn-storage|S3 Glacier Instant Retrieval Cold tier An online tier for rarely accessed data that needs millisecond retrieval.`,`learn-storage|S3 Glacier Flexible Retrieval and S3 Glacier Deep Archive Archive tier An offline tier with the lowest storage cost and the highest retrieval cost.`])}]},i={building:`block-warehouse`,overview:[n(`Block storage cost depends on the volume type: EBS volume types differ in performance characteristics and price. Freight Depot described the performance of each EBS type; this building uses those facts to pick the lowest-cost type that still meets the requirement, and to decide whether instance store or EBS is the right kind of block storage at all.`,[`ebs-volume-types`,`ebs-modify`,`instance-store`],[`ebs-volume-types|Amazon EBS provides the following volume types, which differ in performance characteristics and price, so that you can tailor your storage performance and cost to the needs of your applications.`,`ebs-volume-types|HDD-backed volumes are optimized for large streaming workloads where the dominant performance attribute is throughput.`,`ebs-modify|With Amazon EBS Elastic Volumes, you can increase the volume size, change the volume type, or adjust the performance of your EBS volumes.`,`instance-store|An instance store provides temporary block-level storage for your EC2 instance.`])],bullets:[{id:`4.1-K6`,concepts:[n(`SSD-backed EBS volume types are General Purpose SSD and Provisioned IOPS SSD; HDD-backed types are Throughput Optimized HDD (st1) and Cold HDD (sc1). The HDD types are optimised for large streaming workloads where throughput, not {{term:iops}}, is the dominant performance attribute.`,`ebs-volume-types`,[`SSD-backed volume types include General Purpose SSD and Provisioned IOPS SSD .`,`HDD volume types include Throughput Optimized HDD and Cold HDD.`,`HDD-backed volumes are optimized for large streaming workloads where the dominant performance attribute is throughput.`]),n(`Throughput Optimized HDD suits big data, data warehouses and log processing; Cold HDD suits throughput-oriented storage for infrequently accessed data where the lowest storage cost is important. Neither HDD type can be a boot volume.`,`ebs-volume-types`,[`Big data Data warehouses Log processing Throughput-oriented storage for data that is infrequently accessed Scenarios where the lowest storage cost is important`,`Amazon EBS Multi-attach Not supported Boot volume Not supported`]),n(`General Purpose SSD suits transactional workloads, virtual desktops, medium-sized single-instance databases, boot volumes and development and test environments. Provisioned IOPS SSD is for workloads that require sustained IOPS performance and for I/O-intensive databases; of the Provisioned IOPS types, io2 Block Express is designed for consistent sub-millisecond latency.`,`ebs-volume-types`,[`Transactional workloadsVirtual desktopsMedium-sized, single-instance databasesLow-latency interactive applicationsBoot volumesDevelopment and test environments`,`Workloads that require: Consistent sub-millisecond latency with average latency under 500 microseconds`,`io2 Block Express volumes are designed to deliver an average latency of under 500 microseconds for 16KiB I/O operations.`,`I/O-intensive database workloads`]),n(`Among the General Purpose SSD types, gp3 is the latest generation and the lowest cost SSD volume offered by Amazon EBS, and it lets you scale volume performance independently of volume size, so you can provision the required performance without provisioning additional block storage capacity. AWS recommends General Purpose SSD volumes for most workloads.`,`ebs-gp`,[`General Purpose SSD (gp3) volumes are the latest generation of General Purpose SSD volumes, and the lowest cost SSD volume offered by Amazon EBS.`,`It also helps you to scale volume performance independently of volume size.`,`This means that you can provision the required performance without needing to provision additional block storage capacity.`,`We recommend these volumes for most workloads.`]),n(`Instance store is block storage on disks attached to the host, for temporary data such as buffers, caches and scratch data; it persists across a reboot but not if the instance is stopped, hibernated or terminated. The full comparison with EBS is in the Don't confuse section below.`,[`instance-store`,`instance-store-lifetime`],[`instance-store|Instance store is ideal for temporary storage of information that changes frequently, such as buffers, caches, scratch data, and other temporary content.`,`instance-store-lifetime|However, the data does not persist if the instance is stopped, hibernated, or terminated.`])],services:[`Amazon EBS`,`Amazon EFS`],design:[n(`Cue to the cheapest adequate type: infrequently accessed data and lowest cost → Cold HDD; big sequential scans → Throughput Optimized HDD; general-purpose or boot volume → General Purpose SSD; sustained high IOPS → Provisioned IOPS SSD (io2 Block Express where consistent sub-millisecond latency is required); lowest-cost SSD with performance set independently of size → gp3. Check the boot-volume constraint before choosing HDD for an OS disk.`,`ebs-volume-types`,[`Throughput-oriented storage for data that is infrequently accessed Scenarios where the lowest storage cost is important`,`Amazon EBS Multi-attach Not supported Boot volume Not supported`])]},{id:`4.1-S2`,concepts:[n(`Right-size by the workload, not by the maximum. Each EBS type has a supported size range (for example the HDD types range from 125 GiB to 16 TiB), so the size you choose also decides which types are available.`,`ebs-volume-types`,[`Volume size 125 GiB - 16 TiB Max IOPS per volume (1 MiB I/O) 500 250 Max throughput per volume 500 MiB/s 250 MiB/s`]),n(`Elastic Volumes can increase the size, change the type or adjust the performance of a volume, and if your instance supports Elastic Volumes you can do so without detaching the volume or restarting the instance. You can't decrease the volume size. As study guidance, that is why you grow a volume as needed instead of over-provisioning up front. There is no charge to modify the configuration, and you are charged for the new configuration after the modification starts.`,`ebs-modify`,[`With Amazon EBS Elastic Volumes, you can increase the volume size, change the volume type, or adjust the performance of your EBS volumes.`,`If your instance supports Elastic Volumes, you can do so without detaching the volume or restarting the instance.`,`You can't decrease the volume size.`,`There is no charge to modify the configuration of a volume.`,`You are charged for the new volume configuration after volume modification starts.`]),n(`Amazon EFS removes sizing from the decision for file data: it is built to scale on demand, growing and shrinking automatically as files are added and removed, without provisioning or managing storage capacity.`,`efs-what-is`,[`Amazon EFS is built to scale on demand to petabytes without disrupting applications, growing and shrinking automatically as you add and remove files.`])],services:[`Amazon EBS`,`Amazon EFS`],design:[n(`Cue: "volume is almost full but the instance must keep running" → modify the volume with Elastic Volumes; "capacity cannot be predicted and many instances share the files" → EFS.`,[`ebs-modify`,`efs-what-is`],[`ebs-modify|This enables you to continue using your application while the changes take effect.`,`efs-what-is|Amazon Elastic File System (Amazon EFS) provides serverless, fully elastic file storage so that you can share file data without provisioning or managing storage capacity and performance.`])]},{id:`4.1-S4`,concepts:[n(`Storage auto scaling means capacity that grows by itself. EFS grows and shrinks automatically. For databases, RDS storage autoscaling raises the allocated storage when it detects the database is running out of free space, which suits unpredictable workloads. RDS starts a storage modification for an autoscaling-enabled DB instance when free space is at or below a threshold, the low-storage condition lasts at least five minutes, and the previous storage optimization has completed with fewer than four storage modifications in the past 24 hours. You set a maximum storage threshold that limits how far it can grow.`,[`efs-what-is`,`rds-storage-autoscaling`],[`efs-what-is|Amazon EFS is built to scale on demand to petabytes without disrupting applications, growing and shrinking automatically as you add and remove files.`,`rds-storage-autoscaling|If your workload is unpredictable, you can enable storage autoscaling for an Amazon RDS DB instance.`,`rds-storage-autoscaling|With storage autoscaling enabled, when Amazon RDS detects that you are running out of free database space it automatically scales up your storage.`,`rds-storage-autoscaling|Free available space is less than or equal to`,`rds-storage-autoscaling|The low-storage condition lasts at least five minutes.`,`rds-storage-autoscaling|Storage optimization has completed on the instance for the previous storage modification, and fewer than four storage modifications have occurred in the past 24 hours.`,`rds-storage-autoscaling|The maximum storage threshold is the limit that you set for autoscaling the DB instance.`]),n(`You change an EBS volume with Elastic Volumes, and if the instance supports Elastic Volumes you can do so without detaching the volume or restarting the instance. S3 can store any amount of data.`,[`ebs-modify`,`s3-what-is`],[`ebs-modify|If your instance supports Elastic Volumes, you can do so without detaching the volume or restarting the instance.`,`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`])],services:[`Amazon EBS`,`Amazon EFS`,`Amazon RDS`],design:[n(`Cue: "database storage needs vary and running out of space would cause an outage" → enable RDS storage autoscaling; "shared file storage with unknown growth" → EFS; "block volume that fills up" → Elastic Volumes.`,[`rds-storage-autoscaling`,`efs-what-is`,`ebs-modify`],[`rds-storage-autoscaling|To avoid having to manually scale up database storage, you can use Amazon RDS storage autoscaling.`,`efs-what-is|Amazon Elastic File System (Amazon EFS) provides serverless, fully elastic file storage so that you can share file data without provisioning or managing storage capacity and performance.`,`ebs-modify|If your instance supports Elastic Volumes, you can do so without detaching the volume or restarting the instance.`])]}],cues:[e(`infrequently accessed data on EC2 at the lowest block-storage cost`,`Cold HDD (sc1)`,n(`Cold HDD is for infrequently accessed data where the lowest storage cost is important.`,`ebs-volume-types`,[`Throughput-oriented storage for data that is infrequently accessed Scenarios where the lowest storage cost is important`])),e(`large sequential workloads: big data, log processing, data warehouses`,`Throughput Optimized HDD (st1)`,n(`Throughput Optimized HDD suits big data, data warehouses and log processing.`,`ebs-volume-types`,[`Big data Data warehouses Log processing`])),e(`root/boot volume for a general workload`,`General Purpose SSD (HDD types cannot be boot volumes)`,n(`General Purpose SSD lists boot volumes among its use cases and the HDD types do not support boot volumes.`,`ebs-volume-types`,[`Amazon EBS Multi-attach Not supported Boot volume Not supported`])),e(`temporary scratch data or cache that can be recreated`,`Instance store`,n(`Instance store is ideal for buffers, caches, scratch data and other temporary content.`,`instance-store`,[`Instance store is ideal for temporary storage of information that changes frequently, such as buffers, caches, scratch data, and other temporary content.`])),e(`grow an EBS volume without detaching it, on an instance that supports Elastic Volumes`,`EBS Elastic Volumes`,n(`If your instance supports Elastic Volumes, you can increase the volume size without detaching the volume or restarting the instance.`,`ebs-modify`,[`With Amazon EBS Elastic Volumes, you can increase the volume size, change the volume type, or adjust the performance of your EBS volumes.`,`If your instance supports Elastic Volumes, you can do so without detaching the volume or restarting the instance.`])),e(`RDS database storage fills unpredictably`,`RDS storage autoscaling`,n(`RDS storage autoscaling automatically scales up storage when free space runs low.`,`rds-storage-autoscaling`,[`With storage autoscaling enabled, when Amazon RDS detects that you are running out of free database space it automatically scales up your storage.`]))],examples:[],confuse:[`instance-store-vs-ebs`],azure:[{concept:`Managed disks (Standard SSD, Premium SSD, Ultra Disk)`,aws:`Amazon EBS volume types`,mapping:n(`Learn maps EBS volume types to Azure managed disks by use: gp2/gp3 to Standard SSD, gp2 to Premium SSD, gp3 to Premium SSD v2, and io2 to Ultra Disk for IO-intensive workloads, and says on both platforms you need to match the storage performance of the VM with the provisioned disk type.`,[`learn-storage`,`ebs-volume-types`],[`learn-storage|For higher-performing disks, on both AWS and Azure you need to match the storage performance of the VM with the provisioned disk type and configuration.`,`learn-storage|io2 Ultra Disk Storage IO-intensive workloads, performance-demanding databases, and high-transaction workloads that require high throughput and IOPS No`,`ebs-volume-types|I/O-intensive database workloads`]),breaks:n(`Learn shows which Azure disk types can be used as an OS disk (Premium SSD v2 and Ultra Disk cannot). On AWS, the HDD-backed volumes (st1 and sc1) cannot be boot volumes, and Learn pairs no Azure disk type with them.`,[`learn-storage`,`ebs-volume-types`],[`learn-storage|Can this managed disk be used as an OS Disk`,`learn-storage|gp3 Premium SSD v2 Performance-sensitive workloads or workloads that require high IOPS and low latency No`,`learn-storage|io2 Ultra Disk Storage IO-intensive workloads, performance-demanding databases, and high-transaction workloads that require high throughput and IOPS No`,`ebs-volume-types|Amazon EBS Multi-attach Not supported Boot volume Not supported`],{allow:[`two`]})}]},a={building:`capacity-meter`,overview:[n(`Several levers help control database cost by fitting capacity to the load: choose a DynamoDB capacity mode or an RDS instance class that fits the workload, put a cache in front so repeated reads are served from the cache instead of the database, pool connections with RDS Proxy, and route read traffic to read replicas.`,[`dynamodb-capacity`,`elasticache-strategies`,`rds-proxy-planning`,`rds-read-replicas`],[`dynamodb-capacity|In Amazon DynamoDB, you can choose between on-demand mode and provisioned mode for your tables to accommodate different workload requirements.`,`elasticache-strategies|Amazon ElastiCache is an in-memory key-value store that sits between your application and the data store (database) that it accesses.`,`rds-proxy-planning|The proxy enables applications to open many client connections, while the proxy manages a smaller number of long-lived connections to the DB instance .`,`rds-read-replicas|You can reduce the load on your primary DB instance by routing queries from your applications to the read replica.`])],beyondProject:[n(`Your project uses DynamoDB. For provisioned mode the SAA step is reading capacity units. For an item up to 4 KB, one read capacity unit represents one strongly consistent read per second, or two eventually consistent reads per second, so an eventually consistent read needs half the read capacity. AWS says to consider provisioned capacity if you have steady workloads with predictable growth and can reliably forecast capacity requirements; otherwise on-demand mode avoids capacity planning.`,[`dynamodb-provisioned`,`dynamodb-capacity`],[`dynamodb-provisioned|For an item up to 4 KB, one read capacity unit (RCU) represents one strongly consistent read operation per second, or two eventually consistent read operations per second.`,`dynamodb-capacity|You can choose to use provisioned capacity if you have steady workloads with predictable growth, and if you can reliably forecast capacity requirements for your application.`,`dynamodb-capacity|DynamoDB on-demand enables you to create a table without worrying about capacity planning, monitoring usage, and configuring scaling policies.`],{newer:[`dynamodb-price-cut-2024`],allow:[`two`]})],bullets:[{id:`4.3-K3`,concepts:[n(`A cache is an in-memory key-value store between the application and its database. On a request the application asks the cache first and reads the database only on a miss, so repeated reads stop costing database capacity. In lazy loading only requested data is cached, which avoids filling the cache with data that is never requested; the cost is a cache miss penalty.`,`elasticache-strategies`,[`Amazon ElastiCache is an in-memory key-value store that sits between your application and the data store (database) that it accesses.`,`Only requested data is cached.`,`Because most data is never requested, lazy loading avoids filling up the cache with data that isn't requested.`,`The disadvantages of lazy loading are as follows: There is a cache miss penalty.`]),n(`For DynamoDB, DAX is a managed in-memory cache that is API-compatible with DynamoDB. For read-heavy or bursty workloads it provides increased throughput and potential operational cost savings by reducing the need to overprovision read capacity units. It helps eventually consistent reads: if a request specifies strongly consistent reads, DAX passes the request through to DynamoDB.`,[`dax`,`dax-concepts`],[`dax|DAX reduces operational and application complexity by providing a managed service that is API-compatible with DynamoDB.`,`dax|For read-heavy or bursty workloads, DAX provides increased throughput and potential operational cost savings by reducing the need to overprovision read capacity units.`,`dax-concepts|If the request specifies strongly consistent reads, DAX passes the request through to DynamoDB.`])],services:[`Amazon ElastiCache`,`Amazon DynamoDB`],design:[n(`Cue: "the same items are read over and over and the database is the bottleneck" → ElastiCache in front of the database; "DynamoDB read-heavy, avoid overprovisioning read capacity" → DAX.`,[`elasticache-strategies`,`dax`],[`elasticache-strategies|Amazon ElastiCache is an in-memory key-value store that sits between your application and the data store (database) that it accesses.`,`dax|For read-heavy or bursty workloads, DAX provides increased throughput and potential operational cost savings by reducing the need to overprovision read capacity units.`])]},{id:`4.3-K5`,concepts:[n(`DynamoDB capacity is chosen as on-demand mode or provisioned mode, and the throughput mode determines how the capacity is managed and how you are charged for reads and writes. In provisioned mode you specify throughput in capacity units, can change them later, or enable auto scaling to modify them automatically. Throughput requests that exceed the default table throughput quota are throttled.`,[`dynamodb-capacity`,`dynamodb-provisioned`],[`dynamodb-capacity|A table’s throughput mode determines how the capacity of a table is managed.`,`dynamodb-capacity|Throughput mode also determines how you're charged for the read and write operations on your tables.`,`dynamodb-provisioned|You can modify these settings later, if needed, or enable DynamoDB auto scaling to modify them automatically.`,`dynamodb-provisioned|Throughput requests that exceed the default table throughput quota are throttled.`]),n(`Provisioned capacity fits steady workloads with predictable growth, because you pay for the capacity you set; on-demand mode removes the planning and, with pay-per-request pricing, you pay only for the throughput you use.`,[`dynamodb-capacity`,`dynamodb-ondemand`],[`dynamodb-capacity|You can choose to use provisioned capacity if you have steady workloads with predictable growth, and if you can reliably forecast capacity requirements for your application.`,`dynamodb-ondemand|With pay-per-request pricing, you don’t have to worry about idle capacity because you only pay for the throughput you actually use.`]),n(`Some DynamoDB cost levers are not about throughput. The Standard-Infrequent Access table class is optimised for tables where storage is the dominant cost, such as old order history or logs, while the default Standard table class is recommended for the vast majority of workloads. Time to Live deletes items that are no longer relevant without consuming write throughput. For steady provisioned capacity you can buy reserved capacity, which is charged at a reserved rate for capacity used up to the amount you purchased.`,[`dynamodb-table-classes`,`dynamodb-ttl`,`dynamodb-pricing`],[`dynamodb-table-classes|The DynamoDB Standard table class is the default, and is recommended for the vast majority of workloads.`,`dynamodb-table-classes|The DynamoDB Standard-Infrequent Access (DynamoDB Standard-IA) table class is optimized for tables where storage is the dominant cost.`,`dynamodb-ttl|Time To Live (TTL) for DynamoDB is a cost-effective method for deleting items that are no longer relevant.`,`dynamodb-ttl|DynamoDB automatically deletes expired items within a few days of their expiration time, without consuming write throughput.`,`dynamodb-pricing|Each hour, if the amount of capacity used is less than or equal to the total reserved provisioned capacity you’ve purchased, all capacity will be charged at the reserved capacity rate.`],{newer:[`dynamodb-price-cut-2024`]}),n(`For relational databases, capacity planning means choosing the DB instance class. The instance class determines the computation and memory capacity of a DB instance, and you can change the CPU and memory available to a DB instance by changing its DB instance class.`,`rds-instance-class`,[`The DB instance class determines the computation and memory capacity of an Amazon RDS DB instance.`,`You can change the CPU and memory available to a DB instance by changing its DB instance class.`])],services:[`Amazon DynamoDB`,`Amazon RDS`],design:[n(`Cue: "predictable, steady throughput" → provisioned capacity (auto scaling can adjust it); "no capacity planning wanted" → on-demand; "relational database over- or under-sized" → change the DB instance class.`,[`dynamodb-capacity`,`dynamodb-provisioned`,`rds-instance-class`],[`dynamodb-capacity|You can choose to use provisioned capacity if you have steady workloads with predictable growth, and if you can reliably forecast capacity requirements for your application.`,`dynamodb-provisioned|You can modify these settings later, if needed, or enable DynamoDB auto scaling to modify them automatically.`,`dynamodb-capacity|DynamoDB on-demand enables you to create a table without worrying about capacity planning, monitoring usage, and configuring scaling policies.`,`rds-instance-class|You can change the CPU and memory available to a DB instance by changing its DB instance class.`,`rds-instance-class|The DB instance class determines the computation and memory capacity of an Amazon RDS DB instance.`])]},{id:`4.3-K6`,concepts:[n(`Amazon RDS Proxy lets applications pool and share database connections. The proxy enables applications to open many client connections while it manages a smaller number of long-lived connections to the DB instance, and it can reduce the CPU overhead of establishing connections. This lets a database serve many short-lived clients without being sized only to hold their connections.`,[`rds-proxy`,`rds-proxy-planning`],[`rds-proxy|By using Amazon RDS Proxy, you can allow your applications to pool and share database connections to improve their ability to scale.`,`rds-proxy-planning|The proxy enables applications to open many client connections, while the proxy manages a smaller number of long-lived connections to the DB instance .`,`rds-proxy-planning|It can also help reduce the CPU overhead for establishing connections.`]),n(`A DB instance that encounters "too many connections" errors is a good candidate for a proxy, and so are AWS Lambda functions.`,`rds-proxy-planning`,[`Any DB instance that encounters "too many connections" errors is a good candidate for associating with a proxy.`,`AWS Lambda functions can also be good candidates for using a proxy.`])],services:[`Amazon RDS`],design:[n(`Cue: "too many connections" errors on a DB instance, or AWS Lambda functions as clients → RDS Proxy.`,`rds-proxy-planning`,[`Any DB instance that encounters "too many connections" errors is a good candidate for associating with a proxy.`,`AWS Lambda functions can also be good candidates for using a proxy.`])]},{id:`4.3-K8`,concepts:[n(`A read replica is a read-only copy of a DB instance, and routing queries from your applications to the replica reduces the load on the primary DB instance. Read replicas are billed as standard DB instances at the same rates as the DB instance class used for the replica, so a replica is a way to buy read capacity rather than a free feature.`,`rds-read-replicas`,[`A read replica is a read-only copy of a DB instance.`,`You can reduce the load on your primary DB instance by routing queries from your applications to the read replica.`,`Read replicas are billed as standard DB instances at the same rates as the DB instance class used for the replica.`]),n(`You are not charged for the data transfer incurred in replicating data between the source DB instance and a read replica within the same AWS Region. AWS covers cross-Region replication costs separately, under Cross-Region replication costs and DB instance billing for Amazon RDS.`,`rds-read-replicas`,[`You aren't charged for the data transfer incurred in replicating data between the source DB instance and a read replica within the same AWS Region.`,`For more information, see Cross-Region replication costs and DB instance billing for Amazon RDS`]),n(`For Amazon RDS DB instances (the non-Aurora engines), RDS does not support autoscaling of read replicas, which is the automatic adding or removing of read replicas as read demand changes, so you add and delete replicas yourself. Aurora differs: Aurora Auto Scaling dynamically adjusts the number of Aurora Replicas in a cluster, and removes unnecessary replicas when the workload decreases so that you do not pay for unused provisioned DB instances.`,[`rds-read-replicas`,`aurora-autoscaling`],[`rds-read-replicas|RDS doesn't support autoscaling of read replicas, which is the automatic add or removing of read replicas as read demand changes.`,`aurora-autoscaling|To meet your connectivity and workload requirements, Aurora Auto Scaling dynamically adjusts the number of Aurora Replicas (reader DB instances) provisioned for an Aurora DB cluster.`,`aurora-autoscaling|When the connectivity or workload decreases, Aurora Auto Scaling removes unnecessary Aurora Replicas so that you don't pay for unused provisioned DB instances.`]),n(`DAX is a DynamoDB-compatible caching service that delivers fast response times for accessing eventually consistent data; if a request specifies strongly consistent reads, DAX passes the request through to DynamoDB.`,[`dax`,`dax-concepts`],[`dax|DAX is a DynamoDB-compatible caching service that enables you to benefit from fast in-memory performance for demanding applications.`,`dax|For these use cases, DynamoDB Accelerator (DAX) delivers fast response times for accessing eventually consistent data.`,`dax-concepts|If the request specifies strongly consistent reads, DAX passes the request through to DynamoDB.`])],services:[`Amazon RDS`,`Amazon ElastiCache`],design:[n(`Cue: "reporting queries slow the production database" → a read replica (billed like an instance), which reduces the load on the primary; "the same reads repeat" → a cache between the application and the database.`,[`rds-read-replicas`,`elasticache-strategies`],[`rds-read-replicas|You can reduce the load on your primary DB instance by routing queries from your applications to the read replica.`,`rds-read-replicas|Read replicas are billed as standard DB instances at the same rates as the DB instance class used for the replica.`,`elasticache-strategies|Amazon ElastiCache is an in-memory key-value store that sits between your application and the data store (database) that it accesses.`])]}],cues:[e(`steady, predictable DynamoDB throughput`,`Provisioned capacity mode (with auto scaling)`,n(`Provisioned capacity suits steady workloads with predictable growth.`,`dynamodb-capacity`,[`You can choose to use provisioned capacity if you have steady workloads with predictable growth, and if you can reliably forecast capacity requirements for your application.`])),e(`unpredictable DynamoDB traffic, no capacity planning`,`On-demand capacity mode`,n(`On-demand mode has pay-per-request pricing with no idle capacity to worry about.`,`dynamodb-ondemand`,[`With pay-per-request pricing, you don’t have to worry about idle capacity because you only pay for the throughput you actually use.`])),e(`repeated reads of the same data overload the database`,`ElastiCache (lazy loading) in front of the database`,n(`A cache sits between the application and the database, and lazy loading caches only requested data.`,`elasticache-strategies`,[`Only requested data is cached.`])),e(`DynamoDB read-heavy, avoid overprovisioning read capacity`,`DAX`,n(`DAX can reduce the need to overprovision read capacity units.`,`dax`,[`For read-heavy or bursty workloads, DAX provides increased throughput and potential operational cost savings by reducing the need to overprovision read capacity units.`])),e(`too many database connections from Lambda or many clients`,`Amazon RDS Proxy`,n(`A DB instance that hits "too many connections" errors is a good candidate for a proxy.`,`rds-proxy-planning`,[`Any DB instance that encounters "too many connections" errors is a good candidate for associating with a proxy.`])),e(`offload read-only queries from the primary database`,`RDS read replica`,n(`Routing queries to a read replica reduces the load on the primary.`,`rds-read-replicas`,[`You can reduce the load on your primary DB instance by routing queries from your applications to the read replica.`]))],examples:[],confuse:[],azure:[{concept:`Azure Managed Redis`,aws:`Amazon ElastiCache`,mapping:n(`Learn pairs Amazon ElastiCache with Azure Managed Redis as an in-memory cache and temporary data store, for caching, sessions, messaging and other low-latency temporary-data patterns.`,[`learn-databases`,`elasticache-what-is`],[`learn-databases|In-memory cache and temporary data store Amazon ElastiCache Azure Managed Redis Use Azure Managed Redis for caching, sessions, messaging, and other low-latency temporary-data patterns.`,`elasticache-what-is|Amazon ElastiCache is a web service that makes it easy to set up, manage, and scale a distributed in-memory data store or cache environment in the cloud.`]),breaks:n(`Learn says Azure Managed Redis is a cache and temporary data store. DAX is a managed service that is API-compatible with DynamoDB, so it is the cache for DynamoDB reads.`,[`learn-databases`,`dax`],[`learn-databases|Azure Managed Redis is a cache and temporary data store.`,`dax|DAX reduces operational and application complexity by providing a managed service that is API-compatible with DynamoDB.`])}]},o={building:`cold-cellar`,overview:[n(`Most data is hot for a short time and cold for a long time. S3 lets you pay less for cold data by moving it to a cheaper storage class, but each cheaper class trades something away: retrieval fees, minimum storage durations, a single Availability Zone or slower retrieval. Choosing the class, and automating the move with a lifecycle rule, is the core cost skill for object storage.`,[`s3-storage-classes`,`s3-glacier-classes`,`s3-lifecycle`],[`s3-storage-classes|These storage classes require minimum storage durations and retrieval fees making them most effective for rarely accessed data.`,`s3-glacier-classes|Storage classes designed for less frequent access patterns with longer retrieval times offer lower storage costs.`,`s3-lifecycle|Transition actions – These actions define when objects transition to another storage class.`])],beyondProject:[n(`Your static site keeps its files in S3 Standard, the default class. The SAA questions start when data accumulates: access logs, old versions of site files or user uploads that nobody reads after a month. A lifecycle configuration can transition those objects to cheaper classes and expire them, without touching the live site.`,[`s3-storage-classes`,`s3-lifecycle`],[`s3-storage-classes|S3 Standard (STANDARD) – The default storage class.`,`s3-lifecycle|Expiration actions – These actions define when objects expire.`])],bullets:[{id:`4.1-K7`,concepts:[n(`A data lifecycle is the sequence of states data passes through: created and used frequently, then infrequently, then archived, then deleted. S3 Lifecycle expresses it as rules with transition actions (move objects to another storage class, for example to Standard-IA 30 days after creation or to Glacier Flexible Retrieval one year after creation) and expiration actions (delete objects, after which S3 deletes expired objects on your behalf).`,`s3-lifecycle`,[`Transition actions – These actions define when objects transition to another storage class.`,`For example, you might choose to transition objects to the S3 Standard-IA storage class 30 days after creating them, or archive objects to the S3 Glacier Flexible Retrieval storage class one year after creating them.`,`Expiration actions – These actions define when objects expire. Amazon S3 deletes expired objects on your behalf.`]),n(`Lifecycle transitions follow a waterfall model, a fixed set of allowed paths: from S3 Standard to Standard-IA, Intelligent-Tiering, One Zone-IA, Glacier Instant Retrieval, Glacier Flexible Retrieval or Glacier Deep Archive, and from Standard-IA to Intelligent-Tiering, One Zone-IA or the Glacier classes; objects move toward colder classes, not back. There are costs for lifecycle transition requests, and objects smaller than 128 KB are not transitioned by default because the transition cost can outweigh the storage savings.`,[`s3-lifecycle-transitions`,`s3-lifecycle`],[`s3-lifecycle-transitions|Amazon S3 supports a waterfall model for transitioning between storage classes, as shown in the following diagram.`,`s3-lifecycle-transitions|The S3 Standard storage class to the S3 Standard-IA, S3 Intelligent-Tiering, S3 One Zone-IA, S3 Glacier Instant Retrieval, S3 Glacier Flexible Retrieval, or S3 Glacier Deep Archive storage classes.`,`s3-lifecycle-transitions|The S3 Standard-IA storage class to the S3 Intelligent-Tiering, S3 One Zone-IA, S3 Glacier Instant Retrieval, S3 Glacier Flexible Retrieval, or S3 Glacier Deep Archive storage classes.`,`s3-lifecycle-transitions|Objects smaller than 128 KB will not transition by default to any storage class`,`s3-lifecycle-transitions|We don't recommend transitioning objects less than 128 KB because you are charged a transition request for each object.`,`s3-lifecycle|There are costs associated with lifecycle transition requests.`],{newer:[`s3-lifecycle-default-min-size`]}),n(`A lifecycle configuration is set on a bucket; it consists of rules, and each rule has an ID, a status (enabled or disabled), a filter that identifies the objects it applies to, and actions. A bucket can have one lifecycle configuration with up to 1,000 rules, written as XML.`,`s3-lifecycle-rules`,[`A S3 Lifecycle configuration consist of Lifecycle rules that include various elements that describe the actions Amazon S3 takes during an object's lifetime.`,`Each S3 bucket can have one lifecycle configuration assigned to it, which can contain up to 1,000 rules.`,`Rule metadata that includes a rule ID, and a status that indicates whether the rule is enabled or disabled.`])],services:[`Amazon S3`,`Amazon S3 Glacier`],design:[n(`Cue: "data is accessed frequently for a month and rarely after" → lifecycle transition to an infrequent-access or archive class; "delete after the retention period" → expiration; "unknown pattern" → Intelligent-Tiering instead of a fixed schedule.`,[`s3-lifecycle`,`s3-storage-classes`],[`s3-lifecycle|Expiration actions – These actions define when objects expire. Amazon S3 deletes expired objects on your behalf.`,`s3-storage-classes|S3 Intelligent-Tiering is the ideal storage class when you want to optimize storage costs for data that has unknown or changing access patterns.`])]},{id:`4.1-K10`,concepts:[n(`Cold tiering for object storage means placing data in a storage class that matches how rarely it is read. The IA classes suit infrequently accessed data that still needs millisecond access (with a retrieval fee); the Glacier classes suit long-term, rarely accessed data and require minimum storage durations and retrieval fees.`,`s3-storage-classes`,[`Amazon S3 charges a retrieval fee for these objects, so they are most suitable for infrequently accessed data.`,`These storage classes require minimum storage durations and retrieval fees making them most effective for rarely accessed data.`]),n(`The Glacier classes differ in retrieval: Instant Retrieval offers millisecond retrieval and real-time access (90-day minimum), Flexible Retrieval offers minutes to 12 hours (90-day minimum), and Deep Archive offers 9 to 48 hours (180-day minimum), with Flexible Retrieval and Deep Archive archived and unavailable for real-time access. These are documented values that can change.`,`s3-glacier-classes`,[`S3 Glacier Instant Retrieval 90 days Quarterly Milliseconds No S3 Glacier Flexible Retrieval 90 days Semi-annually Minutes to 12 hours Yes S3 Glacier Deep Archive 180 days Annually 9 to 48 hours Yes`]),n(`The S3 storage class comparison table gives the minimum storage durations and minimum billable object sizes: 30 days for S3 Standard-IA and One Zone-IA, 90 days for Glacier Instant Retrieval and Glacier Flexible Retrieval, and 180 days for Glacier Deep Archive; the minimum billable object size is 128 KB for Standard-IA, One Zone-IA and Glacier Instant Retrieval. The storage classes page says that if you delete an object before the end of the 30-day minimum storage duration period, you are charged for 30 days, and that an object smaller than 128 KB is charged for 128 KB. The minimum is charged when an object leaves one of these classes, or is deleted, before the minimum duration ends; the decision guide's statement about entering the classes is shown in the disagreements block below.`,[`s3-storage-classes`],[`s3-storage-classes|(once a month) with millisecond access 99.999999999% 99.9% >= 3 30 days 128 KB`,`s3-storage-classes|99.999999999% 99.5% 1 30 days 128 KB`,`s3-storage-classes|(GLACIER_IR) Long-lived, archive data accessed once a quarter with millisecond access 99.999999999% 99.9% >= 3 90 days 128 KB`,`s3-storage-classes|(GLACIER) Long-lived archive data accessed once a year with retrieval times of minutes to hours 99.999999999% 99.99% (after you restore objects) >= 3 90 days NA`,`s3-storage-classes|>= 3 180 days NA`,`s3-storage-classes|If you delete an object before the end of the 30-day minimum storage duration period, you are charged for 30 days.`,`s3-storage-classes|If an object is less than 128 KB, Amazon S3 charges you for 128 KB.`],{newer:[`s3-lifecycle-default-min-size`],allow:[`128`,`30`,`90`,`180`]}),n(`S3 Intelligent-Tiering automates tiering: it stores objects in access tiers (Frequent Access, Infrequent Access and Archive Instant Access automatically, with optional Archive Access and Deep Archive Access) and moves objects that have not been accessed for 30 consecutive days to the Infrequent Access tier and after 90 consecutive days to Archive Instant Access. It has no retrieval fees, but it charges a small monthly object monitoring and automation fee, and objects smaller than 128 KB are not monitored and not eligible for auto-tiering.`,`s3-storage-classes`,[`S3 Intelligent-Tiering moves objects that have not been accessed in 30 consecutive days to the Infrequent Access tier.`,`With S3 Intelligent-Tiering, any existing objects that have not been accessed for 90 consecutive days are automatically moved to the Archive Instant Access tier.`,`There are no retrieval fees for S3 Intelligent-Tiering.`,`For a small monthly object monitoring and automation fee, S3 Intelligent-Tiering monitors access patterns and automatically moves objects that have not been accessed to lower-cost access tiers.`,`If the size of an object is less than 128 KB, it is not monitored and not eligible for auto-tiering.`],{newer:[`efs-archive-class`]})],services:[`Amazon S3`,`Amazon S3 Glacier`],design:[n(`The full class-by-class comparison is in the Don't confuse section below. When a requirement states how fast archived data must be retrieved, that answer picks the Glacier class.`,`s3-glacier-classes`,[`S3 Glacier Instant Retrieval 90 days Quarterly Milliseconds No S3 Glacier Flexible Retrieval 90 days Semi-annually Minutes to 12 hours Yes S3 Glacier Deep Archive 180 days Annually 9 to 48 hours Yes`])]},{id:`4.1-S5`,concepts:[n(`To manage lifecycles, create a lifecycle configuration on the bucket with a filter (a key prefix and/or object tags) so only the intended objects are affected, then add transition and expiration actions. The lifecycle transition page says you cannot create a single Lifecycle rule that transitions objects from one storage class to another before the minimum storage duration period has passed.`,[`s3-lifecycle-rules`,`s3-lifecycle-transitions`],[`s3-lifecycle-rules|A filter that identifies the objects to which the rule applies.`,`s3-lifecycle-transitions|You can't create a single Lifecycle rule that transitions objects from one storage class to another before the minimum storage duration period has passed.`]),n(`Four more lifecycle actions control hidden cost. NoncurrentVersionTransition moves noncurrent versions to another class. In a versioned bucket an Expiration action applies only to the current version, so NoncurrentVersionExpiration is what permanently deletes noncurrent versions. ExpiredObjectDeleteMarker cleans up a delete marker that has no noncurrent versions left. AbortIncompleteMultipartUpload sets a maximum time in days that multipart uploads may stay in progress; object expiration does not remove incomplete multipart uploads, and AWS recommends the abort rule to minimise storage costs.`,[`s3-lifecycle-rules`,`s3-mpu-abort`],[`s3-lifecycle-rules|NoncurrentVersionTransition action element – Use this action to specify when Amazon S3 transitions objects to the specified storage class.`,`s3-lifecycle-rules|NoncurrentVersionExpiration action element – Use this action to direct Amazon S3 to permanently delete noncurrent versions of objects.`,`s3-lifecycle-rules|The Expiration action applies only to the current version (it has no impact on noncurrent object versions).`,`s3-lifecycle-rules|ExpiredObjectDeleteMarker action element – In a versioning-enabled bucket, a delete marker with zero noncurrent versions is referred to as an expired object delete marker.`,`s3-lifecycle-rules|AbortIncompleteMultipartUpload action element – Use this element to set a maximum time (in days) that you want to allow multipart uploads to remain in progress.`,`s3-lifecycle-rules|Object expiration lifecycle configurations don't remove incomplete multipart uploads.`,`s3-mpu-abort|As a best practice, we recommend that you configure a lifecycle rule by using the AbortIncompleteMultipartUpload action to minimize your storage costs.`],{allow:[`four`]}),n(`Expiration behaves according to versioning: in a nonversioned bucket S3 queues the object for removal and removes it permanently; in a versioning-enabled bucket it adds a delete marker that becomes the current version and makes the previous version noncurrent. Expiration applies only to an object's current version, so versioned buckets need separate rules for noncurrent versions.`,`s3-lifecycle-expire`,[`Nonversioned bucket – Amazon S3 queues the object for removal and removes it asynchronously, permanently removing the object.`,`Versioning-enabled bucket – If the current object version is not a delete marker, Amazon S3 adds a delete marker with a unique version ID.`,`Object expiration applies only to an object's current version (it has no impact on noncurrent object versions).`])],services:[`Amazon S3`],design:[n(`Cue: "automatically move objects to cheaper storage after N days and delete after M" → lifecycle rule; "only for the logs/ prefix" → prefix filter.`,`s3-lifecycle-rules`,[`A filter that identifies the objects to which the rule applies.`])]},{id:`4.1-S8`,concepts:[n(`Choose the tier by asking: how quickly must the data be available, and how often will it be read. Needs milliseconds and read often → Standard; read rarely but still milliseconds → Standard-IA / One Zone-IA / Glacier Instant Retrieval; can wait minutes to hours → Glacier Flexible Retrieval; can wait 9 to 48 hours and almost never read → Deep Archive; pattern unknown → Intelligent-Tiering.`,[`s3-glacier-classes`,`s3-storage-classes`],[`s3-glacier-classes|S3 Glacier Instant Retrieval 90 days Quarterly Milliseconds No S3 Glacier Flexible Retrieval 90 days Semi-annually Minutes to 12 hours Yes S3 Glacier Deep Archive 180 days Annually 9 to 48 hours Yes`,`s3-storage-classes|S3 Intelligent-Tiering is the ideal storage class when you want to optimize storage costs for data that has unknown or changing access patterns.`]),n(`Resilience matters too: One Zone-IA stores data in only one Availability Zone and is not resilient to losing that zone, so it fits re-creatable data or replicas, not the only copy.`,`s3-storage-classes`,[`S3 One Zone-IA (ONEZONE_IA) – Use if you can re-create the data if the Availability Zone fails, for object replicas when configuring S3 Cross-Region Replication (CRR).`])],services:[`Amazon S3`,`Amazon S3 Glacier`],design:[n(`Typical answers: archive where portions might need to be retrieved in minutes → Glacier Flexible Retrieval; archiving data that rarely needs to be accessed → Deep Archive; unknown or changing access patterns → Intelligent-Tiering; re-creatable data → One Zone-IA.`,`s3-storage-classes`,[`S3 Glacier Flexible Retrieval (GLACIER) – Use for archives where portions of the data might need to be retrieved in minutes.`,`S3 Glacier Deep Archive (DEEP_ARCHIVE) – Use for archiving data that rarely needs to be accessed.`,`S3 Intelligent-Tiering is the ideal storage class when you want to optimize storage costs for data that has unknown or changing access patterns.`,`S3 One Zone-IA (ONEZONE_IA) – Use if you can re-create the data if the Availability Zone fails, for object replicas when configuring S3 Cross-Region Replication (CRR).`])]},{id:`4.1-S9`,concepts:[n(`Choose the lifecycle by matching age to access: storage classes designed for less frequent access patterns with longer retrieval times offer lower storage costs, and an expiration action deletes objects when they expire. Transitioning or deleting before a minimum storage duration is charged for the remainder of that duration.`,[`s3-glacier-classes`,`s3-lifecycle`],[`s3-glacier-classes|Storage classes designed for less frequent access patterns with longer retrieval times offer lower storage costs.`,`s3-lifecycle|Expiration actions – These actions define when objects expire. Amazon S3 deletes expired objects on your behalf.`,`s3-glacier-classes|If you delete, overwrite, or transition the object to a different storage class before the minimum, you are charged for the remainder of that duration.`]),n(`S3 Storage Class Analysis can help optimise costs between S3 Standard and S3 Standard-IA by analysing storage access patterns. Its scope is narrow: it only provides recommendations for Standard to Standard-IA, not for the Glacier classes or One Zone-IA, and you can filter it by prefix, by object tags, or both.`,[`s3-storage-classes`,`s3-analytics`],[`s3-storage-classes|To help you optimize costs between S3 Standard and S3 Standard-IA you can use Amazon S3 analytics – Storage Class Analysis.`,`s3-analytics|Storage class analysis only provides recommendations for Standard to Standard IA classes.`,`s3-analytics|Or, you can configure filters to group objects together for analysis by common prefix (that is, objects that have names that begin with a common string), by object tags, or by both prefix and tags.`])],services:[`Amazon S3`],design:[n(`Cue: "retain for a long compliance period, rarely read" → transition to an archive class and expire at the end of the retention period.`,`s3-lifecycle`,[`Expiration actions – These actions define when objects expire. Amazon S3 deletes expired objects on your behalf.`])]}],disagreements:[n(`Two AWS pages give different figures for how much lower the request costs of S3 Express One Zone are than S3 Standard: the "What is Amazon S3?" page says 80 percent and the storage classes page says 50 percent. This app states no figure, and no question depends on one; check the current S3 pricing page before you rely on either.`,[`s3-what-is`,`s3-storage-classes`],[`s3-what-is|S3 Express One Zone is the lowest latency cloud object storage class available today, with data access speeds up to 10x faster and with request costs 80 percent lower than S3 Standard.`,`s3-storage-classes|S3 Express One Zone is the lowest latency cloud object storage class available today, with data access speed up to 10x faster and with request costs 50 percent lower than S3 Standard.`],{disputed:`c-s3-express-request-cost`,allow:[`two`],newer:[`s3-express-one-zone`]}),n(`Read by direction, the pages agree. The storage decision guide says S3 no longer applies a 30-day minimum storage duration for transitions to S3 Standard-IA and One Zone-IA, which concerns entering the class. The storage classes page and the lifecycle transition page describe the charge for objects that are deleted, overwritten or transitioned out of these classes before the minimum duration. The lifecycle transition page also says a single Lifecycle rule cannot transition objects from one storage class to another before the minimum storage duration period has passed. This app states the billing charge as written and does not treat an entry minimum as a fact.`,[`storage-decision`,`s3-storage-classes`,`s3-lifecycle-transitions`],[`storage-decision|Amazon S3 no longer applies a 30-day minimum storage duration for transitions to Amazon S3 Standard-Infrequent Access and Amazon S3 One Zone-Infrequent Access.`,`s3-storage-classes|If you delete an object before the end of the 30-day minimum storage duration period, you are charged for 30 days.`,`s3-lifecycle-transitions|You can't create a single Lifecycle rule that transitions objects from one storage class to another before the minimum storage duration period has passed.`,`s3-lifecycle-transitions|If you transition objects out of these storage classes before the minimum duration, you are charged for the remainder of that duration.`],{disputed:`c-s3-ia-transition-direction`,allow:[`30`],newer:[`s3-ia-day-zero`]}),n(`Newer than the exam guide: the exam may expect objects to stay 30 days in S3 Standard before a lifecycle transition to Standard-IA or One Zone-IA. The storage decision guide says S3 no longer applies a 30-day minimum storage duration for transitions to these classes, and the What's New post describes the previous 30-day minimum retention in S3 Standard. The practice questions and puzzles in this app do not depend on either reading.`,[`storage-decision`,`pg-s3-ia-day-zero`],[`storage-decision|Amazon S3 no longer applies a 30-day minimum storage duration for transitions to Amazon S3 Standard-Infrequent Access and Amazon S3 One Zone-Infrequent Access.`,`pg-s3-ia-day-zero|without the previous 30-day minimum retention in S3 Standard`],{newer:[`s3-ia-day-zero`]})],cues:[e(`unknown or changing access pattern, no retrieval fees`,`S3 Intelligent-Tiering`,n(`Intelligent-Tiering suits unknown or changing access patterns and has no retrieval fees.`,`s3-storage-classes`,[`There are no retrieval fees for S3 Intelligent-Tiering.`])),e(`infrequently accessed, millisecond access, only copy of the data`,`S3 Standard-IA`,n(`Standard-IA is for your primary or only copy of data that cannot be re-created.`,`s3-storage-classes`,[`S3 Standard-IA (STANDARD_IA) – Use for your primary or only copy of data that can't be re-created.`])),e(`infrequently accessed and can be re-created, lower cost`,`S3 One Zone-IA`,n(`One Zone-IA stores in a single Availability Zone, which makes it less expensive than Standard-IA.`,`s3-storage-classes`,[`S3 One Zone-IA (ONEZONE_IA) – Amazon S3 stores the object data in only one Availability Zone, which makes it less expensive than S3 Standard-IA.`])),e(`archive with millisecond retrieval, accessed about quarterly`,`S3 Glacier Instant Retrieval`,n(`Glacier Instant Retrieval is for long-term rarely accessed data that requires millisecond retrieval.`,`s3-storage-classes`,[`S3 Glacier Instant Retrieval (GLACIER_IR) – Use for long-term data that's rarely accessed and requires milliseconds retrieval.`])),e(`archive, retrieval in minutes to hours is acceptable`,`S3 Glacier Flexible Retrieval`,n(`Flexible Retrieval is for archives where portions might need to be retrieved in minutes.`,`s3-storage-classes`,[`S3 Glacier Flexible Retrieval (GLACIER) – Use for archives where portions of the data might need to be retrieved in minutes.`])),e(`long-term archive that rarely needs access, retrieval within a day or two acceptable`,`S3 Glacier Deep Archive`,n(`Deep Archive is for data that rarely needs to be accessed, with 9 to 48 hours retrieval.`,`s3-glacier-classes`,[`S3 Glacier Deep Archive 180 days Annually 9 to 48 hours Yes`])),e(`automatically move objects to cheaper classes by age`,`S3 Lifecycle transition rules`,n(`Transition actions define when objects move to another storage class.`,`s3-lifecycle`,[`Transition actions – These actions define when objects transition to another storage class.`]))],examples:[t(`Lifecycle rule: log objects move colder, then expire`,`lifecycle`,`
<LifecycleConfiguration>
  <Rule>
    <ID>age-out-logs</ID>
    <Filter>
      <Prefix>logs/</Prefix>
    </Filter>
    <Status>Enabled</Status>
    <Transition>
      <Days>30</Days>
      <StorageClass>STANDARD_IA</StorageClass>
    </Transition>
    <Transition>
      <Days>120</Days>
      <StorageClass>GLACIER</StorageClass>
    </Transition>
    <Expiration>
      <Days>730</Days>
    </Expiration>
  </Rule>
</LifecycleConfiguration>
`,[n(`A lifecycle configuration is XML made of rules; each rule has an ID and a Status that says whether it is enabled, and a Filter that limits which objects it applies to. Here the Filter limits the rule to objects whose key starts with logs/.`,`s3-lifecycle-rules`,[`Rule metadata that includes a rule ID, and a status that indicates whether the rule is enabled or disabled.`,`A filter that identifies the objects to which the rule applies.`]),n(`Each Transition says when to move objects and to which class. STANDARD_IA is S3 Standard-IA and GLACIER is S3 Glacier Flexible Retrieval; the example moves objects to the first class after 30 days and to the second after a longer period.`,`s3-lifecycle`,[`For example, you might choose to transition objects to the S3 Standard-IA storage class 30 days after creating them, or archive objects to the S3 Glacier Flexible Retrieval storage class one year after creating them.`]),n(`The Expiration action deletes the objects at the end of their lifetime; in a nonversioned bucket S3 queues the object for removal and removes it permanently. The day counts, the prefix and the rule ID are placeholders for illustration, not recommended settings.`,`s3-lifecycle-expire`,[`Nonversioned bucket – Amazon S3 queues the object for removal and removes it asynchronously, permanently removing the object.`])])],confuse:[`s3-storage-classes`],azure:[{concept:`Storage cool tier`,aws:`S3 Standard-IA`,mapping:n(`Learn pairs S3 Standard-Infrequent Access with the Azure cool tier, for data that is infrequently accessed but must be available immediately when accessed.`,[`learn-storage`,`s3-storage-classes`],[`learn-storage|For data that's infrequently accessed but must be available immediately when accessed, the cool tier provides cheaper storage than the hot tier, with a 30-day minimum retention period.`,`learn-storage|This tier is comparable to S3 Standard-Infrequent Access.`,`s3-storage-classes|Amazon S3 charges a retrieval fee for these objects, so they are most suitable for infrequently accessed data.`]),breaks:n(`Learn pairs S3 Standard-Infrequent Access with the Azure cool tier. On AWS, S3 One Zone-IA stores the object data in only one Availability Zone, which makes it less expensive than S3 Standard-IA.`,[`s3-storage-classes`,`learn-storage`],[`s3-storage-classes|S3 One Zone-IA (ONEZONE_IA) – Amazon S3 stores the object data in only one Availability Zone, which makes it less expensive than S3 Standard-IA.`,`learn-storage|This tier is comparable to S3 Standard-Infrequent Access.`])},{concept:`Storage archive access tier`,aws:`S3 Glacier storage classes`,mapping:n(`Learn pairs the Azure archive tier with S3 Glacier Flexible Retrieval and S3 Glacier Deep Archive: store data there for at least 180 days and expect retrieval latency measured in hours.`,[`learn-storage`,`s3-glacier-classes`],[`learn-storage|Azure archive Blob Storage is comparable to S3 Glacier Flexible Retrieval and S3 Glacier Deep Archive.`,`learn-storage|Store data there for at least 180 days and expect retrieval latency measured in hours.`,`s3-glacier-classes|S3 Glacier Deep Archive 180 days Annually 9 to 48 hours Yes`]),breaks:n(`Learn pairs the Azure archive tier with S3 Glacier Flexible Retrieval and S3 Glacier Deep Archive, and S3 Glacier Instant Retrieval with the Azure cold tier. The break is in the numbers: Learn gives the archive tier at least 180 days of storage with retrieval measured in hours, while S3 Glacier Flexible Retrieval has a 90-day minimum storage duration and retrieval times of minutes to 12 hours.`,[`s3-glacier-classes`,`learn-storage`],[`s3-glacier-classes|S3 Glacier Instant Retrieval 90 days Quarterly Milliseconds No S3 Glacier Flexible Retrieval 90 days Semi-annually Minutes to 12 hours Yes S3 Glacier Deep Archive 180 days Annually 9 to 48 hours Yes`,`learn-storage|Azure archive Blob Storage is comparable to S3 Glacier Flexible Retrieval and S3 Glacier Deep Archive.`,`learn-storage|The cold tier is comparable to S3 Glacier Instant Retrieval.`,`learn-storage|Store data there for at least 180 days and expect retrieval latency measured in hours.`])}]},s={building:`counting-house`,overview:[n(`The exam asks about compute cost from both sides: how you pay (the purchasing option) and how you see and control the spend (the cost tools). EC2 offers On-Demand Instances, Savings Plans, Reserved Instances, Spot Instances, Dedicated Hosts, Dedicated Instances and Capacity Reservations. Ledger Office introduced the cost tools; this building applies them to compute and adds the purchasing options.`,[`ec2-purchasing`],[`ec2-purchasing|You can use the following options to optimize your costs for Amazon EC2`,`ec2-purchasing|On-Demand Instances – Pay, by the second, for the instances that you launch.`])],bullets:[{id:`4.2-K1`,concepts:[n(`Cost allocation tags track your AWS costs on a detailed level. If you tag resources with an application name, you can track the total cost of a single application that runs on those resources. A tag is a label that you or AWS assigns to an AWS resource, and you must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`,`cost-alloc-tags`,[`You can use tags to organize your resources, and cost allocation tags to track your AWS costs on a detailed level.`,`For example, if you tag resources with an application name, you can track the total cost of a single application that runs on those resources.`,`A tag is a label that you or AWS assigns to an AWS resource.`,`You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`]),n(`Consolidated billing matters for purchasing options: when accounts are in one organisation, the combined usage shares volume pricing discounts, Reserved Instance discounts and Savings Plans, so a commitment bought in one account can benefit others.`,`consolidated-billing`,[`This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`])],services:[`AWS Organizations`,`Amazon EC2`],design:[n(`Cue: "charge compute costs back to each department" → tag instances and activate the tags; "many accounts should share one commitment" → consolidated billing in AWS Organizations.`,[`cost-alloc-tags`,`consolidated-billing`],[`cost-alloc-tags|After you activate cost allocation tags, AWS uses the cost allocation tags to organize your resource costs on your cost allocation report, to make it easier for you to categorize and track your AWS costs.`,`consolidated-billing|This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`])]},{id:`4.2-K2`,concepts:[n(`Cost Explorer is where you decide what to commit to: to get started with Savings Plans, you use AWS Cost Explorer to view your recommended Savings Plans commitment, purchase and manage your plans, and view your historical usage.`,`savings-plans`,[`To get started, use AWS Cost Explorer to view your recommended Savings Plans commitment, refresh Savings Plans recommendations, purchase Savings Plans, manage your Savings Plans, and view your historical AWS usage.`]),n(`AWS Budgets can monitor how well commitments are used: it tracks your aggregate utilisation and coverage metrics for Reserved Instances or Savings Plans, in addition to cost and usage budgets with alerts.`,`budgets-managing`,[`You can use AWS Budgets to monitor your aggregate utilization and coverage metrics for your Reserved Instances (RIs) or Savings Plans.`]),n(`The Cost and Usage Report is the detailed record behind the other tools: it contains the most comprehensive set of cost and usage data available, published to an S3 bucket you own.`,`cur-what-is`,[`AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`,`You can use Cost and Usage Reports to publish your AWS billing reports to an Amazon Simple Storage Service (Amazon S3) bucket that you own.`])],services:[`AWS Cost Explorer`,`AWS Budgets`],design:[n(`Cue: "which Savings Plan should we buy?" → Cost Explorer recommendations; "are we using what we committed to?" → Budgets utilisation and coverage; "full line-item data" → Cost and Usage Report.`,[`savings-plans`,`budgets-managing`,`cur-what-is`],[`savings-plans|To get started, use AWS Cost Explorer to view your recommended Savings Plans commitment, refresh Savings Plans recommendations, purchase Savings Plans, manage your Savings Plans, and view your historical AWS usage.`,`budgets-managing|You can use AWS Budgets to monitor your aggregate utilization and coverage metrics for your Reserved Instances (RIs) or Savings Plans.`,`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`])]},{id:`4.2-K4`,concepts:[n(`With On-Demand Instances you pay for compute capacity by the second with no long-term commitments, and you pay only for the seconds the instance is in the running state, with a 60-second minimum. They are the baseline that the other options reduce.`,[`ec2-on-demand`,`ec2-purchasing`],[`ec2-on-demand|With On-Demand Instances, you pay for compute capacity by the second with no long-term commitments.`,`ec2-on-demand|You pay only for the seconds that your On-Demand Instances are in the running state, with a 60-second minimum.`]),n(`Savings Plans give savings beyond On-Demand rates in exchange for a commitment to a specified amount of compute usage, measured per hour, for a one or three year term. The commitment cannot be changed or cancelled during the term. There are Compute, Database, EC2 Instance and SageMaker AI plan types, and the general Savings Plans description lists All upfront, Partial upfront and No upfront payment options. The Database Savings Plans pricing page describes those plans as applying with no upfront payment.`,[`savings-plans`,`savings-plans-types`,`savings-plans-vs-ri`,`savings-plans-database`],[`savings-plans|Savings Plans provide savings beyond On-Demand rates in exchange for a commitment of using a specified amount of compute power (measured per hour) for a one or three year period.`,`savings-plans-types|AWS offers four types of Savings Plans: Compute Savings Plans, Database Savings Plans, EC2 Instance Savings Plans, and SageMaker AI Savings Plans.`,`savings-plans-types|The terms of the commitment can't be changed after purchase.`,`savings-plans-vs-ri|Savings Plans offer lower prices compared to On-Demand pricing in exchange for a commitment, and can't be cancelled during the term.`,`savings-plans|You can pay for your commitment using All upfront, Partial upfront, or No upfront payment options.`,`savings-plans-database|regardless of engine, instance family, size, deployment option, or AWS Region with no upfront payment.`],{newer:[`database-savings-plans`],allow:[`one`,`four`]}),n(`Compute Savings Plans are the most flexible: they apply to EC2 usage regardless of instance family, size, Region, operating system or tenancy, and also to Fargate and Lambda usage, so you can move a workload between instance families or Regions, or from EC2 to Fargate, without losing the discount.`,`savings-plans-types`,[`Compute Savings Plans provide the most flexibility`,`They also apply to your Fargate and Lambda usage.`,`With Compute Savings Plans, you can move a workload from c5 to m5, shift your usage from EU (Ireland) to EU (London), or migrate your application from Amazon EC2 to Amazon ECS using Fargate at any time.`]),n(`EC2 Instance Savings Plans are less flexible than Compute Savings Plans: you commit to a specific instance family in a chosen Region, and the plan applies regardless of instance size, operating system and tenancy within that family in that Region. Database Savings Plans apply to AWS database services such as Aurora, RDS, DynamoDB and ElastiCache instead of to compute.`,`savings-plans-types`,[`in exchange for a commitment to a specific instance family in a chosen AWS Region (for example, m5 in Virginia).`,`These plans automatically apply to usage regardless of instance size (for example, m5.xlarge, m5.2xlarge, etc.), OS (for example, Windows, Linux, etc.), and tenancy (Host, Dedicated, Default) within the specified family in a Region.`,`Database Savings Plans provide flexibility to use AWS database services while reducing costs`],{newer:[`database-savings-plans`]}),n(`Reserved Instances commit to a specific instance configuration, including instance type and Region, for a term of 1 or 3 years. AWS recommends Savings Plans over Reserved Instances. Savings Plans do not provide capacity reservations.`,[`ec2-purchasing`,`ec2-reserved-instances`,`savings-plans-vs-ri`],[`ec2-purchasing|Reserved Instances – Reduce your Amazon EC2 costs by making a commitment to a consistent instance configuration, including instance type and Region, for a term of 1 or 3 years.`,`ec2-reserved-instances|We recommend Savings Plans over Reserved Instances.`,`savings-plans-vs-ri|Savings Plans doesn't provide capacity reservations, but you can allocate On-Demand Capacity Reservation (ODCR) for your needs and your Savings Plans will apply.`]),n(`A Reserved Instance has an offering class and a scope. A Standard Reserved Instance provides a more significant discount than a Convertible one but cannot be exchanged; a Convertible Reserved Instance can be exchanged during the term. The scope does not affect the price, and only a zonal Reserved Instance reserves capacity. A regional Reserved Instance applies to usage in any Availability Zone in the Region and gives instance size flexibility within the family (Amazon Linux/Unix with default tenancy only); a zonal one applies to the specified Availability Zone and instance size only.`,[`ec2-ri-classes`,`ec2-ri-scope`],[`ec2-ri-classes|A Standard Reserved Instance provides a more significant discount than a Convertible Reserved Instance, but you can't exchange a Standard Reserved Instance.`,`ec2-ri-classes|Can be exchanged during the term for another Convertible Reserved Instance with new attributes, including instance family, instance type, platform, scope, or tenancy.`,`ec2-ri-scope|You pay the same price for a regional or zonal Reserved Instance.`,`ec2-ri-scope|A regional Reserved Instance does not reserve capacity.`,`ec2-ri-scope|A zonal Reserved Instance reserves capacity in the specified Availability Zone.`,`ec2-ri-scope|The Reserved Instance discount applies to instance usage in any Availability Zone in the specified Region.`,`ec2-ri-scope|The Reserved Instance discount applies to instance usage within the instance family, regardless of size.`,`ec2-ri-scope|Only supported on Amazon Linux/Unix Reserved Instances with default tenancy.`,`ec2-ri-scope|No Availability Zone flexibility—the Reserved Instance discount applies to instance usage in the specified Availability Zone only.`,`ec2-ri-scope|No instance size flexibility—the Reserved Instance discount applies to instance usage for the specified instance family and instance size only.`]),n(`A Spot Instance uses spare EC2 capacity that is available for less than the On-Demand price. Amazon EC2 might interrupt it, so it is a cost-effective choice if you can be flexible about when your applications run and your applications can be interrupted.`,[`ec2-spot`,`ec2-spot-interruptions`],[`ec2-spot|A Spot Instance is an instance that uses spare EC2 capacity that is available for less than the On-Demand price.`,`ec2-spot|Spot Instances are a cost-effective choice if you can be flexible about when your applications run and if your applications can be interrupted.`,`ec2-spot-interruptions|It is always possible that your Spot Instance might be interrupted.`]),n(`Amazon EC2 issues a Spot Instance interruption notice, a warning two minutes before it stops or terminates the instance, so a fault-tolerant application can react; with hibernation as the interruption behaviour there is no two-minute warning because hibernation begins immediately.`,`ec2-spot-notices`,[`A Spot Instance interruption notice is a warning that is issued two minutes before Amazon EC2 stops or terminates your Spot Instance.`,`If you specify hibernation as the interruption behavior, you receive an interruption notice, but you do not receive a two-minute warning because the hibernation process begins immediately.`]),n(`Dedicated Hosts are a physical host fully dedicated to running your instances, and you can bring your existing per-socket, per-core or per-VM software licences to reduce costs.`,`ec2-purchasing`,[`Dedicated Hosts – Pay for a physical host that is fully dedicated to running your instances, and bring your existing per-socket, per-core, or per-VM software licenses to reduce costs.`]),n(`Capacity Reservations reserve compute capacity in a specific Availability Zone for any duration. An immediate-use reservation has no term commitment and can be cancelled at any time, but it is charged at the equivalent On-Demand rate whether or not you run instances in it, and it gives no billing discount by itself. Savings Plans can apply to the usage that runs in it.`,[`ec2-capacity-reservations`,`ec2-capacity-reservation-billing`,`savings-plans-vs-ri`],[`ec2-capacity-reservations|Amazon EC2 Capacity Reservations allow you to reserve compute capacity for your Amazon EC2 instances in a specific Availability Zone for any duration.`,`ec2-capacity-reservations|If you request a Capacity Reservation for immediate use, the Capacity Reservation becomes available for use immediately and there is no term commitment.`,`ec2-capacity-reservations|You can modify the Capacity Reservation at any time, and you can cancel it at any time to release the reserved capacity and to stop incurring charges.`,`ec2-capacity-reservation-billing|Capacity Reservations are charged at the equivalent On-Demand rate whether you run instances in reserved capacity or not, including any applicable regional surcharge for Dedicated Instances.`,`ec2-capacity-reservations|No billing discount.`,`savings-plans-vs-ri|Savings Plans doesn't provide capacity reservations, but you can allocate On-Demand Capacity Reservation (ODCR) for your needs and your Savings Plans will apply.`])],services:[`Savings Plans`,`Amazon EC2`],design:[n(`Cue: you can commit to a usage amount but not to an instance configuration → Savings Plans; you can commit to a consistent instance configuration → Reserved Instances; the instance family may change → Compute Savings Plans; flexible about when it runs and can be interrupted → Spot; no long-term commitment wanted → On-Demand Instances; per-socket or per-core licences → Dedicated Hosts. The full comparison is in the Don't confuse section below.`,[`ec2-purchasing`,`savings-plans-types`,`ec2-spot`,`ec2-on-demand`],[`ec2-purchasing|If you can't make a commitment to a specific instance configuration, but you can commit to a usage amount, purchase Savings Plans to reduce your On-Demand Instance costs.`,`ec2-purchasing|Reserved Instances – Reduce your Amazon EC2 costs by making a commitment to a consistent instance configuration, including instance type and Region, for a term of 1 or 3 years.`,`savings-plans-types|With Compute Savings Plans, you can move a workload from c5 to m5, shift your usage from EU (Ireland) to EU (London), or migrate your application from Amazon EC2 to Amazon ECS using Fargate at any time.`,`ec2-spot|Spot Instances are a cost-effective choice if you can be flexible about when your applications run and if your applications can be interrupted.`,`ec2-on-demand|With On-Demand Instances, you pay for compute capacity by the second with no long-term commitments.`,`ec2-purchasing|Dedicated Hosts – Pay for a physical host that is fully dedicated to running your instances, and bring your existing per-socket, per-core, or per-VM software licenses to reduce costs.`])]}],cues:[e(`commit to a usage amount but the instance types will change`,`Compute Savings Plans`,n(`If you cannot commit to an instance configuration but can commit to a usage amount, purchase Savings Plans.`,`ec2-purchasing`,[`If you can't make a commitment to a specific instance configuration, but you can commit to a usage amount, purchase Savings Plans to reduce your On-Demand Instance costs.`])),e(`Savings Plan discount must also cover Fargate or Lambda`,`Compute Savings Plans`,n(`Compute Savings Plans also apply to Fargate and Lambda usage.`,`savings-plans-types`,[`They also apply to your Fargate and Lambda usage.`])),e(`reserve capacity in one specific Availability Zone`,`Zonal Reserved Instances or Capacity Reservations`,n(`A zonal Reserved Instance reserves capacity in the specified Availability Zone; a regional one does not.`,`ec2-ri-scope`,[`A regional Reserved Instance does not reserve capacity.`,`A zonal Reserved Instance reserves capacity in the specified Availability Zone.`])),e(`fault-tolerant batch processing that can be interrupted and restarted`,`Spot Instances`,n(`Spot is cost-effective if you can be flexible about when applications run and they can be interrupted.`,`ec2-spot`,[`Spot Instances are a cost-effective choice if you can be flexible about when your applications run and if your applications can be interrupted.`])),e(`bring existing per-socket or per-core software licences`,`Dedicated Hosts`,n(`Dedicated Hosts let you bring your existing per-socket, per-core or per-VM software licences.`,`ec2-purchasing`,[`Dedicated Hosts – Pay for a physical host that is fully dedicated to running your instances, and bring your existing per-socket, per-core, or per-VM software licenses to reduce costs.`])),e(`short-term, unpredictable workload with no commitment`,`On-Demand Instances`,n(`On-Demand Instances are paid by the second for the instances you launch.`,`ec2-purchasing`,[`On-Demand Instances – Pay, by the second, for the instances that you launch.`])),e(`check whether purchased commitments are actually used`,`AWS Budgets (RI and Savings Plans utilisation and coverage)`,n(`Budgets monitors aggregate utilisation and coverage for Reserved Instances and Savings Plans.`,`budgets-managing`,[`You can use AWS Budgets to monitor your aggregate utilization and coverage metrics for your Reserved Instances (RIs) or Savings Plans.`]))],examples:[],confuse:[`savings-plans-ri-spot`],azure:[{concept:`Microsoft Cost Management`,aws:`AWS Billing and Cost Management (Cost Explorer, Budgets)`,mapping:n(`Learn pairs AWS Billing and Cost Management with Microsoft Cost Management, which helps you understand your Azure bill, monitor and control spending and optimise resource use. On AWS, Cost Explorer is also where the Savings Plans recommendation is viewed.`,[`learn-hub`,`savings-plans`],[`learn-hub|AWS Billing and Cost Management Microsoft Cost Management Cost Management helps you understand your Azure invoice or bill.`,`learn-hub|It also helps you manage your billing account and subscriptions, monitor and control Azure spending, and optimize resource use.`,`savings-plans|To get started, use AWS Cost Explorer to view your recommended Savings Plans commitment, refresh Savings Plans recommendations, purchase Savings Plans, manage your Savings Plans, and view your historical AWS usage.`]),breaks:n(`Learn pairs Microsoft Cost Management with the AWS billing tools. AWS lists the EC2 purchasing options (On-Demand, Savings Plans, Reserved Instances, Spot, Dedicated Hosts, Capacity Reservations) as options to optimize your costs for Amazon EC2.`,[`ec2-purchasing`,`learn-hub`],[`ec2-purchasing|You can use the following options to optimize your costs for Amazon EC2`,`learn-hub|AWS Billing and Cost Management Microsoft Cost Management Cost Management helps you understand your Azure invoice or bill.`])}]},c={building:`db-cost-desk`,overview:[n(`What changes for databases is what you look for. For databases that means tagging DB instances and snapshots so their spend can be attributed, using the consolidated bill of an organisation to share commitments, and using Cost Explorer, Budgets and the Cost and Usage Report to see database spend. Ledger Office introduced each tool and Counting House applied them to compute; this building applies them to databases.`,[`rds-tagging`,`cost-alloc-tags`,`ce-what-is`,`consolidated-billing`,`budgets-managing`,`cur-what-is`],[`rds-tagging|An Amazon RDS tag is a name-value pair that you define and associate with an Amazon RDS resource such as a DB instance or DB snapshot.`,`cost-alloc-tags|You can use tags to organize your resources, and cost allocation tags to track your AWS costs on a detailed level.`,`ce-what-is|AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`,`consolidated-billing|This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`,`budgets-managing|Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`,`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`])],bullets:[{id:`4.3-K1`,concepts:[n(`An Amazon RDS tag is a name-value pair that you define and associate with an RDS resource such as a DB instance or DB snapshot. To see database spend by team or application, tag the databases and activate the tag as a cost allocation tag, because you must activate a tag before it appears in Cost Explorer or on a cost allocation report.`,[`rds-tagging`,`cost-alloc-tags`],[`rds-tagging|An Amazon RDS tag is a name-value pair that you define and associate with an Amazon RDS resource such as a DB instance or DB snapshot.`,`cost-alloc-tags|You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`]),n(`Multi-account billing helps database commitments. In consolidated billing the management account pays the charges of all member accounts, and the combined usage shares Reserved Instance discounts and Savings Plans, so a database commitment bought in one account can benefit others in the organisation.`,`consolidated-billing`,[`Every organization in AWS Organizations has a management account that pays the charges of all the member accounts.`,`This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`])],services:[`AWS Organizations`],design:[n(`Cue: "attribute database costs to each application team" → tag the databases and activate cost allocation tags; "share a database commitment across many accounts" → consolidated billing in AWS Organizations.`,[`rds-tagging`,`consolidated-billing`],[`rds-tagging|You can use tags to add metadata to your Amazon RDS resources.`,`consolidated-billing|This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`])]},{id:`4.3-K2`,concepts:[n(`Cost Explorer shows what databases cost over time: you can view and analyse costs and usage, forecast how much you are likely to spend, and get recommendations for which Reserved Instances to purchase. Its charts, tables and reports can be built with filters, groupings and dates.`,`ce-what-is`,[`AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`,`You can view data for up to the last 13 months, forecast how much you're likely to spend for the next 18 months, and get recommendations for what Reserved Instances to purchase.`,`including filters, groupings, and dates to reflect the analysis.`],{allow:[`13`,`18`]}),n(`Budgets can alert when database spend crosses a limit, and can monitor the utilisation and coverage of Reserved Instances or Savings Plans, which shows whether a database commitment is being used.`,`budgets-managing`,[`Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`,`You can use AWS Budgets to monitor your aggregate utilization and coverage metrics for your Reserved Instances (RIs) or Savings Plans.`]),n(`The Cost and Usage Report is the most comprehensive set of cost and usage data available, published to an S3 bucket you own, and it can be broken down by tags you define, so database tags show up in the line items.`,`cur-what-is`,[`AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`,`You can receive reports that break down your costs by the hour, day, or month, by product or product resource, or by tags that you define yourself.`]),n(`There are different ways to commit for database usage. Reserved DB instances are a billing discount applied to the use of certain on-demand DB instances, for a one- or three-year term, and the discount is tied to instance type and Region. Database Savings Plans offer flexibility to use AWS database services while reducing costs, and also apply to serverless usage.`,[`rds-reserved`,`savings-plans-types`],[`rds-reserved|Reserved DB instances are not physical instances, but rather a billing discount applied to the use of certain on-demand DB instances in your account.`,`rds-reserved|Discounts for reserved DB instances are tied to instance type and AWS Region.`,`rds-reserved|Using reserved DB instances, you can reserve a DB instance for a one- or three-year term.`,`savings-plans-types|Database Savings Plans provide flexibility to use AWS database services while reducing costs`,`savings-plans-types|These plans automatically apply to the latest provisioned instance generations regardless of engine, instance family, size, Availability Zone (AZ), or Region, and also apply to serverless usage.`],{newer:[`database-savings-plans`],allow:[`one`]})],services:[`AWS Cost Explorer`,`AWS Budgets`,`AWS Cost and Usage Report`],design:[n(`Cue: "which database costs are growing?" → Cost Explorer; "alert when the database bill passes a limit" → Budgets; "line-item database costs analysed with a query tool" → Cost and Usage Report; "steady database usage" → a reserved DB instance or Database Savings Plan.`,[`ce-what-is`,`budgets-managing`,`cur-what-is`,`rds-reserved`],[`ce-what-is|AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`,`budgets-managing|Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`,`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`,`rds-reserved|Reserved DB instances are not physical instances, but rather a billing discount applied to the use of certain on-demand DB instances in your account.`],{newer:[`database-savings-plans`]})]}],cues:[e(`attribute database spend to teams`,`Tag DB instances and activate cost allocation tags`,n(`A tag is a name-value pair on a resource, and cost allocation tags must be activated before they appear in Cost Explorer.`,`cost-alloc-tags`,[`You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`])),e(`steady RDS usage for a long term, reduce the on-demand cost`,`Reserved DB instances (or a Database Savings Plan)`,n(`Reserved DB instances are a billing discount for a one- or three-year term, tied to instance type and Region.`,`rds-reserved`,[`Using reserved DB instances, you can reserve a DB instance for a one- or three-year term.`,`Discounts for reserved DB instances are tied to instance type and AWS Region.`])),e(`commit to database usage but engine and size may change`,`Database Savings Plans`,n(`Database Savings Plans automatically apply to the latest provisioned instance generations regardless of engine, instance family, size, Availability Zone or Region, and also to serverless usage.`,`savings-plans-types`,[`These plans automatically apply to the latest provisioned instance generations regardless of engine, instance family, size, Availability Zone (AZ), or Region, and also apply to serverless usage.`],{newer:[`database-savings-plans`]})),e(`alert when database spend approaches a limit`,`AWS Budgets`,n(`Budgets alerts when costs approach or exceed your threshold.`,`budgets-managing`,[`Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`])),e(`detailed database billing data delivered to S3`,`AWS Cost and Usage Report`,n(`CUR is published to an S3 bucket you own, with breakdown by tags you define.`,`cur-what-is`,[`You can receive reports that break down your costs by the hour, day, or month, by product or product resource, or by tags that you define yourself.`]))],examples:[],confuse:[],azure:[{concept:`Microsoft Cost Management`,aws:`AWS Billing and Cost Management (Cost Explorer, Budgets)`,mapping:n(`Learn pairs AWS Billing and Cost Management with Microsoft Cost Management, which helps you monitor and control Azure spending and optimise resource use. On AWS, Cost Explorer also gives recommendations for which Reserved Instances to purchase.`,[`learn-hub`,`ce-what-is`],[`learn-hub|It also helps you manage your billing account and subscriptions, monitor and control Azure spending, and optimize resource use.`,`ce-what-is|You can view data for up to the last 13 months, forecast how much you're likely to spend for the next 18 months, and get recommendations for what Reserved Instances to purchase.`],{allow:[`13`,`18`]}),breaks:n(`On AWS, the discount for a reserved DB instance is tied to instance type and Region, whereas a Database Savings Plan automatically applies to the latest provisioned instance generations regardless of engine, instance family, size, Availability Zone or Region, and also to serverless usage.`,[`rds-reserved`,`savings-plans-types`,`learn-hub`],[`rds-reserved|Discounts for reserved DB instances are tied to instance type and AWS Region.`,`savings-plans-types|These plans automatically apply to the latest provisioned instance generations regardless of engine, instance family, size, Availability Zone (AZ), or Region, and also apply to serverless usage.`,`learn-hub|AWS Billing and Cost Management Microsoft Cost Management Cost Management helps you understand your Azure invoice or bill.`],{newer:[`database-savings-plans`]})}]},l={building:`distribution-office`,overview:[n(`Where compute runs, and how available it must be, both change the bill. A {{term:region}} is a physical location where AWS clusters data centers, and each group of logical data centers is an {{term:availability-zone}}. Edge and hybrid options (CloudFront edge locations, Local Zones, Wavelength, Outposts) put compute or content closer to users or to your premises. And not every workload needs the same availability: a production system usually justifies the cost of running across Availability Zones, while a development environment often does not.`,[`global-infra`,`cloudfront-what-is`,`outposts-what-is`,`waf-cost-demand`],[`global-infra|AWS has the concept of a Region, which is a physical location around the world where we cluster data centers.`,`global-infra|We call each group of logical data centers an Availability Zone.`,`cloudfront-what-is|CloudFront delivers your content through a worldwide network of data centers called edge locations.`,`outposts-what-is|AWS Outposts is a fully managed service that extends AWS infrastructure, services, APIs, and tools to customer premises.`,`waf-cost-demand|The economic benefits of just-in-time supply should be balanced against the need to provision to account for resource failures, high availability, and provision time.`])],bullets:[{id:`4.2-K3`,concepts:[n(`A Region is where you place the workload. Select a Region that has the AWS services and features you need, and you can lower network latency by selecting a Region that is close to most of your users. An account can create resources in the Regions that meet your requirements, for example to be closer to customers or to meet legal requirements.`,`regions-and-azs`,[`For example, select a Region that has the AWS services and features that you need.`,`Also, you can lower network latency when you select a Region that is close to the majority of your users.`,`For example, you want to create resources in Europe to be closer to your European customers or to meet legal requirements.`]),n(`Region choice is also a cost choice. Resource pricing is different in each Region because of local market conditions such as the cost of land, fiber, electricity and taxes, and AWS says to use Regions that provide lower prices for AWS services to deploy your workloads if you have no obligations in data privacy, security and business requirements.`,`waf-region-cost`,[`Resource pricing may be different in each Region.`,`Each AWS Region operates within local market conditions, and resource pricing is different in each Region due to differences in the cost of land, fiber, electricity, and taxes, for example.`,`Use Regions that provide lower prices for AWS services to deploy your workloads if you have no obligations in data privacy, security and business requirements.`]),n(`Availability Zones are the groups of logical data centers inside a Region. EC2 Auto Scaling can balance instances evenly across the Availability Zones you choose as the group scales.`,[`global-infra`,`asg-what-is`],[`global-infra|We call each group of logical data centers an Availability Zone.`,`asg-what-is|You can specify multiple Availability Zones for your Auto Scaling group, and Amazon EC2 Auto Scaling balances your instances evenly across the Availability Zones as the group scales.`])],services:[`Amazon EC2`],design:[n(`Cue: "lowest latency for users in one geography" → a Region close to them; "must stay in a specific country" → a Region in that country; "survive a data center failure" → more than one Availability Zone.`,[`regions-and-azs`,`asg-what-is`],[`regions-and-azs|Also, you can lower network latency when you select a Region that is close to the majority of your users.`,`asg-what-is|You can specify multiple Availability Zones for your Auto Scaling group, and Amazon EC2 Auto Scaling balances your instances evenly across the Availability Zones as the group scales.`])]},{id:`4.2-K5`,concepts:[n(`Edge processing moves work toward the user. CloudFront delivers content through edge locations and routes each request to the edge location that provides the lowest latency, retrieving content from the origin only when it is not already cached there. That keeps repeated requests off the origin.`,`cloudfront-what-is`,[`CloudFront delivers your content through a worldwide network of data centers called edge locations.`,`When a user requests content that you're serving with CloudFront, the request is routed to the edge location that provides the lowest latency (time delay), so that content is delivered with the best possible performance.`,`If the content is already in the edge location with the lowest latency, CloudFront delivers it immediately.`]),n(`Local Zones put compute close to end users for low-latency applications such as real-time gaming and live streaming. AWS resources in Local Zones have different prices than they do in the parent AWS Region, so check prices before choosing one.`,`local-zones`,[`You can use Local Zones to provide your users with low-latency access to your applications.`,`Run low-latency applications at the edge — Build and deploy applications close to end users to enable real-time gaming, live streaming, augmented and virtual reality (AR/VR), virtual workstations, and more.`,`AWS resources in Local Zones have different prices than they do in parent AWS Regions.`]),n(`Wavelength deploys standard AWS compute and storage services to the edge of communications service providers' networks, to deliver low latency to mobile devices and end users. You extend a VPC to one or more Wavelength Zones and run EC2 instances there while communicating back to services in the parent Region.`,`wavelength-what-is`,[`Wavelength deploys standard AWS compute and storage services to the edge of communications service providers' (CSP) networks.`,`You can extend a virtual private cloud (VPC) to one or more Wavelength Zones.`,`You can then use AWS resources such as Amazon Elastic Compute Cloud (Amazon EC2) instances to run the applications that require low latency or edge resiliency within the Wavelength Zone, while seamlessly communicating back to your existing AWS services deployed in the parent AWS Region.`])],services:[`Amazon CloudFront`,`AWS Wavelength`],design:[n(`Cue: "cache static content near users and cut load on the origin" → CloudFront; "low-latency access for users near a large population or industry center" → Local Zones; "mobile devices on a carrier network" → Wavelength. Resources in Local Zones can be priced differently from the parent Region.`,[`cloudfront-what-is`,`local-zones`,`wavelength-what-is`],[`cloudfront-what-is|If the content is already in the edge location with the lowest latency, CloudFront delivers it immediately.`,`local-zones|AWS resources in Local Zones have different prices than they do in parent AWS Regions.`,`wavelength-what-is|AWS Wavelength enables developers to build applications that require edge computing infrastructure to deliver low latency to mobile devices and end users or increase the resiliency of their existing edge applications.`])]},{id:`4.2-K6`,concepts:[n(`AWS Outposts extends AWS infrastructure, services, APIs and tools to customer premises. An Outpost is a pool of AWS compute and storage capacity deployed at your site, operated, monitored and managed by AWS as part of an AWS Region. Applications on premises use the same programming interfaces as in AWS Regions and use local compute and storage for lower latency and local data processing.`,`outposts-what-is`,[`AWS Outposts is a fully managed service that extends AWS infrastructure, services, APIs, and tools to customer premises.`,`An Outpost is a pool of AWS compute and storage capacity deployed at a customer site.`,`AWS operates, monitors, and manages this capacity as part of an AWS Region.`]),n(`Instances in Outpost subnets communicate with instances in the AWS Region using private IP addresses, all within the same VPC, so an Outpost is an extension of a Region VPC rather than a separate network. Hybrid is the answer when the requirement names on-premises latency or local data processing; if it is only a one-time data move, look at Haul & Hybrid Customs instead.`,`outposts-what-is`,[`Instances in Outpost subnets communicate with other instances in the AWS Region using private IP addresses, all within the same VPC.`])],services:[`AWS Outposts`],design:[n(`Cue: "run AWS services on premises for low-latency local processing, with the same APIs" → Outposts; contrast with Wavelength (AWS compute and storage at the edge of communications service providers' networks) and Local Zones (resources placed close to large population and industry centers).`,[`outposts-what-is`,`wavelength-what-is`,`local-zones`],[`outposts-what-is|By providing local access to AWS managed infrastructure, AWS Outposts enables customers to build and run applications on premises using the same programming interfaces as in AWS Regions, while using local compute and storage resources for lower latency and local data processing needs.`,`wavelength-what-is|Wavelength deploys standard AWS compute and storage services to the edge of communications service providers' (CSP) networks.`,`local-zones|AWS Local Zones places compute, storage, database, and other select AWS resources close to large population and industry centers.`])]},{id:`4.2-S4`,concepts:[n(`Match the availability to the workload class. The reliability pillar defines availability as the percentage of time that a workload is available for use, and the cost pillar says the benefit of just-in-time supply must be balanced against provisioning for resource failures, high availability and provision time. So a production workload that cannot tolerate an outage pays for redundancy, and a non-production workload usually should not.`,[`waf-availability`,`waf-cost-demand`],[`waf-availability|Availability is the percentage of time that a workload is available for use.`,`waf-cost-demand|The economic benefits of just-in-time supply should be balanced against the need to provision to account for resource failures, high availability, and provision time.`]),n(`For production, the usual building blocks are Multi-AZ: an RDS Multi-AZ deployment provisions and maintains a synchronous standby replica in a different Availability Zone, and an Auto Scaling group balances instances across Availability Zones. For disaster recovery, the strategies range from the low cost and low complexity of making backups to more complex strategies using multiple active Regions, so pick the cheapest that meets the recovery objectives (Disaster Bunker).`,[`rds-multi-az-instance`,`asg-what-is`,`dr-options`],[`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`,`asg-what-is|You can specify multiple Availability Zones for your Auto Scaling group, and Amazon EC2 Auto Scaling balances your instances evenly across the Availability Zones as the group scales.`,`dr-options|Disaster recovery strategies available to you within AWS can be broadly categorized into four approaches, ranging from the low cost and low complexity of making backups to more complex strategies using multiple active Regions.`],{allow:[`four`]}),n(`For non-production, cost levers are to run fewer copies and to stop what is not in use. You are not charged for usage or data transfer fees for an EC2 instance when it is stopped, though charges are incurred for the storage of any attached EBS volumes, and Elastic IP addresses also incur charges regardless of the instance's state. A stopped RDS DB instance is not charged for DB instance hours but is charged for provisioned storage and backup storage, and it is started again automatically if you do not start it within seven consecutive days. Scheduled scaling can also lower the desired capacity at predictable times.`,[`ec2-lifecycle`,`rds-stop`,`asg-scheduled`],[`ec2-lifecycle|You are not charged for usage or data transfer fees for your instance when it is stopped.`,`ec2-lifecycle|Charges are incurred for the storage of any Amazon EBS volumes.`,`ec2-lifecycle|Some AWS resources, such as Amazon EBS volumes and Elastic IP addresses, incur charges regardless of the instance's state.`,`rds-stop|While the instance is stopped, you're not charged for DB instance hours.`,`rds-stop|While your DB instance is stopped, you are charged for provisioned storage (including Provisioned IOPS).`,`rds-stop|If you don't manually start your DB instance after it is stopped for seven consecutive days, RDS automatically starts your DB instance for you.`,`asg-scheduled|You create scheduled actions that increase or decrease your group's desired capacity at specific times.`])],services:[`Amazon EC2`,`Amazon RDS`],design:[n(`Cue: "production database must survive an Availability Zone failure" → Multi-AZ; "development environment, minimise cost" → a single Availability Zone, smaller resources, stopped when unused; "disaster recovery with a loose recovery objective" → the cheaper DR strategies. This is study guidance: the exam wording decides.`,[`rds-multi-az-instance`,`ec2-lifecycle`,`dr-options`],[`rds-multi-az-instance|Amazon RDS provides high availability and failover support for DB instances using Multi-AZ deployments with a single standby DB instance.`,`ec2-lifecycle|You are not charged for usage or data transfer fees for your instance when it is stopped.`,`dr-options|Disaster recovery strategies available to you within AWS can be broadly categorized into four approaches, ranging from the low cost and low complexity of making backups to more complex strategies using multiple active Regions.`],{allow:[`four`]})]}],cues:[e(`lower latency for most users by choosing where to deploy`,`A Region close to the majority of users`,n(`Selecting a Region close to the majority of your users lowers network latency.`,`regions-and-azs`,[`Also, you can lower network latency when you select a Region that is close to the majority of your users.`])),e(`cache content at locations near users to reduce origin load`,`Amazon CloudFront edge locations`,n(`CloudFront delivers content from edge locations and retrieves it from the origin only if it is not cached there.`,`cloudfront-what-is`,[`If the content is already in the edge location with the lowest latency, CloudFront delivers it immediately.`])),e(`low-latency application close to end users in a metro area`,`AWS Local Zones`,n(`Local Zones provide users with low-latency access to your applications.`,`local-zones`,[`You can use Local Zones to provide your users with low-latency access to your applications.`])),e(`low latency to mobile devices on a carrier network`,`AWS Wavelength`,n(`Wavelength deploys AWS compute and storage at the edge of communications service providers' networks.`,`wavelength-what-is`,[`Wavelength deploys standard AWS compute and storage services to the edge of communications service providers' (CSP) networks.`])),e(`run AWS infrastructure and APIs in our own data centre for local processing`,`AWS Outposts`,n(`Outposts extends AWS infrastructure, services, APIs and tools to customer premises.`,`outposts-what-is`,[`AWS Outposts is a fully managed service that extends AWS infrastructure, services, APIs, and tools to customer premises.`])),e(`development instances idle outside working hours`,`Stop the instances (no instance usage charge while stopped)`,n(`You are not charged for usage for a stopped instance, but EBS storage is still charged.`,`ec2-lifecycle`,[`You are not charged for usage or data transfer fees for your instance when it is stopped.`,`Charges are incurred for the storage of any Amazon EBS volumes.`]))],examples:[],confuse:[],azure:[{concept:`Azure Local (formerly Azure Stack HCI)`,aws:`AWS Outposts`,mapping:n(`Learn pairs AWS Outposts with Azure Local (formerly Azure Stack HCI): both deliver cloud-managed, on-premises infrastructure for low-latency workloads and data-residency requirements.`,[`learn-compute`,`outposts-what-is`],[`learn-compute|Both services deliver cloud-managed, on-premises infrastructure for low-latency workloads and data-residency requirements.`,`outposts-what-is|AWS Outposts is a fully managed service that extends AWS infrastructure, services, APIs, and tools to customer premises.`]),breaks:n(`Learn describes Azure Local as a validated hyperconverged infrastructure platform managed through the Azure portal. On AWS, an Outpost is a pool of AWS compute and storage capacity deployed at a customer site, which AWS operates, monitors and manages as part of an AWS Region.`,[`learn-compute`,`outposts-what-is`],[`learn-compute|Azure Local provides a validated hyperconverged infrastructure (HCI) platform managed through the Azure portal.`,`outposts-what-is|An Outpost is a pool of AWS compute and storage capacity deployed at a customer site.`,`outposts-what-is|AWS operates, monitors, and manages this capacity as part of an AWS Region.`])}]},u={building:`elastic-mint`,overview:[n(`Lambda runs code without provisioning or managing servers, Fargate runs containers without managing servers or clusters of EC2 instances, and EC2 gives you the instance itself, with Auto Scaling to add and remove instances as demand changes. A load balancer spreads the traffic across the targets. This building is about choosing among them and scaling them.`,[`lambda-welcome`,`fargate-ecs`,`asg-what-is`,`elb-what-is`],[`lambda-welcome|With Lambda, you can run code without provisioning or managing servers.`,`fargate-ecs|AWS Fargate is a technology that you can use with Amazon ECS to run containers without having to manage servers or clusters of Amazon EC2 instances.`,`asg-what-is|If you specify scaling policies, then Amazon EC2 Auto Scaling can launch or terminate instances as demand on your application increases or decreases.`,`elb-what-is|Elastic Load Balancing automatically distributes your incoming traffic across multiple targets, such as EC2 instances, containers, and IP addresses, in one or more Availability Zones.`])],beyondProject:[n(`Your visitor counter runs on Lambda. The SAA cost question is when Lambda is the cheaper choice than EC2 or Fargate. Pricing for {{rename:lambda-event-function}} is based on the number of requests served and the duration your code runs, measured in GB-seconds. Code can run for up to 15 minutes in a single invocation, and the function timeout is 900 seconds (15 minutes); a Lambda Managed Instances function invoked asynchronously or through an event source mapping (other than Amazon MQ and Amazon DocumentDB) can run for up to 90 minutes. For long-running or steady high-volume work, compare the cost against EC2 or Fargate. These limits are documented and can change.`,[`lambda-pricing`,`lambda-quotas`],[`lambda-pricing|Lambda Event Functions are priced based on the number of requests served and the duration your code runs, measured in GB-seconds.`,`lambda-quotas|Code can run for up to 15 minutes in a single invocation (up to 90 minutes for Lambda Managed Instances functions invoked asynchronously or through any event source mapping except Amazon MQ and Amazon DocumentDB) and a single function can use up to 10,240 MB of memory.`,`lambda-quotas|Function timeout 900 seconds (15 minutes).`],{newer:[`lambda-managed-instances`,`lambda-managed-instances-90min`]}),n(`Concurrency settings can add cost. There is no charge for configuring reserved concurrency for a function, but provisioned concurrency incurs additional charges to your account, so it is the option to remove when the question asks for the lowest cost and can tolerate cold starts.`,`lambda-concurrency`,[`There is no charge for configuring reserved concurrency for an Event Function.`,`Configuring provisioned concurrency incurs charges to your AWS account.`])],bullets:[{id:`4.2-K8`,concepts:[n(`Serverless computing removes the idle server. Lambda manages execution environments, scaling, routing and fault tolerance, and each invocation runs independently with no shared state, scaling horizontally to match demand.`,`lambda-welcome`,[`Lambda manages execution environments, scaling, routing, and fault tolerance.`,`Each invocation runs independently with no shared state, scaling horizontally to match demand.`]),n(`With Fargate you package your application in containers, specify the CPU and memory requirements, define networking and IAM policies, and launch the application; this removes the need to choose server types, decide when to scale your clusters, or optimize cluster packing.`,`fargate-ecs`,[`This removes the need to choose server types, decide when to scale your clusters, or optimize cluster packing.`,`When you run your tasks and services with Fargate, you package your application in containers, specify the CPU and memory requirements, define networking and IAM policies, and launch the application.`]),n(`ECS runs containerised applications, and ECS service auto scaling increases or decreases the desired number of tasks automatically.`,[`ecs-what-is`,`ecs-autoscaling`],[`ecs-what-is|Amazon Elastic Container Service (Amazon ECS) is a fully managed container orchestration service that helps you easily deploy, manage, and scale containerized applications.`,`ecs-autoscaling|Automatic scaling is the ability to increase or decrease the desired number of tasks in your Amazon ECS service automatically.`])],services:[`AWS Lambda`,`AWS Fargate`,`Amazon EC2`],design:[n(`Cue: "event-driven, short tasks, unpredictable traffic, no servers to manage" → Lambda; "containers, but no cluster of instances to manage" → Fargate; "need the instance itself, long-running or steady load" → EC2 (with a commitment if usage is steady).`,[`lambda-welcome`,`fargate-ecs`,`ec2-purchasing`],[`lambda-welcome|With Lambda, you can run code without provisioning or managing servers.`,`fargate-ecs|With AWS Fargate, you no longer have to provision, configure, or scale clusters of virtual machines to run containers.`,`ec2-purchasing|If you can't make a commitment to a specific instance configuration, but you can commit to a usage amount, purchase Savings Plans to reduce your On-Demand Instance costs.`])]},{id:`4.2-K9`,concepts:[n(`EC2 Auto Scaling keeps a group between the minimum and maximum size you set and at the desired capacity, launching or terminating instances as scaling policies react to demand. It also monitors instance health and replaces terminated or impaired instances to maintain the desired capacity.`,`asg-what-is`,[`You can specify the minimum number of instances in each Auto Scaling group, and Amazon EC2 Auto Scaling ensures that your group never goes below this size.`,`You can specify the maximum number of instances in each Auto Scaling group, and Amazon EC2 Auto Scaling ensures that your group never goes above this size.`,`If you specify scaling policies, then Amazon EC2 Auto Scaling can launch or terminate instances as demand on your application increases or decreases.`,`Amazon EC2 Auto Scaling automatically monitors the health and availability of your instances using EC2 health checks and replaces terminated or impaired instances to maintain your desired capacity.`]),n(`Scaling approaches differ in cost. Target tracking keeps a metric such as average CPU at a target value, which helps maintain high utilisation for better cost efficiency without manual intervention. Scheduled scaling changes desired capacity at specific times for predictable load changes. Predictive scaling forecasts load from history to add capacity ahead of demand, and can save money by avoiding over-provisioning.`,[`asg-target-tracking`,`asg-scheduled`,`asg-predictive`],[`asg-target-tracking|This allows your application to maintain optimal performance and high utilization for your EC2 instances for better cost efficiency without manual intervention.`,`asg-scheduled|With scheduled scaling, you can set up automatic scaling for your application based on predictable load changes.`,`asg-predictive|Predictive scaling can also potentially save you money on your EC2 bill by helping you avoid the need to over provision capacity.`]),n(`For an Auto Scaling group whose instances are slow to start, a warm pool is the Auto Scaling feature: a pool of pre-initialized EC2 instances that sits alongside the group, so a scale-out can draw on instances that are ready to serve traffic. You can keep warm pool instances Stopped, Running or Hibernated; Stopped is an effective way to minimize costs because you pay only for the volumes and attached Elastic IP addresses, and Running is highly discouraged. AWS warns that creating a warm pool when it is not required can lead to unnecessary costs.`,`asg-warm-pools`,[`A warm pool gives you the ability to decrease latency for your applications that have exceptionally long boot times, for example, because instances need to write massive amounts of data to disk.`,`A warm pool is a pool of pre-initialized EC2 instances that sits alongside an Auto Scaling group.`,`You can keep instances in the warm pool in one of three states: Stopped, Running, or Hibernated.`,`Keeping instances in a Stopped state is an effective way to minimize costs.`,`With stopped instances, you pay only for the volumes that you use and the Elastic IP addresses attached to the instances.`,`Keeping instances in a Running state inside the warm pool is also possible, but is highly discouraged to avoid incurring unnecessary charges.`,`Creating a warm pool when it's not required can lead to unnecessary costs.`],{allow:[`three`]}),n(`Hibernation is a cost tool for a single instance that is slow to start. Hibernation saves the contents of the instance memory (RAM) to the EBS root volume; when the instance starts again, the RAM contents are reloaded and the processes that were running resume. You are not charged for instance usage for a hibernated instance in the stopped state, but you are charged for storage of any EBS volumes, including storage for the RAM contents.`,`ec2-hibernate`,[`Hibernation saves the contents from the instance memory (RAM) to your Amazon Elastic Block Store (Amazon EBS) root volume.`,`The RAM contents are reloaded`,`The processes that were previously running on the instance are resumed`,`You're not charged for instance usage for a hibernated instance when it is in the stopped state or for data transfer when the contents of the RAM are transferred to the EBS root volume.`,`You are charged for storage of any EBS volumes, including storage for the RAM contents.`])],services:[`Amazon EC2 Auto Scaling`,`Amazon EC2`],design:[n(`Cue: "keep average CPU at a level" → target tracking; "load rises every weekday morning" → scheduled scaling; "regular daily or weekly patterns and slow start-up" → predictive scaling; "Auto Scaling group instances take very long to boot" → a warm pool; "one instance takes a long time to reach a warm state" → hibernation to pre-warm.`,[`asg-target-tracking`,`asg-scheduled`,`asg-predictive`,`asg-warm-pools`,`ec2-hibernate`],[`asg-scheduled|With scheduled scaling, you can set up automatic scaling for your application based on predictable load changes.`,`asg-predictive|In general, if you have regular patterns of traffic increases and applications that take a long time to initialize, you should consider using predictive scaling.`,`asg-warm-pools|A warm pool is a pool of pre-initialized EC2 instances that sits alongside an Auto Scaling group.`,`ec2-hibernate|If an instance or application takes a long time to bootstrap and build a memory footprint to become fully productive, you can use hibernation to pre-warm the instance.`])]},{id:`4.2-S1`,concepts:[n(`Elastic Load Balancing distributes traffic across multiple targets, such as EC2 instances, containers and IP addresses, in one or more Availability Zones, and sends requests only to healthy targets. Choose the type by the traffic and the need.`,`elb-what-is`,[`Elastic Load Balancing automatically distributes your incoming traffic across multiple targets, such as EC2 instances, containers, and IP addresses, in one or more Availability Zones.`,`It monitors the health of its registered targets, and routes traffic only to the healthy targets.`]),n(`The Application Load Balancer works at the application layer, the seventh layer of the OSI model, and can route requests to different target groups based on the content of the application traffic, so one load balancer can front several services.`,`alb-intro`,[`An Application Load Balancer functions at the application layer, the seventh layer of the Open Systems Interconnection (OSI) model.`,`You can configure listener rules to route requests to different target groups based on the content of the application traffic.`],{allow:[`seventh`]}),n(`The Network Load Balancer works at the fourth layer, can handle millions of requests per second, and its target groups support protocols such as TCP, UDP and TLS.`,`nlb-intro`,[`Network Load Balancer functions at the fourth layer of the Open Systems Interconnection (OSI) model.`,`It can handle millions of requests per second.`,`Network Load Balancer target groups support the TCP, UDP, TCP_UDP, TLS, QUIC, and TCP_QUIC protocols.`],{allow:[`fourth`]}),n(`The Gateway Load Balancer deploys, scales and manages virtual appliances such as firewalls and intrusion detection and prevention systems behind a single entry and exit point for traffic. The full comparison is in the Don't confuse section of Express Interchange.`,`gwlb-intro`,[`Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`,`It combines a transparent network gateway (that is, a single entry and exit point for all traffic) and distributes traffic while scaling your virtual appliances with the demand.`])],services:[`Elastic Load Balancing (ELB)`],design:[n(`Cue: "HTTP routing by path or host" → Application Load Balancer; "millions of requests per second of TCP or UDP traffic" → Network Load Balancer; "deploy and scale virtual appliances such as firewalls and intrusion detection systems" → Gateway Load Balancer.`,[`alb-intro`,`nlb-intro`,`gwlb-intro`],[`alb-intro|You can configure listener rules to route requests to different target groups based on the content of the application traffic.`,`alb-intro|You can configure rules for your listener that forward requests based on the host field in the HTTP header.`,`alb-intro|Support for Path conditions.`,`nlb-intro|It can handle millions of requests per second.`,`gwlb-intro|Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`])]},{id:`4.2-S2`,concepts:[n(`Scaling up (vertical) means moving to a larger instance by changing the instance type; scaling out (horizontal) means adding more instances. You change the type of a compatible EBS-backed instance only after stopping it, so plan for downtime, and you start paying the rate of the new type. Auto Scaling can launch or terminate instances as demand increases or decreases, so the number of instances you run follows demand.`,[`ec2-resize`,`ec2-resize-ebs`,`asg-what-is`],[`ec2-resize|When you change the instance type, you'll start paying the rate of the new instance type.`,`ec2-resize-ebs|Considerations You must stop your instance before you can change its instance type.`,`ec2-resize-ebs|Ensure that you plan for downtime while your instance is stopped.`,`asg-what-is|If you specify scaling policies, then Amazon EC2 Auto Scaling can launch or terminate instances as demand on your application increases or decreases.`]),n(`Hibernation applies when you enable it at launch: you can enable hibernation for an On-Demand Instance or a Spot Instance when you launch it, and you cannot enable it on an existing instance, whether running or stopped. It needs an HVM AMI that supports hibernation, a supported instance family (bare metal instances are not supported), RAM below a size limit, and an encrypted EBS root volume large enough to hold the RAM contents.`,`ec2-hibernate-prereq`,[`You can enable hibernation support for an On-Demand Instance or a Spot Instance when you launch it.`,`You can't enable hibernation on an existing instance, whether it is running or stopped.`,`You must use an HVM AMI that supports hibernation.`,`You must use an instance family that supports hibernation.`,`However, bare metal instances are not supported.`,`Linux instances – Must be less than 150 GiB.`,`The root volume must be large enough to store the RAM contents and accommodate your expected usage, for example, OS or applications.`,`The root volume must be encrypted to protect sensitive content that is in memory during hibernation.`])],services:[`Amazon EC2`,`Amazon EC2 Auto Scaling`],design:[n(`Cue: "single instance is too small, resize" → vertical, change the instance type; "traffic varies, add instances automatically" → horizontal with Auto Scaling; "instance is slow to warm up and sits idle between uses" → hibernation, enabled at launch.`,[`ec2-resize`,`asg-what-is`,`ec2-hibernate-prereq`],[`ec2-resize|When you change the instance type, you'll start paying the rate of the new instance type.`,`asg-what-is|If you specify scaling policies, then Amazon EC2 Auto Scaling can launch or terminate instances as demand on your application increases or decreases.`,`ec2-hibernate-prereq|You can't enable hibernation on an existing instance, whether it is running or stopped.`])]},{id:`4.2-S3`,concepts:[n(`Match the service to the workload shape. Lambda: code can run for up to 15 minutes in a single invocation, and a Lambda Managed Instances function invoked asynchronously or through an event source mapping (other than Amazon MQ and Amazon DocumentDB) can run for up to 90 minutes; the pricing for {{rename:lambda-event-function}} is per request and execution duration. Fargate runs containers without managing servers or clusters of EC2 instances. EC2 offers purchasing options to optimize cost (Counting House).`,[`lambda-quotas`,`lambda-pricing`,`fargate-ecs`,`ec2-purchasing`],[`lambda-quotas|Code can run for up to 15 minutes in a single invocation (up to 90 minutes for Lambda Managed Instances functions invoked asynchronously or through any event source mapping except Amazon MQ and Amazon DocumentDB) and a single function can use up to 10,240 MB of memory.`,`lambda-pricing|Lambda Event Functions are priced per request and execution duration.`,`fargate-ecs|AWS Fargate is a technology that you can use with Amazon ECS to run containers without having to manage servers or clusters of Amazon EC2 instances.`,`ec2-purchasing|You can use the following options to optimize your costs for Amazon EC2`],{newer:[`lambda-managed-instances`,`lambda-managed-instances-90min`]}),n(`With Fargate you specify the CPU and memory requirements for the task, and each Fargate task has its own isolation boundary and does not share the underlying kernel, CPU, memory or network interface with another task.`,`fargate-ecs`,[`Each Fargate task has its own isolation boundary and does not share the underlying kernel, CPU resources, memory resources, or elastic network interface with another task.`])],services:[`AWS Lambda`,`Amazon EC2`,`AWS Fargate`],design:[n(`Cue: "pay per request and execution duration" → Lambda; "containerised app, no instances to manage" → Fargate; "can commit to a consistent instance configuration" → EC2 Reserved Instances; "can commit to a usage amount but not an instance configuration" → Savings Plans; "flexible about when it runs and can be interrupted" → EC2 Spot.`,[`lambda-pricing`,`fargate-ecs`,`ec2-purchasing`,`ec2-spot`],[`lambda-pricing|Lambda Event Functions are priced per request and execution duration.`,`fargate-ecs|With AWS Fargate, you no longer have to provision, configure, or scale clusters of virtual machines to run containers.`,`ec2-purchasing|If you can't make a commitment to a specific instance configuration, but you can commit to a usage amount, purchase Savings Plans to reduce your On-Demand Instance costs.`,`ec2-purchasing|Reserved Instances – Reduce your Amazon EC2 costs by making a commitment to a consistent instance configuration, including instance type and Region, for a term of 1 or 3 years.`,`ec2-spot|Spot Instances are a cost-effective choice if you can be flexible about when your applications run and if your applications can be interrupted.`])]}],cues:[e(`priced per request and execution duration, no servers to manage`,`AWS Lambda`,n(`The pricing for {{rename:lambda-event-function}} is per request and execution duration.`,`lambda-pricing`,[`Lambda Event Functions are priced per request and execution duration.`])),e(`run containers without managing servers or clusters`,`AWS Fargate`,n(`Fargate runs containers without having to manage servers or clusters of EC2 instances.`,`fargate-ecs`,[`AWS Fargate is a technology that you can use with Amazon ECS to run containers without having to manage servers or clusters of Amazon EC2 instances.`])),e(`keep average CPU near a target to maintain high utilisation`,`Target tracking scaling`,n(`Target tracking helps maintain high utilisation for better cost efficiency without manual intervention.`,`asg-target-tracking`,[`This allows your application to maintain optimal performance and high utilization for your EC2 instances for better cost efficiency without manual intervention.`])),e(`load changes at known times each week`,`Scheduled scaling`,n(`Scheduled scaling suits predictable load changes.`,`asg-scheduled`,[`With scheduled scaling, you can set up automatic scaling for your application based on predictable load changes.`])),e(`regular daily or weekly pattern and slow-to-initialise application`,`Predictive scaling`,n(`Predictive scaling suits regular traffic patterns and applications that take a long time to initialise.`,`asg-predictive`,[`In general, if you have regular patterns of traffic increases and applications that take a long time to initialize, you should consider using predictive scaling.`])),e(`instance takes a long time to warm up; stop it without paying for compute`,`EC2 hibernation (enabled at launch)`,n(`Hibernation can pre-warm an instance, and a hibernated instance in the stopped state is not charged for instance usage.`,`ec2-hibernate`,[`If an instance or application takes a long time to bootstrap and build a memory footprint to become fully productive, you can use hibernation to pre-warm the instance.`,`You're not charged for instance usage for a hibernated instance when it is in the stopped state or for data transfer when the contents of the RAM are transferred to the EBS root volume.`])),e(`route to different services by URL path on one load balancer`,`Application Load Balancer`,n(`An Application Load Balancer routes to different target groups based on the content of the request.`,`alb-intro`,[`You can configure listener rules to route requests to different target groups based on the content of the application traffic.`])),e(`deploy and scale virtual appliances such as firewalls`,`Gateway Load Balancer`,n(`Gateway Load Balancers deploy, scale and manage virtual appliances.`,`gwlb-intro`,[`Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`]))],examples:[],confuse:[`alb-nlb-gwlb`],azure:[{concept:`Azure Functions`,aws:`AWS Lambda`,mapping:n(`The Learn compute comparison pairs AWS Lambda with Azure Functions: both provide serverless, event-driven code execution with pay-per-execution pricing and automatic scaling.`,[`learn-compute`,`lambda-pricing`],[`learn-compute|AWS Lambda Azure Functions Both services provide serverless, event-driven code execution with pay-per-execution pricing and automatic scaling.`,`lambda-pricing|Lambda Event Functions are priced per request and execution duration.`]),breaks:n(`Learn pairs Lambda with Azure Functions on pay-per-execution pricing. On AWS, the pricing for {{rename:lambda-event-function}} is per request and execution duration, and configuring provisioned concurrency incurs charges to your AWS account.`,[`lambda-concurrency`,`learn-compute`,`lambda-pricing`],[`lambda-concurrency|Configuring provisioned concurrency incurs charges to your AWS account.`,`learn-compute|AWS Lambda Azure Functions Both services provide serverless, event-driven code execution with pay-per-execution pricing and automatic scaling.`,`lambda-pricing|Lambda Event Functions are priced per request and execution duration.`])},{concept:`Azure Virtual Machine Scale Sets`,aws:`Amazon EC2 Auto Scaling`,mapping:n(`Learn pairs AWS Auto Scaling with Azure Virtual Machine Scale Sets (and App Service autoscaling): in Azure, you use virtual machine scale sets to deploy and manage identical sets of VMs, and autoscaling changes the number of compute instances or resources based on defined metrics and thresholds.`,[`learn-compute`,`asg-what-is`],[`learn-compute|In Azure, you can use virtual machine scale sets to deploy and manage identical sets of VMs.`,`learn-compute|You can use autoscaling to automatically change the number of compute instances or resources based on defined metrics and thresholds.`,`asg-what-is|If you specify scaling policies, then Amazon EC2 Auto Scaling can launch or terminate instances as demand on your application increases or decreases.`]),breaks:n(`Learn describes virtual machine scale sets as identical sets of VMs and autoscaling as changing the number of instances based on defined metrics and thresholds. On AWS, EC2 Auto Scaling also offers predictive scaling, which analyses historical load data to detect daily or weekly patterns in traffic flows.`,[`asg-predictive`,`learn-compute`],[`asg-predictive|Predictive scaling works by analyzing historical load data to detect daily or weekly patterns in traffic flows.`,`learn-compute|In Azure, you can use virtual machine scale sets to deploy and manage identical sets of VMs.`])}]},d={building:`engine-exchange`,overview:[n(`The database engine decides the licence, the tools and the migration effort, so it is a cost decision as well as a technical one. Amazon RDS runs engines you already know, and Aurora is compatible with MySQL and PostgreSQL. Moving between engines is more work than keeping the same engine: AWS DMS migrates the data, and DMS Schema Conversion or the AWS Schema Conversion Tool converts the schema when the engine changes. Express Quarter introduced DMS; this building looks at the cost side of the same choices.`,[`rds-what-is`,`aurora-overview`,`dms-what-is`],[`rds-what-is|You can use database engines that you are already familiar with: IBM Db2, MariaDB, Microsoft SQL Server, MySQL, Oracle Database, and PostgreSQL.`,`aurora-overview|Amazon Aurora (Aurora) is a fully managed relational database engine that's compatible with MySQL and PostgreSQL.`,`dms-what-is|With AWS DMS, you can discover your source data stores, convert your source schemas, and migrate your data.`],{newer:[`dms-schema-conversion`]})],bullets:[{id:`4.3-K7`,concepts:[n(`A {{term:homogeneous-migration}} keeps the same engine and a {{term:heterogeneous-migration}} changes it. AWS DMS supports migrating away from old infrastructure while keeping the same engine, and fully heterogeneous migrations between the supported engines; to migrate to a different engine you can use DMS Schema Conversion.`,`dms-what-is`,[`Conversely, if you want to migrate away from old infrastructure but continue to use the same database engine, AWS DMS also supports that process.`,`AWS DMS supports fully heterogeneous data migrations between the supported engines.`,`To migrate to a different database engine, you can use DMS Schema Conversion.`],{newer:[`dms-schema-conversion`]}),n(`Amazon RDS lets you use engines you already know: IBM Db2, MariaDB, Microsoft SQL Server, MySQL, Oracle Database and PostgreSQL. Aurora is a relational engine compatible with MySQL and PostgreSQL, so the code, tools and applications you use with existing MySQL and PostgreSQL databases can be used with Aurora.`,[`rds-what-is`,`aurora-overview`],[`rds-what-is|You can use database engines that you are already familiar with: IBM Db2, MariaDB, Microsoft SQL Server, MySQL, Oracle Database, and PostgreSQL.`,`aurora-overview|The code, tools, and applications you use today with your existing MySQL and PostgreSQL databases can be used with Aurora.`])],services:[`AWS DMS`,`Amazon RDS`,`Amazon Aurora`],design:[n(`Cue: "same engine, move to AWS with minimal change" → homogeneous migration (DMS); "move from a commercial engine to MySQL or PostgreSQL" → heterogeneous migration with schema conversion first, then DMS.`,`dms-what-is`,[`After you convert your source schemas and apply the converted code to your target database, you can use AWS DMS to migrate your data.`,`AWS DMS supports fully heterogeneous data migrations between the supported engines.`])]},{id:`4.3-S2`,concepts:[n(`Choose the engine the application needs before comparing cost: MySQL or PostgreSQL applications can run on RDS or on Aurora, which is compatible with both, and Microsoft SQL Server, Oracle and Db2 applications run on RDS with their own engine. The code, tools and applications already written for an engine fix the choice.`,[`rds-what-is`,`aurora-overview`],[`rds-what-is|You can use database engines that you are already familiar with: IBM Db2, MariaDB, Microsoft SQL Server, MySQL, Oracle Database, and PostgreSQL.`,`aurora-overview|The code, tools, and applications you use today with your existing MySQL and PostgreSQL databases can be used with Aurora.`]),n(`Licensing is a cost lever for commercial engines. RDS for Oracle has two licensing options, License Included and Bring Your Own License. In License Included you do not need to purchase Oracle Database licences separately, and AWS holds the licence for the database software, but the model is only supported on Oracle Database Standard Edition 2; in BYOL you use your existing Oracle licences, and for a Multi-AZ deployment you must have a licence for both the primary and the standby DB instance.`,`rds-oracle-licensing`,[`Amazon RDS for Oracle has two licensing options: License Included (LI) and Bring Your Own License (BYOL).`,`In the License Included model, you don't need to purchase Oracle Database licenses separately.`,`AWS holds the license for the Oracle database software.`,`The License Included model is only supported on Amazon RDS for Oracle Database Standard Edition 2 (SE2).`,`If you use the Bring Your Own License model, you must have a license for both the primary DB instance and the standby DB instance in a Multi-AZ deployment.`]),n(`For Aurora, the storage configuration is a cost choice too. Aurora I/O-Optimized has no additional charges for read and write I/O operations and suits I/O-intensive applications; Aurora Standard is cost-effective for moderate I/O usage and adds a standard rate for I/O requests.`,`aurora-storage`,[`Aurora I/O-Optimized – Improved price performance and predictability for I/O-intensive applications.`,`You pay only for the usage and storage of your DB clusters, with no additional charges for read and write I/O operations.`,`Aurora Standard – Cost-effective pricing for many applications with moderate I/O usage.`,`In addition to the usage and storage of your DB clusters, you also pay a standard rate per 1 million requests for I/O operations.`],{newer:[`aurora-io-optimized`]}),n(`Aurora builds on the idea AWS states: MySQL and PostgreSQL combine the speed and reliability of high-end commercial databases with the simplicity and cost-effectiveness of open-source databases. When the target is a different engine, AWS DMS assesses and converts your source schemas to the new target engine.`,[`aurora-overview`,`dms-what-is`],[`aurora-overview|You already know how MySQL and PostgreSQL combine the speed and reliability of high-end commercial databases with the simplicity and cost-effectiveness of open-source databases.`,`dms-what-is|This service automatically assesses and converts your source schemas to a new target engine.`])],services:[`Amazon RDS`,`Amazon Aurora`],design:[n(`Cue: "keep the existing Oracle licences" → RDS for Oracle with BYOL; "no licences to buy" → License Included; "application is MySQL or PostgreSQL compatible and needs elastic, resilient capacity" → Aurora.`,[`rds-oracle-licensing`,`aurora-overview`],[`rds-oracle-licensing|In the BYOL model, you can use your existing Oracle Database licenses to deploy databases on Amazon RDS.`,`aurora-overview|Amazon Aurora (Aurora) is a fully managed relational database engine that's compatible with MySQL and PostgreSQL.`])]},{id:`4.3-S5`,concepts:[n(`AWS DMS migrates relational databases, data warehouses, NoSQL databases and other data stores into the AWS Cloud or between cloud and on-premises setups. Schemas move first when the engine changes: DMS Schema Conversion automatically assesses and converts your source schemas to a new target engine, or you can download the AWS Schema Conversion Tool (AWS SCT) to convert them, and after applying the converted code to the target database you use AWS DMS to migrate the data.`,`dms-what-is`,[`AWS Database Migration Service (AWS DMS) is a cloud service that makes it possible to migrate relational databases, data warehouses, NoSQL databases, and other types of data stores.`,`This service automatically assesses and converts your source schemas to a new target engine.`,`Alternatively, you can download the AWS Schema Conversion Tool (AWS SCT) to your local PC to convert your source schemas.After you convert your source schemas and apply the converted code to your target database, you can use AWS DMS to migrate your data.`],{newer:[`dms-schema-conversion`]}),n(`You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`,`dms-what-is`,[`You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`]),n(`For cost, AWS DMS Serverless provides automatic provisioning, scaling, built-in high availability and a pay-for-use billing model. It removes replication instance management tasks like capacity estimation, provisioning and cost optimisation, so you do not size and pay for a replication instance yourself.`,`dms-serverless`,[`AWS DMS Serverless is a feature that provides automatic provisioning, scaling, built-in high availability, and a pay-for-use billing model, to increase operations agility and optimize your costs.`,`The Serverless feature eliminates replication instance management tasks like capacity estimation, provisioning, cost optimization, and managing replication engine versions and patching.`],{newer:[`dms-serverless`]})],services:[`AWS DMS`,`Amazon RDS`,`Amazon Aurora`],design:[n(`Cue: "convert the schema to a different engine" → DMS Schema Conversion or AWS SCT; "move the data and keep replicating changes" → AWS DMS; "do not want to manage or size the replication capacity" → AWS DMS Serverless.`,[`dms-what-is`,`dms-serverless`],[`dms-what-is|After you convert your source schemas and apply the converted code to your target database, you can use AWS DMS to migrate your data.`,`dms-serverless|AWS DMS Serverless is a feature that provides automatic provisioning, scaling, built-in high availability, and a pay-for-use billing model, to increase operations agility and optimize your costs.`],{newer:[`dms-schema-conversion`,`dms-serverless`]})]}],cues:[e(`same database engine, moving away from old infrastructure`,`Homogeneous migration with AWS DMS`,n(`AWS DMS supports migrating away from old infrastructure while using the same engine.`,`dms-what-is`,[`Conversely, if you want to migrate away from old infrastructure but continue to use the same database engine, AWS DMS also supports that process.`])),e(`migrate to a different database engine`,`DMS Schema Conversion (or AWS SCT), then AWS DMS`,n(`To migrate to a different engine you can use DMS Schema Conversion.`,`dms-what-is`,[`To migrate to a different database engine, you can use DMS Schema Conversion.`],{newer:[`dms-schema-conversion`]})),e(`keep existing Oracle licences on RDS`,`RDS for Oracle Bring Your Own License`,n(`In the BYOL model you use your existing Oracle Database licences on RDS.`,`rds-oracle-licensing`,[`In the BYOL model, you can use your existing Oracle Database licenses to deploy databases on Amazon RDS.`])),e(`no Oracle licence purchase, pay as part of the instance`,`RDS for Oracle License Included`,n(`In License Included you do not purchase Oracle Database licences separately.`,`rds-oracle-licensing`,[`In the License Included model, you don't need to purchase Oracle Database licenses separately.`])),e(`migrate with pay-for-use billing and no replication instance to size`,`AWS DMS Serverless`,n(`DMS Serverless provides automatic provisioning, scaling and a pay-for-use billing model.`,`dms-serverless`,[`AWS DMS Serverless is a feature that provides automatic provisioning, scaling, built-in high availability, and a pay-for-use billing model, to increase operations agility and optimize your costs.`],{newer:[`dms-serverless`]})),e(`keep source and target in sync until cut-over`,`DMS ongoing replication`,n(`DMS can replicate ongoing changes to keep sources and targets in sync.`,`dms-what-is`,[`You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`]))],examples:[],confuse:[],azure:[{concept:`Azure Database Migration Service`,aws:`AWS Database Migration Service (AWS DMS)`,mapping:n(`Learn pairs AWS DMS with Azure Database Migration Service, and says support varies by source, target and online or offline migration mode.`,[`learn-databases`,`dms-what-is`],[`learn-databases|Database migration AWS Database Migration Service Azure Database Migration Service Support varies by source, target, and online or offline migration mode.`,`dms-what-is|AWS DMS supports fully heterogeneous data migrations between the supported engines.`]),breaks:n(`On AWS, AWS DMS Serverless provides automatic provisioning, scaling, built-in high availability and a pay-for-use billing model, and RDS for Oracle has licensing options, License Included and Bring Your Own License, that are chosen for the database rather than for the migration tool.`,[`dms-serverless`,`rds-oracle-licensing`,`learn-databases`],[`dms-serverless|AWS DMS Serverless is a feature that provides automatic provisioning, scaling, built-in high availability, and a pay-for-use billing model, to increase operations agility and optimize your costs.`,`rds-oracle-licensing|Amazon RDS for Oracle has two licensing options: License Included (LI) and Bring Your Own License (BYOL).`,`learn-databases|Support varies by source, target, and online or offline migration mode.`],{newer:[`dms-serverless`]})}]},f={building:`haul-hybrid-customs`,overview:[n(`Transfer Dock covered how the transfer services work. This building asks the cost question: which method gets the data into AWS storage at the lowest cost while meeting the deadline? The inputs are the same (data size, network speed, one-time or ongoing, protocol) but the answer is the cheapest option that still fits, not the fastest. Actual prices are on AWS pricing pages and change, so this building teaches how to compare options, not figures.`,[`datasync-what-is`,`transfer-what-is`,`storage-gateway-docs`],[`datasync-what-is|AWS DataSync is a secure, reliable, high‐speed file transfer service that helps you quickly and easily transfer your file or object data to, from, and between AWS storage services.`,`transfer-what-is|AWS Transfer Family is a secure transfer service that enables you to transfer files into and out of AWS storage services.`,`storage-gateway-docs|AWS Storage Gateway is a service that connects an on-premises software appliance with cloud-based storage to provide seamless and secure integration between your on-premises IT environment and the AWS storage infrastructure in the AWS Cloud.`])],bullets:[{id:`4.1-K8`,concepts:[n(`Hybrid storage options keep some data on premises and some in AWS. AWS DataSync transfers file or object data between on-premises storage (NFS, SMB, HDFS, object storage) and AWS storage services. AWS Transfer Family gives partners and applications SFTP, AS2, FTPS and FTP access to S3 or EFS. AWS Storage Gateway connects an on-premises appliance to cloud storage for ongoing access.`,[`datasync-what-is`,`transfer-what-is`,`storage-gateway-docs`],[`datasync-what-is|DataSync works with the following on-premises storage systems: Network File System (NFS) Server Message Block (SMB) Hadoop Distributed File Systems (HDFS) Object storage`,`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`,`storage-gateway-docs|AWS Storage Gateway is a service that connects an on-premises software appliance with cloud-based storage to provide seamless and secure integration between your on-premises IT environment and the AWS storage infrastructure in the AWS Cloud.`]),n(`The services are billed differently. DataSync charges a flat per-gigabyte fee for the amount of data transferred between your storage locations, with no upfront costs and no minimum charges. Transfer Family charges for the protocols enabled on your server endpoints, plus the gigabytes uploaded and downloaded, so an enabled endpoint is a cost to remove when it is not in use; standard request, storage and data transfer rates for S3 or EFS are charged in addition.`,[`datasync-pricing`,`transfer-pricing`],[`datasync-pricing|You pay a flat, per-gigabyte fee for the amount of data transferred between your storage locations.`,`datasync-pricing|With DataSync, there are no upfront costs and no minimum charges.`,`transfer-pricing|You only pay for the protocols enabled on your Server endpoint(s), the amount of data (gigabytes) uploaded and downloaded over SFTP or FTPS or FTP, or the number of messages sent or received over AS2, and the amount of data processed using Transfer Family workflows.`,`transfer-pricing|You are charged standard request, storage, and data transfer rates to read to and write from Amazon S3 or Amazon EFS.`]),n(`Storage Gateway connects an on-premises software appliance with cloud-based storage. S3 File Gateway provides a cost-effective alternative to on-premises storage, and Tape Gateway lets you cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`,[`sgw-file-s3`,`sgw-tape`,`storage-gateway-docs`],[`storage-gateway-docs|AWS Storage Gateway is a service that connects an on-premises software appliance with cloud-based storage to provide seamless and secure integration between your on-premises IT environment and the AWS storage infrastructure in the AWS Cloud.`,`sgw-file-s3|A S3 File Gateway simplifies file storage in Amazon S3, integrates to existing applications through industry-standard file system protocols, and provides a cost-effective alternative to on-premises storage.`,`sgw-tape|With Tape Gateway, you can cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`])],services:[`AWS DataSync`,`AWS Transfer Family`,`AWS Storage Gateway`],design:[n(`Cue: ongoing hybrid access with local caching → Storage Gateway; a migration or move of file or object data between storage systems → DataSync; partners using SFTP → Transfer Family.`,[`datasync-what-is`,`sgw-file-s3`,`transfer-what-is`],[`datasync-what-is|AWS DataSync is a secure, reliable, high‐speed file transfer service that helps you quickly and easily transfer your file or object data to, from, and between AWS storage services.`,`sgw-file-s3|You can think of a S3 File Gateway as a file system mount on Amazon S3.`,`sgw-file-s3|It also provides low-latency access to data through transparent local caching.`,`datasync-what-is|This approach speeds up migrations, recurring data-processing workflows for analytics and machine learning, and data-protection processes.`,`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`])]},{id:`4.1-S1`,concepts:[n(`Batch uploads against many small ones. Multipart upload splits one large object into parts uploaded independently and in parallel, which improves throughput and recovers quickly from network problems, and AWS suggests considering it for large objects. S3 charges per request for PUT requests that ingest objects, so many individual uploads of small files mean many billed requests, while grouping them into fewer, larger objects means fewer.`,[`s3-multipart`,`s3-pricing`],[`Multipart upload allows you to upload a single object to Amazon S3 as a set of parts.`,`Improved throughput – You can upload parts in parallel to improve throughput.`,`Quick recovery from any network issues – Smaller part size minimizes the impact of restarting a failed upload due to a network error.`,`s3-pricing|There are per-request ingest charges when using PUT, COPY, or lifecycle rules to move data into any S3 storage class.`]),n(`Incomplete multipart uploads cost money: while the parts of an in-progress multipart upload exist, you are billed for the storage, bandwidth and requests for the upload and its parts, so abort or complete uploads and use a lifecycle rule to clean up incomplete ones.`,`s3-multipart`,[`Throughout its lifetime, you are billed for all storage, bandwidth, and requests for this multipart upload and its associated parts.`]),n(`S3 Transfer Acceleration is a bucket-level feature for fast transfers over long distances between your client and an S3 general purpose bucket, using the globally distributed edge locations of CloudFront. It suits users uploading from all over the world to a central bucket, or bandwidth you cannot fully use over the internet. When you use Transfer Acceleration, additional data transfer charges might apply.`,`s3-transfer-acceleration`,[`Amazon S3 Transfer Acceleration is a bucket-level feature that enables fast, easy, and secure transfers of files over long distances between your client and an S3 general purpose bucket.`,`Your customers upload to a centralized general purpose bucket from all over the world.`,`You can't use all of your available bandwidth over the internet when uploading to Amazon S3.`,`When you use Transfer Acceleration, additional data transfer charges might apply.`])],services:[`Amazon S3`],design:[n(`Cue: many tiny files and high request counts → batch into larger objects; one large file over an unreliable link → multipart upload; global uploaders to one bucket → Transfer Acceleration.`,[`s3-multipart`,`s3-transfer-acceleration`],[`s3-multipart|Improved throughput – You can upload parts in parallel to improve throughput.`,`s3-transfer-acceleration|Your customers upload to a centralized general purpose bucket from all over the world.`])]},{id:`4.1-S3`,concepts:[n(`AWS Data Transfer Terminal is a network-ready, physical location you can bring your data storage devices to for fast data transfer to and from your AWS Cloud service. As study guidance, lowest cost means choosing the cheapest method that still meets the deadline.`,[`dtt`],[`dtt|AWS Data Transfer Terminal is a network-ready, physical location you can bring your data storage devices for fast data transfer to and from your AWS Cloud service.`]),n(`Snowball Edge, the classic offline option, is no longer available to new customers; AWS points new customers to DataSync for online transfers, Data Transfer Terminal for secure physical transfers, or partner solutions. For a current design, base the offline option on what AWS now points to.`,[`snowball-edge`],[`snowball-edge|AWS Snowball Edge is no longer available to new customers.`,`snowball-edge|New customers should explore AWS DataSync for online transfers, AWS Data Transfer Terminal for secure physical transfers, or AWS Partner solutions.`],{status:`closed`}),n(`Two connectivity options: Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable, and Site-to-Site VPN supports IPsec VPN connections. Compare their costs in Transit Tariff, and the landing storage class in Cold Cellar.`,[`dx-what-is`,`s2s-vpn`],[`dx-what-is|Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable.`,`s2s-vpn|Site-to-Site VPN supports Internet Protocol security (IPsec) VPN connections.`],{allow:[`two`]})],services:[`AWS DataSync`,`AWS Snow Family`,`AWS Direct Connect`],design:[n(`Cue: "least expensive way to move a large amount of data when bandwidth is limited" → an offline physical option (and note Snowball Edge availability); "ongoing small changes" → DataSync or Storage Gateway over the existing link.`,`snowball-edge`,[`Each Snowball Edge device can transport data at speeds faster than the internet.`])]},{id:`4.1-S7`,concepts:[n(`Selecting the migration service by what is being moved: file or object data between storage systems → DataSync; files over SFTP, AS2, FTPS or FTP → Transfer Family; continuing hybrid access to cloud-backed volumes, files or tapes → Storage Gateway; databases → AWS DMS (Database Registry).`,[`datasync-what-is`,`transfer-what-is`,`sgw-volume`,`dms-what-is`],[`datasync-what-is|AWS DataSync is a secure, reliable, high‐speed file transfer service that helps you quickly and easily transfer your file or object data to, from, and between AWS storage services.`,`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`,`sgw-volume|AWS Storage Gateway offers file-based (S3 File Gateway and FSx File Gateway), volume-based (Volume Gateway), and tape-based (Tape Gateway) storage solutions.`,`dms-what-is|AWS Database Migration Service (AWS DMS) is a cloud service that makes it possible to migrate relational databases, data warehouses, NoSQL databases, and other types of data stores.`])],services:[`AWS DataSync`,`AWS Transfer Family`,`AWS Storage Gateway`,`AWS Snow Family`],design:[n(`DataSync works with Amazon S3, Amazon EFS and the Amazon FSx file systems, and it copies data into most Amazon S3 storage classes, choosing the most cost-effective one for your needs.`,`datasync-what-is`,[`DataSync works with the following AWS storage services: Amazon S3 Amazon EFS Amazon FSx for Windows File Server Amazon FSx for Lustre Amazon FSx for OpenZFS Amazon FSx for NetApp ONTAP`,`Replicate data – Copy data into most Amazon S3 storage classes, choosing the most cost-effective one for your needs.`])]}],cues:[e(`scheduled copy of NFS/SMB data into S3 or EFS`,`AWS DataSync`,n(`DataSync transfers file or object data to, from and between AWS storage services.`,`datasync-what-is`,[`AWS DataSync is a secure, reliable, high‐speed file transfer service that helps you quickly and easily transfer your file or object data to, from, and between AWS storage services.`])),e(`SFTP clients must keep working against S3`,`AWS Transfer Family`,n(`Transfer Family supports SFTP, AS2, FTPS and FTP.`,`transfer-what-is`,[`AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`])),e(`replace physical tapes with cloud-backed virtual tapes`,`Tape Gateway`,n(`Tape Gateway provides cloud-backed virtual tape storage and cost-effective durable archive.`,`sgw-tape`,[`With Tape Gateway, you can cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`])),e(`uploads of very large objects fail over unreliable networks`,`S3 multipart upload`,n(`Multipart upload recovers quickly from network issues by restarting only a failed part.`,`s3-multipart`,[`Quick recovery from any network issues – Smaller part size minimizes the impact of restarting a failed upload due to a network error.`])),e(`users worldwide upload to one bucket, long distance`,`S3 Transfer Acceleration`,n(`Transfer Acceleration speeds transfers over long distances using CloudFront edge locations.`,`s3-transfer-acceleration`,[`Amazon S3 Transfer Acceleration is a bucket-level feature that enables fast, easy, and secure transfers of files over long distances between your client and an S3 general purpose bucket.`])),e(`stored parts of abandoned multipart uploads are costing money`,`Abort incomplete multipart uploads (lifecycle rule)`,n(`You are billed for storage, bandwidth and requests of an in-progress multipart upload and its parts.`,`s3-multipart`,[`Throughout its lifetime, you are billed for all storage, bandwidth, and requests for this multipart upload and its associated parts.`]))],examples:[],confuse:[],azure:[{concept:`Azure Data Box`,aws:`AWS Snowball Edge`,mapping:n(`Learn pairs Snowball Edge with Azure Data Box, a data transport solution that uses enhanced-security data storage devices to transfer large amounts of data to and from the cloud.`,[`learn-storage`,`snowball-edge`],[`learn-storage|AWS Snowball Edge Azure Data Box Petabyte-scale to exabyte-scale data transport solution that uses enhanced-security data storage devices to transfer large amounts of data to and from the cloud.`,`snowball-edge|Snowball Edge is a device with on-board storage and compute power for select AWS capabilities.`]),breaks:n(`Learn pairs Snowball Edge with Azure Data Box; AWS says Snowball Edge is no longer available to new customers and points new customers to DataSync, Data Transfer Terminal or partner solutions.`,[`snowball-edge`,`learn-storage`],[`snowball-edge|AWS Snowball Edge is no longer available to new customers.`,`snowball-edge|New customers should explore AWS DataSync for online transfers, AWS Data Transfer Terminal for secure physical transfers, or AWS Partner solutions.`,`learn-storage|AWS Snowball Edge Azure Data Box Petabyte-scale to exabyte-scale data transport solution that uses enhanced-security data storage devices to transfer large amounts of data to and from the cloud.`])},{concept:`Azure File Sync`,aws:`AWS DataSync and S3 File Gateway`,mapping:n(`Learn pairs DataSync with Azure File Sync, and notes Azure Files can be deployed by directly mounting serverless Azure file shares or by caching Azure file shares on-premises using Azure File Sync.`,[`learn-storage`,`datasync-what-is`],[`learn-storage|AWS DataSync Azure File Sync Azure Files can be deployed in two main ways: by directly mounting the serverless Azure file shares or by caching Azure file shares on-premises with Azure File Sync.`,`datasync-what-is|AWS DataSync is a secure, reliable, high‐speed file transfer service that helps you quickly and easily transfer your file or object data to, from, and between AWS storage services.`],{allow:[`two`]}),breaks:n(`Learn lists Azure File Sync against both DataSync and S3 File Gateway, and describes S3 File Gateway as providing on-premises, locally cached NFS and SMB file shares that are cloud-backed. AWS describes S3 File Gateway as a file system mount on Amazon S3, whereas DataSync is a file transfer service for moving file or object data to, from and between AWS storage services.`,[`sgw-file-s3`,`datasync-what-is`,`learn-storage`],[`sgw-file-s3|You can think of a S3 File Gateway as a file system mount on Amazon S3.`,`datasync-what-is|AWS DataSync is a secure, reliable, high‐speed file transfer service that helps you quickly and easily transfer your file or object data to, from, and between AWS storage services.`,`learn-storage|Provides on-premises, locally cached NFS and SMB file shares that are cloud-backed.`])}]},p={building:`instance-foundry`,overview:[n(`The instance type you pick is a cost decision. An instance type fixes the hardware of the host your instance runs on, each type is grouped in a family by its compute, memory and storage capabilities, and a size within the family sets how much of that capability you get. Engine Works (Express Quarter) taught the families for performance; this building uses them to pick the cheapest instance that still fits, and to find out when the instance you have is the wrong one.`,[`ec2-instance-types`,`ec2-resize`],[`ec2-instance-types|Each instance type offers different compute, memory, and storage capabilities, and is grouped in an instance family based on these capabilities.`,`ec2-instance-types|When you launch an EC2 instance, the instance type that you specify determines the hardware of the host computer used for your instance.`,`ec2-resize|When you change the instance type, you'll start paying the rate of the new instance type.`])],bullets:[{id:`4.2-K7`,concepts:[n(`Families are named for the resource they are rich in. General purpose instances use compute, memory and networking in equal proportions; compute optimized instances suit compute intensive work such as batch processing, media transcoding and high performance web servers; memory optimized instances suit workloads that process large data sets in memory; storage optimized instances suit high sequential read and write access to very large data sets on local storage; accelerated computing instances use co-processors for graphics or floating point work.`,[`ec2-gp`,`ec2-co`,`ec2-mo`,`ec2-so`,`ec2-ac`],[`ec2-gp|These instances are ideal for applications that use these resources in equal proportions, such as web servers and code repositories.`,`ec2-co|Compute optimized instances are designed for compute intensive applications that benefit from high performance processors.`,`ec2-mo|Memory optimized instances are designed to deliver fast performance for workloads that process large data sets in memory.`,`ec2-so|Storage optimized instances are designed for workloads that require high, sequential read and write access to very large data sets on local storage.`,`ec2-ac|Accelerated computing instances use hardware accelerators, or co-processors, to perform functions, such as floating point number calculations, graphics processing, or data pattern matching, more efficiently than is possible in software running on CPUs.`]),n(`Instance types are named from their instance family and instance size, so the name tells you both the family and how large the instance is within it. Changing the type, within or across families, is a resize, and you start paying the rate of the new instance type.`,[`ec2-type-names`,`ec2-resize`],[`ec2-type-names|Instance types are named based on their instance family and instance size.`,`ec2-resize|When you change the instance type, you'll start paying the rate of the new instance type.`]),n(`Resizing is not free of effort. For an EBS-backed instance you must stop the instance before you can change its instance type, so plan for downtime while it is stopped. You can change the type only if the instance's configuration is compatible with the type you want; otherwise you launch a new instance and migrate. Processor architecture is one such limit: an instance on an Arm processor can only move to instance types that support Arm.`,[`ec2-resize-ebs`,`ec2-resize-compat`],[`ec2-resize-ebs|Considerations You must stop your instance before you can change its instance type.`,`ec2-resize-ebs|Ensure that you plan for downtime while your instance is stopped.`,`ec2-resize-compat|You can change the instance type only if the instance's current configuration is compatible with the instance type that you want.`,`ec2-resize-compat|Architecture AMIs are specific to the architecture of the processor, so you must select an instance type with the same processor architecture as the current instance type.`,`ec2-resize-compat|For example: If the current instance type has a processor based on the Arm architecture, you are limited to the instance types that support a processor based on the Arm architecture, such as C6g and M6g.`]),n(`AWS Graviton is a family of processors that AWS designed to deliver the best price performance for workloads running in Amazon EC2, so choosing a Graviton-based (Arm) instance type is a cost lever. The caveat is the architecture limit above: an x86 workload has to be built for Arm, and an AMI is specific to its processor architecture.`,[`graviton`,`ec2-resize-compat`],[`graviton|AWS Graviton is a family of processors designed to deliver the best price performance for your cloud workloads running in Amazon Elastic Compute Cloud (Amazon EC2).`,`ec2-resize-compat|Architecture AMIs are specific to the architecture of the processor, so you must select an instance type with the same processor architecture as the current instance type.`]),n(`Virtualization on current instances comes from the Nitro System, a collection of hardware and software components built by AWS. Its lightweight Nitro hypervisor manages memory and CPU allocation, and the Nitro System also provides bare metal instances that eliminate virtualization overhead. Bare metal fits workloads that need low-level hardware features not available in virtualized environments, or a non-virtualized environment for licensing or support.`,`ec2-nitro`,[`The Nitro System is a collection of hardware and software components built by AWS that enable high performance, high availability, and high security.`,`Nitro hypervisor - A lightweight hypervisor that manages memory and CPU allocation and delivers performance that is indistinguishable from bare metal for most workloads.`,`The Nitro System provides bare metal capabilities that eliminate virtualization overhead and support workloads that require full access to host hardware.`,`Applications that require a non-virtualized environment for licensing or support`]),n(`Burstable performance (T) instances give a baseline level of CPU performance with the ability to burst above it, governed by CPU credits. In unlimited mode an instance can sustain high CPU utilization for any period of time, and the hourly price covers the spikes when average CPU utilization over a rolling 24-hour period or the instance lifetime, whichever is shorter, stays at or below the baseline; if the average CPU usage over a 24-hour period exceeds the baseline, you incur charges for surplus credits.`,[`ec2-instance-types`,`ec2-t-unlimited`],[`ec2-instance-types|Burstable performance (T) instances provide a baseline level of CPU performance with the ability to burst above the baseline.`,`ec2-instance-types|The baseline utilization and ability to burst are governed by CPU credits.`,`ec2-t-unlimited|A burstable performance instance configured as unlimited can sustain high CPU utilization for any period of time whenever required.`,`ec2-t-unlimited|The hourly instance price automatically covers all CPU usage spikes if the average CPU utilization of the instance is at or below the baseline over a rolling 24-hour period or the instance lifetime, whichever is shorter.`,`ec2-t-unlimited|If the average CPU usage over a 24-hour period exceeds the baseline, you incur charges for surplus credits.`])],services:[`Amazon EC2`],design:[n(`Cue: "needs a non-virtualized environment for licensing" → bare metal instance; "large in-memory data set" → memory optimized; "batch processing, transcoding" → compute optimized. Whichever family you pick, EC2 instance types are grouped by capability so the question's limiting resource names the family.`,[`ec2-nitro`,`ec2-mo`,`ec2-co`],[`ec2-nitro|Applications that require a non-virtualized environment for licensing or support`,`ec2-mo|Memory optimized instances are designed to deliver fast performance for workloads that process large data sets in memory.`,`ec2-co|Compute optimized instances are designed for compute intensive applications that benefit from high performance processors.`])]},{id:`4.2-S5`,concepts:[n(`Choose the family from the resource that limits the workload, then check cost. Select an instance type based on the requirements of the application or software that you plan to run. A web server and code repository that use compute, memory and networking in equal proportions fit general purpose; a memory-bound in-memory data set fits memory optimized; paying for compute optimized capacity when the workload is memory-bound wastes money, and the reverse starves the application.`,[`ec2-instance-types`,`ec2-gp`,`ec2-mo`],[`ec2-instance-types|Select an instance type based on the requirements of the application or software that you plan to run on your instance.`,`ec2-gp|These instances are ideal for applications that use these resources in equal proportions, such as web servers and code repositories.`,`ec2-mo|Memory optimized instances are designed to deliver fast performance for workloads that process large data sets in memory.`]),n(`AWS Compute Optimizer analyses the configuration and utilisation metrics of your resources and gives rightsizing recommendations and identifies idle resources. It reports whether resources are optimal and generates recommendations to reduce the cost and improve the performance of your workloads. It supports EC2 instances, EC2 Auto Scaling groups, EBS volumes, Lambda functions, ECS services on Fargate, RDS and Aurora databases, and more.`,`compute-optimizer`,[`AWS Compute Optimizer is a service that analyzes your AWS resources' configuration and utilization metrics to provide you with rightsizing recommendations and identify idle resources.`,`It reports whether your resources are optimal, and generates optimization recommendations to reduce the cost and improve the performance of your workloads.`,`Compute Optimizer generates recommendations for the following resources: Amazon Elastic Compute Cloud (Amazon EC2) instances Amazon EC2 Auto Scaling groups Amazon Elastic Block Store (Amazon EBS) volumes AWS Lambda functions Amazon Elastic Container Service (Amazon ECS) services on AWS Fargate`])],services:[`Amazon EC2`,`AWS Compute Optimizer`],design:[n(`Cue: "which instance family is best for the observed workload?" → Compute Optimizer recommendation; "the instance is underused" → move to a smaller or different family as Compute Optimizer suggests.`,[`compute-optimizer`,`ec2-resize`],[`compute-optimizer|The analysis and visualization of your usage patterns can help you decide when to move or resize your running resources, stop or delete idle resources, and still meet your performance and capacity requirements.`,`ec2-resize|If you want a recommendation for an instance type that is best able to handle your existing workload, you can use AWS Compute Optimizer.`])]},{id:`4.2-S6`,concepts:[n(`Choose the size by measured use, not by guess. Compute Optimizer provides graphs showing recent utilisation history and projected utilisation for its recommendations, which you can use to evaluate which recommendation gives the best price-performance trade-off. It needs enough metric data before it can generate recommendations.`,`compute-optimizer`,[`Compute Optimizer also provides graphs showing recent utilization metric history data, as well as projected utilization for recommendations, which you can use to evaluate which recommendation provides the best price-performance trade-off.`,`For Compute Optimizer to generate recommendations for these resources, they must meet a specific set of requirements, and must have accumulated sufficient metric data.`]),n(`Resizing an EC2 instance means changing its instance type, and which procedure applies depends on the root volume and on compatibility: an EBS-backed instance with a compatible configuration can have its type changed (you must stop the instance first), while an instance store-backed instance, or one whose configuration is not compatible, must be migrated to a new instance type. You start paying the rate of the new type.`,[`ec2-resize`,`ec2-resize-ebs`],[`ec2-resize-ebs|Considerations You must stop your instance before you can change its instance type.`,`Root volume Compatibility Use these instructions EBS Compatible Change the instance type EBS Not compatible Migrate to a new instance type Instance store Not applicable Migrate to a new instance type`,`When you change the instance type, you'll start paying the rate of the new instance type.`]),n(`Sizing is also a scaling decision: instead of one large instance, an Auto Scaling group of smaller instances can follow demand (Elastic Mint covers scaling methods), and Compute Optimizer also gives recommendations for Auto Scaling groups.`,`compute-optimizer`,[`Compute Optimizer generates recommendations for the following resources: Amazon Elastic Compute Cloud (Amazon EC2) instances Amazon EC2 Auto Scaling groups Amazon Elastic Block Store (Amazon EBS) volumes AWS Lambda functions Amazon Elastic Container Service (Amazon ECS) services on AWS Fargate`])],services:[`Amazon EC2`,`AWS Compute Optimizer`],design:[n(`Cue: "right-size based on utilisation with the least effort" → Compute Optimizer; "instance is oversized and costs too much" → resize to the recommended type; remember that the new type is billed at its own rate.`,[`compute-optimizer`,`ec2-resize`],[`compute-optimizer|It reports whether your resources are optimal, and generates optimization recommendations to reduce the cost and improve the performance of your workloads.`,`ec2-resize|When you change the instance type, you'll start paying the rate of the new instance type.`])]}],cues:[e(`find the most cost-effective instance type for the current utilisation`,`AWS Compute Optimizer`,n(`Compute Optimizer analyses configuration and utilisation to give rightsizing recommendations.`,`compute-optimizer`,[`AWS Compute Optimizer is a service that analyzes your AWS resources' configuration and utilization metrics to provide you with rightsizing recommendations and identify idle resources.`])),e(`batch processing or media transcoding needs fast processors`,`Compute optimized family`,n(`Compute optimized instances suit compute intensive work that benefits from high performance processors.`,`ec2-co`,[`Compute optimized instances are designed for compute intensive applications that benefit from high performance processors.`])),e(`process a very large data set in memory`,`Memory optimized family`,n(`Memory optimized instances are designed for workloads that process large data sets in memory.`,`ec2-mo`,[`Memory optimized instances are designed to deliver fast performance for workloads that process large data sets in memory.`])),e(`web servers and code repositories that use CPU and memory evenly`,`General purpose family`,n(`General purpose instances suit applications that use compute, memory and networking in equal proportions.`,`ec2-gp`,[`These instances are ideal for applications that use these resources in equal proportions, such as web servers and code repositories.`])),e(`licence or support requires a non-virtualized environment`,`Bare metal instance`,n(`Bare metal suits applications that require a non-virtualized environment for licensing or support.`,`ec2-nitro`,[`Applications that require a non-virtualized environment for licensing or support`])),e(`mostly idle workload with occasional CPU spikes`,`Burstable (T) instances`,n(`Burstable instances provide a baseline CPU level with the ability to burst, governed by CPU credits.`,`ec2-instance-types`,[`Burstable performance (T) instances provide a baseline level of CPU performance with the ability to burst above the baseline.`]))],examples:[],confuse:[],azure:[{concept:`Azure Virtual Machines`,aws:`Amazon EC2 instance types`,mapping:n(`Learn describes virtual machines and servers as services where you pay only for what you use and can change sizes as needed, and says that AWS instance types and Azure VM sizes have similar categories.`,[`learn-compute`,`ec2-instance-types`],[`learn-compute|You pay only for what you use and can change sizes as needed.`,`learn-compute|AWS instance types and Azure VM sizes have similar categories, but the RAM, CPU, and storage capabilities differ.`,`ec2-instance-types|Each instance type offers different compute, memory, and storage capabilities, and is grouped in an instance family based on these capabilities.`]),breaks:n(`Learn says AWS instance types and Azure VM sizes have similar categories, but the RAM, CPU and storage capabilities differ. On AWS, Compute Optimizer analyses your resources' configuration and utilization metrics to provide rightsizing recommendations; Learn pairs it with Azure Advisor rather than with Azure Virtual Machines.`,[`learn-compute`,`compute-optimizer`],[`learn-compute|AWS instance types and Azure VM sizes have similar categories, but the RAM, CPU, and storage capabilities differ.`,`compute-optimizer|AWS Compute Optimizer is a service that analyzes your AWS resources' configuration and utilization metrics to provide you with rightsizing recommendations and identify idle resources.`])},{concept:`Azure Advisor (Cost category)`,aws:`AWS Compute Optimizer`,mapping:n(`The Learn compute comparison pairs AWS Compute Optimizer with the Cost category of Azure Advisor: both analyse usage metrics to recommend rightsizing for compute resources.`,[`learn-compute`,`compute-optimizer`],[`learn-compute|Both services analyze usage metrics to recommend rightsizing for compute resources.`,`compute-optimizer|AWS Compute Optimizer is a service that analyzes your AWS resources' configuration and utilization metrics to provide you with rightsizing recommendations and identify idle resources.`]),breaks:n(`Learn describes Azure Advisor as providing reliability, security, cost, operational and performance recommendations across VMs, virtual machine scale sets and most Azure services. On AWS, Compute Optimizer reports whether resources are optimal and generates optimization recommendations, while AWS Trusted Advisor provides checks across cost optimization, security, performance, fault tolerance and service limits (Tide Gauges).`,[`learn-compute`,`compute-optimizer`],[`learn-compute|Azure Advisor provides reliability, security, cost, operational, and performance recommendations across VMs, virtual machine scale sets, and most Azure services.`,`learn-compute|AWS Trusted Advisor provides checks across cost optimization, security, performance, fault tolerance, and service limits.`,`compute-optimizer|It reports whether your resources are optimal, and generates optimization recommendations to reduce the cost and improve the performance of your workloads.`])}]},m={building:`ledger-office`,overview:[n(`You cannot optimise what you cannot see. AWS gives you several kinds of cost visibility: tags that label spend ({{term:cost-allocation-tag|cost allocation tags}}), organisation-level billing ({{term:consolidated-billing}}), analysis tools (Cost Explorer), and alerts and detailed data (Budgets and the Cost and Usage Report). Requester Pays moves a data-transfer cost to the person downloading the data.`,[`cost-alloc-tags`,`consolidated-billing`,`ce-what-is`,`budgets-managing`],[`cost-alloc-tags|You can use tags to organize your resources, and cost allocation tags to track your AWS costs on a detailed level.`,`consolidated-billing|Every organization in AWS Organizations has a management account that pays the charges of all the member accounts.`,`ce-what-is|AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`,`budgets-managing|You can use AWS Budgets to track and take action on your AWS costs and usage.`])],bullets:[{id:`4.1-K1`,concepts:[n(`In general the bucket owner pays for all S3 storage and data transfer costs associated with a bucket. With a Requester Pays bucket, the requester instead of the bucket owner pays the cost of the request and the data download; the bucket owner always pays for storing the data.`,`requester-pays`,[`In general, bucket owners pay for all Amazon S3 storage and data transfer costs that are associated with their bucket.`,`With Requester Pays buckets, the requester instead of the bucket owner pays the cost of the request and the data download from the bucket.`,`The bucket owner always pays the cost of storing data.`]),n(`Use it when you want to share data without incurring the charges of others accessing it, such as large datasets (zip code directories, reference data, geospatial information, web crawling data). Requests must be authenticated, so anonymous access to a Requester Pays bucket is not allowed; when a requester assumes an IAM role, the account the role belongs to is charged.`,`requester-pays`,[`Typically, you configure buckets to be Requester Pays buckets when you want to share data but not incur charges associated with others accessing the data.`,`For example, you might use Requester Pays buckets when making available large datasets, such as zip code directories, reference data, geospatial information, or web crawling data.`,`If you enable Requester Pays on a general purpose bucket, anonymous access to that bucket is not allowed.`,`When the requester assumes an AWS Identity and Access Management (IAM) role before making their request, the account to which the role belongs is charged for the request.`])],services:[`Amazon S3`],design:[n(`Cue: "share a large dataset with other accounts but the owner should not pay for their downloads" → Requester Pays bucket; the requesters must be authenticated AWS identities.`,`requester-pays`,[`The request authentication enables Amazon S3 to identify and charge the requester for their use of the Requester Pays bucket.`])]},{id:`4.1-K2`,concepts:[n(`A tag is a label, a key and a value, that you or AWS assigns to a resource. Cost allocation tags track costs at a detailed level: after you activate them, AWS uses them to organise resource costs on your cost allocation report. There are AWS-generated tags and user-defined tags, and you must activate both types separately before they appear in Cost Explorer or on a cost allocation report. All tags can take up to 24 hours to appear in the Billing and Cost Management console.`,`cost-alloc-tags`,[`A tag is a label that you or AWS assigns to an AWS resource.`,`After you activate cost allocation tags, AWS uses the cost allocation tags to organize your resource costs on your cost allocation report, to make it easier for you to categorize and track your AWS costs.`,`AWS provides two types of cost allocation tags, an AWS-generated tags and user-defined tags.`,`You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`,`All tags can take up to 24 hours to appear in the Billing and Cost Management console.`],{allow:[`two`,`24`]}),n(`Consolidated billing in AWS Organizations: the management account pays the charges of all member accounts, you get one bill, can track charges across accounts, and can combine usage across the organisation, which shares volume pricing discounts, Reserved Instance discounts and Savings Plans. It costs nothing extra.`,`consolidated-billing`,[`One bill – You get one bill for multiple accounts in the same SOR.`,`Combined usage – You can combine the usage across all accounts in the organization.`,`This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`,`No extra fee – Consolidated billing is offered at no additional cost.`]),n(`Cost allocation tags apply going forward once activated, but AWS lets the management account backfill them: it can request a backfill of cost allocation tags for up to twelve months, and the tag is then retroactively activated for those earlier months. All tags can take up to 24 hours to appear in the Billing and Cost Management console.`,[`tags-backfill`,`cost-alloc-tags`],[`tags-backfill|Management account users can request a backfill of cost allocation tags for up to twelve months.`,`tags-backfill|As a result, the Project tag is retroactively activated for the prior months from January to December 2023.`,`cost-alloc-tags|All tags can take up to 24 hours to appear in the Billing and Cost Management console.`],{newer:[`cost-allocation-tag-backfill`],allow:[`twelve`,`24`]})],services:[`AWS Organizations`],design:[n(`Cue: "attribute costs to departments or projects" → tag resources and activate the tags as cost allocation tags; "one invoice and shared discounts across many accounts" → consolidated billing under an organisation.`,[`cost-alloc-tags`,`consolidated-billing`],[`cost-alloc-tags|You can use tags to organize your resources, and cost allocation tags to track your AWS costs on a detailed level.`,`consolidated-billing|This can result in a lower charge for your project, department, or company than with individual standalone accounts.`])]},{id:`4.1-K3`,concepts:[n(`AWS Cost Explorer lets you view and analyse your costs and usage using the main graph, the cost and usage reports, or the RI reports, with filters, groupings and dates you can change.`,`ce-what-is`,[`AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`,`You can explore your usage and costs using the main graph, the Cost Explorer cost and usage reports, or the Cost Explorer RI reports.`]),n(`AWS Budgets tracks and takes action on your costs and usage: you set limits and receive alerts when costs approach or exceed a threshold, and can monitor utilisation and coverage of Reserved Instances or Savings Plans.`,`budgets-managing`,[`You can use AWS Budgets to track and take action on your AWS costs and usage.`,`You can use AWS Budgets to monitor your aggregate utilization and coverage metrics for your Reserved Instances (RIs) or Savings Plans.`]),n(`The AWS Cost and Usage Report (CUR) contains the most comprehensive set of cost and usage data available. It publishes billing reports to an S3 bucket you own, broken down by the hour, day or month, by product or product resource, or by tags you define. AWS updates the report at least once a day until your charges are finalised. AWS Data Exports describes Cost and Usage Report 2.0 (CUR 2.0) as the new and recommended way to receive detailed cost and usage data.`,[`cur-what-is`,`cur-create`,`data-exports-what-is`],[`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`,`cur-what-is|You can use Cost and Usage Reports to publish your AWS billing reports to an Amazon Simple Storage Service (Amazon S3) bucket that you own.`,`cur-what-is|You can receive reports that break down your costs by the hour, day, or month, by product or product resource, or by tags that you define yourself.`,`cur-create|After delivery starts, AWS updates the AWS Cost and Usage Reports files at least once a day.`,`data-exports-what-is|Cost and Usage Report 2.0 (CUR 2.0) is the new and recommended way to receive your detailed AWS cost and usage data.`])],services:[`AWS Cost Explorer`,`AWS Budgets`,`AWS Cost and Usage Report`],design:[n(`Cue: "visualise and explore spending trends" → Cost Explorer; "alert me when spending crosses a limit" → Budgets; "line-item data for custom analysis (for example with Athena)" → Cost and Usage Report.`,[`ce-what-is`,`budgets-managing`,`cur-what-is`],[`ce-what-is|AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`,`budgets-managing|Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`,`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`])]}],cues:[e(`the data consumers, not the bucket owner, should pay for downloads`,`S3 Requester Pays bucket`,n(`With Requester Pays, the requester pays the request and download costs.`,`requester-pays`,[`With Requester Pays buckets, the requester instead of the bucket owner pays the cost of the request and the data download from the bucket.`])),e(`allocate costs by project or department`,`Cost allocation tags (activated)`,n(`Cost allocation tags organise resource costs on the cost allocation report.`,`cost-alloc-tags`,[`After you activate cost allocation tags, AWS uses the cost allocation tags to organize your resource costs on your cost allocation report, to make it easier for you to categorize and track your AWS costs.`])),e(`single bill and shared volume discounts across accounts`,`Consolidated billing (AWS Organizations)`,n(`Consolidated billing gives one bill and combined usage across accounts at no extra fee.`,`consolidated-billing`,[`No extra fee – Consolidated billing is offered at no additional cost.`])),e(`analyse and visualise cost and usage over time`,`AWS Cost Explorer`,n(`Cost Explorer views and analyses costs and usage.`,`ce-what-is`,[`AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`])),e(`alert when actual or forecast spending exceeds a threshold`,`AWS Budgets`,n(`Budgets alerts when costs approach or exceed your threshold.`,`budgets-managing`,[`Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`])),e(`most detailed billing data delivered to S3 for analysis`,`AWS Cost and Usage Report`,n(`CUR is the most comprehensive set of cost and usage data and is published to your S3 bucket.`,`cur-what-is`,[`You can use Cost and Usage Reports to publish your AWS billing reports to an Amazon Simple Storage Service (Amazon S3) bucket that you own.`]))],examples:[],confuse:[],azure:[{concept:`Microsoft Cost Management`,aws:`AWS Billing and Cost Management (Cost Explorer, Budgets)`,mapping:n(`Learn pairs AWS Billing and Cost Management with Microsoft Cost Management, which helps you understand your Azure bill, manage your billing account and subscriptions, monitor and control spending, and optimise resource use.`,[`learn-hub`,`ce-what-is`],[`learn-hub|AWS Billing and Cost Management Microsoft Cost Management Cost Management helps you understand your Azure invoice or bill.`,`learn-hub|It also helps you manage your billing account and subscriptions, monitor and control Azure spending, and optimize resource use.`,`ce-what-is|AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`]),breaks:n(`On AWS the job is split across separate tools: Cost Explorer to view and analyse costs and usage, Budgets to track and take action on them, and the Cost and Usage Report for the most comprehensive data set. Learn pairs the billing service as a whole with Microsoft Cost Management.`,[`ce-what-is`,`budgets-managing`,`cur-what-is`,`learn-hub`],[`ce-what-is|AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`,`budgets-managing|You can use AWS Budgets to track and take action on your AWS costs and usage.`,`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`,`learn-hub|AWS Billing and Cost Management Microsoft Cost Management Cost Management helps you understand your Azure invoice or bill.`])},{concept:`Cost details APIs / Cost Management + Billing`,aws:`AWS Cost and Usage Reports`,mapping:n(`Learn pairs Cost and Usage Reports with the cost details APIs and Cost Management + Billing: services that generate, monitor, forecast and share billing data by time, organisation or product resource.`,[`learn-hub`,`cur-what-is`],[`learn-hub|Cost and Usage Reports Cost details APIs Cost Management + Billing These services help you generate, monitor, forecast, and share billing data for resource usage by time, organization, or product resources.`,`cur-what-is|You can receive reports that break down your costs by the hour, day, or month, by product or product resource, or by tags that you define yourself.`]),breaks:n(`Learn pairs Cost and Usage Reports with Azure's cost details APIs and Cost Management + Billing. On AWS, Cost and Usage Reports publish AWS billing reports to an S3 bucket you own.`,[`cur-what-is`,`learn-hub`],[`cur-what-is|You can use Cost and Usage Reports to publish your AWS billing reports to an Amazon Simple Storage Service (Amazon S3) bucket that you own.`,`learn-hub|Cost and Usage Reports Cost details APIs Cost Management + Billing These services help you generate, monitor, forecast, and share billing data for resource usage by time, organization, or product resources.`])},{concept:`Resource Manager resource groups and tags`,aws:`Cost allocation tags`,mapping:n(`Learn pairs Resource Groups and Tag Editor with Azure Resource Manager resource groups and tags: a resource group is a container that holds related resources for an Azure solution, and you apply tags to organise resources by categories.`,[`learn-hub`,`cost-alloc-tags`],[`learn-hub|A resource group is a container that holds related resources for an Azure solution.`,`learn-hub|Apply tags to your Azure resources to logically organize them by categories.`,`cost-alloc-tags|A tag is a label that you or AWS assigns to an AWS resource.`]),breaks:n(`An Azure resource group is a container of resources; an AWS tag is only a key-value label on a resource, and for billing it must be activated as a cost allocation tag before it appears in Cost Explorer or on the cost allocation report.`,[`cost-alloc-tags`,`learn-hub`],[`cost-alloc-tags|You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`,`learn-hub|A resource group is a container that holds related resources for an Azure solution.`])}]},h={building:`nat-toll`,overview:[n(`A NAT gateway lets instances in a private subnet reach services outside the VPC while outside services cannot start a connection to them. It is a common hidden cost: you are charged for each hour the NAT gateway is available and each gigabyte of data it processes. The choices that move the bill are NAT gateway or NAT instance, how many NAT gateways you run and where, and how much traffic you send through them. Gatehouse (Citadel) explained what a NAT gateway is; this building is about its cost.`,[`vpc-nat-gateway`,`vpc-nat-pricing`],[`vpc-nat-gateway|You can use a NAT gateway so that instances in a private subnet can connect to services outside your VPC but external services can't initiate a connection with those instances.`,`vpc-nat-pricing|When you provision a NAT gateway, you are charged for each hour that your NAT gateway is available and each gigabyte of data that it processes.`])],bullets:[{id:`4.4-K4`,concepts:[n(`A NAT gateway is managed by AWS, so you do not perform maintenance, while a NAT instance is an EC2 instance you manage by installing software updates or operating system patches. AWS recommends NAT gateways because they provide better availability and bandwidth and require less effort to administer.`,`vpc-nat-comparison`,[`We recommend that you use NAT gateways because they provide better availability and bandwidth and require less effort on your part to administer.`,`Managed by AWS. You do not need to perform any maintenance.`,`Managed by you, for example, by installing software updates or operating system patches on the instance.`]),n(`The bills are built differently. A NAT gateway is charged depending on the number of gateways, the duration of usage and the amount of data sent through them, and you do not choose a type or size. A NAT instance is charged depending on the number of instances, the duration of usage and the instance type and size, which you choose for your predicted workload. Cost per gigabyte processed therefore matters for a gateway, and right-sizing the instance matters for an instance.`,`vpc-nat-comparison`,[`Charged depending on the number of NAT gateways you use, duration of usage, and amount of data that you send through the NAT gateways.`,`Charged depending on the number of NAT instances that you use, duration of usage, and instance type and size.`,`Choose a suitable instance type and size, according to your predicted workload.`]),n(`The comparison also lists differences that a cost question may turn on: a NAT instance can be used as a bastion server and supports port forwarding by manual configuration, while a NAT gateway does not support either, and you cannot associate security groups with a NAT gateway. The full comparison is in the Don't confuse section below.`,`vpc-nat-comparison`,[`Bastion servers Not supported.`,`Use as a bastion server.`,`You cannot associate security groups with NAT gateways.`]),n(`To reduce what a NAT gateway charges for data, AWS suggests: keep resources that send or receive a lot of traffic in the same Availability Zone as the NAT gateway, or create a NAT gateway in each Availability Zone with resources; and, if most traffic through the gateway is to AWS services that support interface endpoints or gateway endpoints, create an endpoint for those services instead.`,`vpc-nat-pricing`,[`If your AWS resources send or receive a significant volume of traffic across Availability Zones, ensure that the resources are in the same Availability Zone as the NAT gateway.`,`Alternatively, create a NAT gateway in each Availability Zone with resources.`,`If most traffic through your NAT gateway is to AWS services that support interface endpoints or gateway endpoints, consider creating an interface endpoint or gateway endpoint for these services.`]),n(`The endpoint types are billed very differently. Gateway endpoints (for S3 and DynamoDB) have no data processing or hourly charges. Interface endpoints are billed for each hour the endpoint remains provisioned in each Availability Zone, plus data processing charges for each gigabyte processed through the endpoint. Replacing NAT traffic with an interface endpoint therefore trades one set of charges for another, so the saving depends on the traffic; replacing it with a gateway endpoint adds no endpoint charge.`,[`vpc-pricing`,`privatelink-pricing`,`vpce-gateway`],[`vpc-pricing|There are no data processing or hourly charges for using Gateway Type VPC endpoints.`,`vpce-gateway|Gateway VPC endpoints provide reliable connectivity to Amazon S3 and DynamoDB without requiring an internet gateway or a NAT device for your VPC.`,`vpce-gateway|There is no additional charge for using gateway endpoints.`,`privatelink-pricing|You will be billed for each hour that your VPC endpoint remains provisioned in each Availability Zone, irrespective of the state of its association with the service (learn more).`,`privatelink-pricing|Data processing charges apply for each Gigabyte processed through the VPC endpoint regardless of the traffic’s source or destination.`])],services:[`Amazon VPC`,`Amazon EC2`],design:[n(`Cue: "private instances need outbound internet, least administration" → NAT gateway; "most of the NAT traffic goes to S3 or DynamoDB" → add a gateway endpoint (no endpoint charge) so that traffic bypasses the NAT gateway; "to other AWS services" → an interface endpoint, which bills hourly and per gigabyte; "need a bastion or port forwarding on the NAT device" → NAT instance.`,[`vpc-nat-comparison`,`vpc-nat-pricing`,`vpc-pricing`,`privatelink-pricing`,`vpce-gateway`],[`vpc-pricing|There are no data processing or hourly charges for using Gateway Type VPC endpoints.`,`vpce-gateway|Gateway VPC endpoints provide reliable connectivity to Amazon S3 and DynamoDB without requiring an internet gateway or a NAT device for your VPC.`,`privatelink-pricing|Data processing charges apply for each Gigabyte processed through the VPC endpoint regardless of the traffic’s source or destination.`,`vpc-nat-comparison|We recommend that you use NAT gateways because they provide better availability and bandwidth and require less effort on your part to administer.`,`vpc-nat-pricing|If most traffic through your NAT gateway is to AWS services that support interface endpoints or gateway endpoints, consider creating an interface endpoint or gateway endpoint for these services.`])]},{id:`4.4-S1`,concepts:[n(`Public or private is the first choice. You use a public NAT gateway so that instances in a private subnet can send outbound traffic to the internet while the internet cannot start connections to them. You use a private NAT gateway to reach your on-premises network with a pool of allow-listed addresses, or to communicate between networks that have overlapping CIDR ranges.`,`vpc-nat-scenarios`,[`You can use a public NAT gateway to enable instances in a private subnet to send outbound traffic to the internet, while preventing the internet from establishing connections to the instances.`,`You can use a private NAT gateway to enable communication from your VPCs to your on-premises network using a pool of allow-listed addresses.`,`You can use a private NAT gateway to enable communication between networks even if they have overlapping CIDR ranges.`]),n(`One shared NAT gateway or one per Availability Zone? Each NAT gateway is created in one Availability Zone with redundancy in that zone. A single shared gateway has the lowest hourly cost, but if resources in several zones share it and its zone goes down, resources in the other zones lose internet access, and traffic from other zones crosses Availability Zones to reach it, which AWS lists as a data transfer cost. A gateway per zone with matching routing costs more in hourly charges, but is zone-independent and keeps traffic in its zone.`,[`vpc-nat-basics`,`vpc-nat-comparison`,`vpc-nat-pricing`],[`vpc-nat-basics|If you have resources in multiple Availability Zones and they share one NAT gateway, and if the NAT gateway's Availability Zone is down, resources in the other Availability Zones lose internet access.`,`vpc-nat-comparison|Create a NAT gateway in each Availability Zone to ensure zone-independent architecture.`,`vpc-nat-pricing|If your AWS resources send or receive a significant volume of traffic across Availability Zones, ensure that the resources are in the same Availability Zone as the NAT gateway.`]),n(`A regional NAT gateway is the third pattern. It automatically expands across Availability Zones based on your workload presence, where standard (zonal) NAT gateways operate in a single Availability Zone, and AWS recommends considering it for all use cases except those that require private connectivity. A regional NAT gateway does not offer private connectivity, so use the zonal mode for private NAT use cases. For pricing information, AWS refers to Amazon VPC Pricing.`,`vpc-nat-regional`,[`A regional NAT gateway automatically expands across Availability Zones based on your workload presence.`,`Unlike standard NAT gateways (referred to as zonal NAT gateways), which operate in a single Availability Zone, regional NAT gateways follow your workloads to provide automatic high availability.`,`Consider using Regional NAT Gateways for all use cases except those that require private connectivity.`,`Regional NAT Gateways do not offer private connectivity and we recommend using your NAT Gateways in zonal availability mode for private NAT use cases.`,`For pricing information, see Amazon VPC Pricing.`],{newer:[`regional-nat-gateway`]})],services:[`Amazon VPC`],design:[n(`Cue: "lowest cost, development environment, accepts zone dependency" → one shared NAT gateway; "production, avoid cross-zone data charges and a single point of failure" → a NAT gateway in each Availability Zone, with each subnet routed to its own zone's gateway; "simplify and keep high availability without managing per-zone gateways" → regional NAT gateway. This is study guidance: the wording of the question decides.`,[`vpc-nat-basics`,`vpc-nat-comparison`,`vpc-nat-regional`],[`vpc-nat-basics|If you have resources in multiple Availability Zones and they share one NAT gateway, and if the NAT gateway's Availability Zone is down, resources in the other Availability Zones lose internet access.`,`vpc-nat-comparison|Create a NAT gateway in each Availability Zone to ensure zone-independent architecture.`,`vpc-nat-regional|A regional NAT gateway automatically expands across Availability Zones based on your workload presence.`],{newer:[`regional-nat-gateway`]})]}],cues:[e(`private subnet needs outbound internet with the least administration`,`NAT gateway`,n(`AWS recommends NAT gateways for better availability and bandwidth with less administration.`,`vpc-nat-comparison`,[`We recommend that you use NAT gateways because they provide better availability and bandwidth and require less effort on your part to administer.`])),e(`NAT charges are high and most traffic goes to S3 or DynamoDB`,`Gateway endpoint (and interface endpoints) instead of NAT`,n(`If most NAT traffic is to services that support endpoints, consider creating an endpoint.`,`vpc-nat-pricing`,[`If most traffic through your NAT gateway is to AWS services that support interface endpoints or gateway endpoints, consider creating an interface endpoint or gateway endpoint for these services.`])),e(`NAT data transfer charges across Availability Zones`,`Same-zone NAT gateway per Availability Zone with resources`,n(`Keep resources in the same Availability Zone as the NAT gateway or create one in each zone with resources.`,`vpc-nat-pricing`,[`Alternatively, create a NAT gateway in each Availability Zone with resources.`])),e(`NAT must survive an Availability Zone failure`,`A NAT gateway in each Availability Zone (or a regional NAT gateway)`,n(`Create a NAT gateway in each Availability Zone to ensure zone-independent architecture.`,`vpc-nat-comparison`,[`Create a NAT gateway in each Availability Zone to ensure zone-independent architecture.`])),e(`overlapping CIDR ranges or allow-listed addresses to on-premises`,`Private NAT gateway`,n(`A private NAT gateway enables communication between networks even if they have overlapping CIDR ranges.`,`vpc-nat-scenarios`,[`You can use a private NAT gateway to enable communication between networks even if they have overlapping CIDR ranges.`])),e(`NAT device also needed as a bastion or for port forwarding`,`NAT instance`,n(`A NAT instance can be used as a bastion server; a NAT gateway does not support bastion servers.`,`vpc-nat-comparison`,[`Use as a bastion server.`]))],examples:[],confuse:[`nat-gateway-vs-instance`],azure:[{concept:`Azure NAT Gateway`,aws:`AWS NAT gateways`,mapping:n(`Learn pairs AWS NAT gateways with Azure NAT Gateway: these services simplify outbound-only Internet connectivity for virtual networks.`,[`learn-networking`,`vpc-nat-gateway`],[`learn-networking|These services simplify outbound-only Internet connectivity for virtual networks.`,`vpc-nat-gateway|You can use a NAT gateway so that instances in a private subnet can connect to services outside your VPC but external services can't initiate a connection with those instances.`]),breaks:n(`Learn says AWS NAT gateways can be associated with only a single public IP and that Azure NAT gateways can have multiple public IPs. AWS says you can increase this limit by associating up to 8 IPv4 addresses with a NAT gateway (1 primary and 7 secondary), so the sources differ on this point.`,[`learn-networking`,`vpc-nat-basics`],[`learn-networking|AWS NAT gateways can be associated with only a single public IP.`,`learn-networking|Azure NAT gateways can have multiple public IPs.`,`vpc-nat-basics|You can increase this limit by associating up to 8 IPv4 addresses to your NAT gateways (1 primary IPv4 address and 7 secondary IPv4 addresses).`],{allow:[`8`,`1`,`7`]})}]},g={building:`network-cost-audit`,overview:[n(`The audit building is about finding network costs in an existing workload. Cost Explorer can show which service you use the most and which Availability Zone most of your traffic is in, cost allocation tags let you track AWS costs on a detailed level, and Trusted Advisor has checks such as Idle NAT gateways. The fixes themselves are in NAT Toll, Transit Tariff and Route Tariff.`,[`ce-filtering`,`cost-alloc-tags`,`trusted-advisor-cost-checks`],[`ce-filtering|You can use Cost Explorer to see which service you use the most, which Availability Zone (AZ) most of your traffic is in, and which member account uses AWS the most.`,`cost-alloc-tags|You can use tags to organize your resources, and cost allocation tags to track your AWS costs on a detailed level.`,`trusted-advisor-cost-checks|Idle NAT gateways`])],bullets:[{id:`4.4-K1`,concepts:[n(`Cost allocation tags let you attribute network costs, such as a NAT gateway or a load balancer, to the team or application that uses it. A tag is a label that you or AWS assigns to a resource, and you must activate it as a cost allocation tag before it appears in Cost Explorer or on a cost allocation report.`,`cost-alloc-tags`,[`A tag is a label that you or AWS assigns to an AWS resource.`,`You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`]),n(`Multi-account billing shows network cost across an organisation. With consolidated billing the management account pays the charges of all member accounts, you can track charges across accounts, and in Cost Explorer you can use the Linked Account and Service filters to identify the member account that spent the most on a service.`,[`consolidated-billing`,`ce-filtering`],[`consolidated-billing|Every organization in AWS Organizations has a management account that pays the charges of all the member accounts.`,`ce-filtering|For example, you can use the Linked Account and Services filters to identify the member account that spent the most money on Amazon EC2.`])],services:[`AWS Organizations`],design:[n(`Cue: "which team is responsible for the NAT or load balancer cost?" → cost allocation tags; "which account spends most?" → Cost Explorer grouped by linked account.`,[`cost-alloc-tags`,`ce-filtering`],[`cost-alloc-tags|After you activate cost allocation tags, AWS uses the cost allocation tags to organize your resource costs on your cost allocation report, to make it easier for you to categorize and track your AWS costs.`,`ce-filtering|For example, you can use the Linked Account and Services filters to identify the member account that spent the most money on Amazon EC2.`])]},{id:`4.4-K2`,concepts:[n(`Cost Explorer filters costs by values that include Availability Zone, Region, Service, Tag, Usage type and Usage type group, and you can refine the analysis with multiple filters and by grouping the data. That is how you find which Region or Availability Zone most of the traffic and cost is in.`,`ce-filtering`,[`With Cost Explorer, you can filter how you view your AWS costs by one or more of the following values: API operation Availability Zone (AZ) Billing entity Charge type Include all Instance type Legal entity Linked account Platform Product attribute Purchase option Region Resources Service Tag Tenancy Usage type Usage type group`,`You can continue refining your cost analysis by using multiple filters, grouping your data by filter type, and choosing Advanced Options tab options.`]),n(`Cost Explorer shows spend by dimensions such as service and Availability Zone. To see traffic itself, VPC Flow Logs capture information about the IP traffic going to and from network interfaces, and the NAT gateway metric BytesOutToDestination is the number of bytes sent out through the NAT gateway to the destination. AWS Cost Anomaly Detection uses machine learning models to detect and alert on anomalous spend patterns.`,[`vpc-flow-logs`,`vpc-nat-metrics`,`cost-anomaly`,`ce-filtering`],[`vpc-flow-logs|VPC Flow Logs is a feature that enables you to capture information about the IP traffic going to and from network interfaces in your VPC.`,`vpc-nat-metrics|BytesOutToDestination The number of bytes sent out through the NAT gateway to the destination.`,`cost-anomaly|AWS Cost Anomaly Detection is a feature that uses machine learning models to detect and alert on anomalous spend patterns in your deployed AWS services.`,`ce-filtering|You can use Cost Explorer to see which service you use the most, which Availability Zone (AZ) most of your traffic is in, and which member account uses AWS the most.`]),n(`AWS Budgets sets spending limits and alerts when costs approach or exceed a threshold, so an unexpected jump in network spend is caught early. The Cost and Usage Report is the most comprehensive set of cost and usage data available, published to an S3 bucket you own and broken down by product or product resource, so it holds the line items behind a transfer charge.`,[`budgets-managing`,`cur-what-is`],[`budgets-managing|Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`,`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`,`cur-what-is|You can receive reports that break down your costs by the hour, day, or month, by product or product resource, or by tags that you define yourself.`])],services:[`AWS Cost Explorer`,`AWS Budgets`,`AWS Cost and Usage Report`],design:[n(`Cue: "see which Region or Availability Zone drives the cost" → Cost Explorer filters; "alert when network spend passes a limit" → Budgets; "line-item detail to query" → Cost and Usage Report.`,[`ce-filtering`,`budgets-managing`,`cur-what-is`],[`ce-filtering|You can use Cost Explorer to see which service you use the most, which Availability Zone (AZ) most of your traffic is in, and which member account uses AWS the most.`,`budgets-managing|Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`,`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`])]},{id:`4.4-S5`,concepts:[n(`Trusted Advisor inspects your AWS environment and recommends where to save money. Its cost optimization checks include idle NAT gateways, idle load balancers, inactive VPC interface endpoints and unassociated Elastic IP addresses, each a network resource that you pay for whether or not traffic uses it.`,[`trusted-advisor`,`trusted-advisor-cost-checks`],[`trusted-advisor|Trusted Advisor inspects your AWS environment, and then makes recommendations when opportunities exist to save money, improve system availability and performance, or help close security gaps.`,`trusted-advisor-cost-checks|Idle Load Balancers`,`trusted-advisor-cost-checks|Idle NAT gateways`,`trusted-advisor-cost-checks|Inactive VPC interface endpoints`,`trusted-advisor-cost-checks|Unassociated Elastic IP Addresses`]),n(`Idle addresses are not the only address cost. Any public IPv4 address associated with a resource in a VPC is charged as an in-use public IPv4 address, and a public IPv4 address in your account that is not used on a resource is charged as an idle address, at the same hourly rate. So Trusted Advisor flagging unassociated Elastic IP addresses finds only part of the public IPv4 cost.`,`vpc-pricing`,[`Any public IPv4 address associated with a resource launched in an Amazon VPC, and public IPv4 addresses assigned to AWS Global Accelerator and AWS Site-to-Site VPN tunnel endpoints are charged as in-use public IPv4 address.`,`Any public IPv4 address associated to your AWS account that is not used on a resource is charged as idle public IPv4 address.`,`You pay an hourly rate for each public IPv4 address used by your AWS account.`,`The price is the same whether the public IPv4 address is in-use public IPv4 addresses that is associated with an AWS resource you own, or an idle public IPv4 addresses in your AWS account not associated with any AWS resources.`]),n(`Which checks you can use depends on the support plan. With the Basic Support plan you can access all checks in the Service Limits category and selected checks in the Security and Fault tolerance categories, which does not include the cost optimization category; with Business Support+, Enterprise Support or Unified Operations you can access all Trusted Advisor checks.`,`trusted-advisor`,[`If you have a Basic Support plan, you can use the Trusted Advisor console to access all checks in the Service Limits category and selected checks in the Security and Fault tolerance categories.`,`If you have a AWS Business Support+, AWS Enterprise Support, or AWS Unified Operations plan, you can use the Trusted Advisor console and the AWS Trusted Advisor API to access all Trusted Advisor checks.`]),n(`The same page announces that Developer Support and Business Support will be discontinued on 1 January 2027, with Business Support+ as the upgrade for Business Support customers.`,`trusted-advisor`,[`End of Support Notice: Developer Support will be discontinued January 1, 2027.`,`End of Support Notice: Business Support will be discontinued January 1, 2027.`],{status:`deprecated`,allow:[`1`,`2027`]}),n(`Compute Optimizer is another review tool. It generates recommendations for resources that include Amazon NAT Gateway, alongside EC2 instances, Auto Scaling groups, EBS volumes and Lambda functions, once they have accumulated sufficient metric data.`,`compute-optimizer`,[`Compute Optimizer generates recommendations for the following resources: Amazon Elastic Compute Cloud (Amazon EC2) instances Amazon EC2 Auto Scaling groups Amazon Elastic Block Store (Amazon EBS) volumes AWS Lambda functions Amazon Elastic Container Service (Amazon ECS) services on AWS Fargate Commercial software licenses Amazon Aurora and Amazon Relational Database Service (Amazon RDS) databases Amazon NAT Gateway`,`For Compute Optimizer to generate recommendations for these resources, they must meet a specific set of requirements, and must have accumulated sufficient metric data.`])],services:[`AWS Trusted Advisor`,`AWS Cost Explorer`],design:[n(`Cue: "review an existing workload for wasted network spend" → Trusted Advisor cost checks (idle NAT gateways, idle load balancers, inactive interface endpoints, unassociated Elastic IP addresses) plus Cost Explorer by Region and Availability Zone; "unused Elastic IP addresses" → Trusted Advisor flags unassociated ones, but public IPv4 addresses in use on a resource are charged as in-use public IPv4 addresses too.`,[`trusted-advisor-cost-checks`,`ce-filtering`,`trusted-advisor`,`vpc-pricing`],[`trusted-advisor-cost-checks|Idle NAT gateways`,`trusted-advisor-cost-checks|Unassociated Elastic IP Addresses`,`trusted-advisor-cost-checks|Inactive VPC interface endpoints`,`vpc-pricing|Any public IPv4 address associated with a resource launched in an Amazon VPC, and public IPv4 addresses assigned to AWS Global Accelerator and AWS Site-to-Site VPN tunnel endpoints are charged as in-use public IPv4 address.`,`trusted-advisor-cost-checks|Idle Load Balancers`,`ce-filtering|You can use Cost Explorer to see which service you use the most, which Availability Zone (AZ) most of your traffic is in, and which member account uses AWS the most.`,`trusted-advisor|If you have a AWS Business Support+, AWS Enterprise Support, or AWS Unified Operations plan, you can use the Trusted Advisor console and the AWS Trusted Advisor API to access all Trusted Advisor checks.`])]}],cues:[e(`find which Availability Zone or Region carries the traffic and cost`,`Cost Explorer filters (Availability Zone, Region, Usage type)`,n(`Cost Explorer can show which Availability Zone most of your traffic is in.`,`ce-filtering`,[`You can use Cost Explorer to see which service you use the most, which Availability Zone (AZ) most of your traffic is in, and which member account uses AWS the most.`])),e(`NAT gateways or load balancers that carry little or no traffic`,`Trusted Advisor idle-resource checks`,n(`Trusted Advisor cost optimization checks include Idle NAT gateways and Idle Load Balancers.`,`trusted-advisor-cost-checks`,[`Idle NAT gateways`,`Idle Load Balancers`])),e(`Elastic IP addresses not attached to anything`,`Trusted Advisor: Unassociated Elastic IP Addresses`,n(`Trusted Advisor has a check for unassociated Elastic IP addresses.`,`trusted-advisor-cost-checks`,[`Unassociated Elastic IP Addresses`])),e(`interface endpoints that nobody uses`,`Trusted Advisor: Inactive VPC interface endpoints`,n(`Trusted Advisor has a check for inactive VPC interface endpoints.`,`trusted-advisor-cost-checks`,[`Inactive VPC interface endpoints`])),e(`charge network costs back to a team`,`Cost allocation tags`,n(`Cost allocation tags organise resource costs on your cost allocation report.`,`cost-alloc-tags`,[`After you activate cost allocation tags, AWS uses the cost allocation tags to organize your resource costs on your cost allocation report, to make it easier for you to categorize and track your AWS costs.`]))],examples:[],confuse:[],azure:[{concept:`Microsoft Cost Management`,aws:`AWS Billing and Cost Management (Cost Explorer, Budgets)`,mapping:n(`Learn pairs AWS Billing and Cost Management with Microsoft Cost Management, which helps you understand your Azure invoice or bill and monitor and control Azure spending. On AWS, Cost Explorer adds filters such as Availability Zone and Region for network analysis.`,[`learn-hub`,`ce-filtering`],[`learn-hub|It also helps you manage your billing account and subscriptions, monitor and control Azure spending, and optimize resource use.`,`ce-filtering|You can use Cost Explorer to see which service you use the most, which Availability Zone (AZ) most of your traffic is in, and which member account uses AWS the most.`]),breaks:n(`Learn pairs the billing service as a whole with Microsoft Cost Management. On AWS, Cost Explorer shows which Availability Zone most of your traffic is in, and Trusted Advisor has a check for idle NAT gateways.`,[`trusted-advisor-cost-checks`,`ce-filtering`,`learn-hub`],[`trusted-advisor-cost-checks|Idle NAT gateways`,`ce-filtering|You can use Cost Explorer to see which service you use the most, which Availability Zone (AZ) most of your traffic is in, and which member account uses AWS the most.`,`learn-hub|AWS Billing and Cost Management Microsoft Cost Management Cost Management helps you understand your Azure invoice or bill.`])},{concept:`Azure Advisor`,aws:`AWS Trusted Advisor`,mapping:n(`Learn pairs AWS Trusted Advisor with Azure Advisor: Trusted Advisor provides checks across cost optimization, security, performance, fault tolerance and service limits.`,[`learn-compute`,`trusted-advisor`],[`learn-compute|AWS Trusted Advisor provides checks across cost optimization, security, performance, fault tolerance, and service limits.`,`trusted-advisor|Trusted Advisor inspects your AWS environment, and then makes recommendations when opportunities exist to save money, improve system availability and performance, or help close security gaps.`]),breaks:n(`Which Trusted Advisor checks you can use depends on the AWS support plan: with the Basic Support plan you can access all checks in the Service Limits category and selected checks in the Security and Fault tolerance categories, and the full set needs a higher plan. Learn pairs Trusted Advisor with Azure Advisor and lists the check categories; the Learn text does not mention a support plan limit.`,[`trusted-advisor`,`learn-compute`],[`trusted-advisor|If you have a Basic Support plan, you can use the Trusted Advisor console to access all checks in the Service Limits category and selected checks in the Security and Fault tolerance categories.`,`learn-compute|AWS Trusted Advisor provides checks across cost optimization, security, performance, fault tolerance, and service limits.`])}]},_={building:`retention-records`,overview:[n(`Database backups count toward your Region's backup storage while they exist. Automated backups are kept for the RDS backup retention period, while manual snapshots do not expire and keep counting until you delete them. For databases the controls are the RDS backup retention period, manual snapshots, and AWS Backup plans.`,[`rds-automated-backups`,`rds-backup-retention`,`rds-snapshot-create`,`backup-plans`],[`rds-automated-backups|RDS saves the automated backups of your DB instance according to the backup retention period that you specify.`,`rds-automated-backups|Your Amazon RDS backup storage for each AWS Region is composed of the automated backups and manual DB snapshots for that Region.`,`rds-backup-retention|You can set the backup retention period of a DB instance to between 0 and 35 days.`,`rds-snapshot-create|Snapshots don't expire.`,`backup-plans|AWS Backup also seamlessly manages your backup plan's lifecycle based on your retention settings, which allows you to restore when needed.`])],bullets:[{id:`4.3-K4`,concepts:[n(`A data retention policy states how long data and its backups must be kept, and when they may be deleted. For an RDS DB instance the retention period applies to automated backups: you set it when you create or restore a DB instance, and the console default is seven days while the API and CLI default is one day if you do not set it. The retention period of a DB instance is between 0 and 35 days, and setting it to 0 disables automated backups. For Aurora, you specify a retention period from 1 to 35 days for a DB cluster.`,[`rds-backup-retention`,`aurora-backups`],[`You can set the backup retention period when you create or restore a DB instance or Multi-AZ DB cluster.`,`If you create a DB instance using the Amazon RDS API or the AWS CLI and if you don't set the backup retention period, the default backup retention period is one day.`,`If you create a DB instance using the console, the default backup retention period is seven days.`,`You can set the backup retention period of a DB instance to between 0 and 35 days.`,`Setting the backup retention period to 0 disables automated backups.`,`aurora-backups|You can specify a backup retention period from 1–35 days when you create or modify or restore a DB cluster.`]),n(`Automated backups belong to the DB instance. If you do not choose Retain automated backups when you delete a DB instance, all automated backups are deleted with it, while manual snapshots are not deleted when an instance is deleted. A point-in-time restore creates a new DB instance without modifying the source DB instance, so it adds the cost of a second instance.`,[`rds-automated-backups`,`rds-pitr`],[`rds-automated-backups|If you don't choose Retain automated backups when you delete a DB instance, all automated backups are deleted with the DB instance.`,`rds-automated-backups|Manual snapshots are not deleted when an instance is deleted.`,`rds-pitr|You can restore a DB instance to a specific point in time, creating a new DB instance without modifying the source DB instance.`]),n(`Manual DB snapshots follow a different rule: unlike automated backups, manual snapshots are not subject to the backup retention period. Snapshots don't expire, so they remain until you delete them, and they count toward the Region's backup storage.`,[`rds-snapshot-create`,`rds-automated-backups`],[`rds-snapshot-create|Unlike automated backups, manual snapshots aren't subject to the backup retention period.`,`rds-snapshot-create|Snapshots don't expire.`,`rds-automated-backups|Your Amazon RDS backup storage for each AWS Region is composed of the automated backups and manual DB snapshots for that Region.`]),n(`Retention in AWS Backup lives in the backup plan. AWS Backup manages your backup plan's lifecycle based on your retention settings. If you lock a vault, backups in it cannot be deleted until their lifecycle completes, so AWS tells you to set retention appropriately to avoid unintended storage costs. Vault Lock has two modes: a vault locked in governance mode can be managed or deleted by users with the appropriate IAM permissions, while a compliance mode lock becomes immutable after its cooling-off period (grace time) expires.`,[`backup-plans`,`backup-vault-lock`],[`backup-plans|AWS Backup also seamlessly manages your backup plan's lifecycle based on your retention settings, which allows you to restore when needed.`,`backup-vault-lock|Because backups in a locked vault cannot be deleted until their lifecycle completes, ensure your retention settings are configured appropriately to avoid unintended storage costs.`,`backup-vault-lock|When you create a vault lock, you have a choice of two modes: Governance mode or Compliance mode.`,`backup-vault-lock|A vault locked in Governance mode can be managed or deleted by users who have the appropriate IAM permissions.`,`backup-vault-lock|Vaults locked in compliance mode cannot be deleted once the cooling-off period ("grace time") expires if any recovery points are in the vault.`,`backup-vault-lock|Once the grace time expires, the vault and its lock are immutable and cannot be changed or deleted by any user or by AWS.`])],services:[`AWS Backup`,`Amazon RDS`],design:[n(`Cue: "keep database backups only as long as policy requires, minimise storage" → delete old manual snapshots, which keep counting until you delete them, and, as study guidance, set the shortest retention period that meets the requirement; "retention must be enforced and cannot be shortened" → Backup Vault Lock (Archive Annex). Compliance mode is the immutable one: once its grace time expires, the vault and its lock cannot be changed or deleted by any user or by AWS.`,[`rds-backup-retention`,`rds-snapshot-create`,`backup-vault-lock`],[`rds-backup-retention|You can set the backup retention period of a DB instance to between 0 and 35 days.`,`rds-snapshot-create|Unlike automated backups, manual snapshots aren't subject to the backup retention period.`,`rds-snapshot-create|Snapshots don't expire.`,`backup-vault-lock|Vaults locked in compliance mode cannot be deleted once the cooling-off period ("grace time") expires if any recovery points are in the vault.`,`backup-vault-lock|Once the grace time expires, the vault and its lock are immutable and cannot be changed or deleted by any user or by AWS.`])]},{id:`4.3-S1`,concepts:[n(`Snapshot frequency sets the recovery point. For RDS, automated backups include transaction logs that RDS uploads to Amazon S3 every five minutes, so you can restore a DB instance to a specific point in time during the retention period without taking a snapshot every few minutes. Take manual snapshots for specific events, such as before a major change, and for long-term keeps.`,[`rds-pitr`,`rds-automated-backups`],[`rds-pitr|RDS uploads transaction logs for DB instances to Amazon S3 every five minutes.`,`rds-automated-backups|If necessary, you can recover your DB instance to any point in time during the backup retention period.`]),n(`In AWS Backup you choose how often a plan creates a backup in the backup rule: the rule sets the schedule, the window and the lifecycle. The more often it runs the smaller the possible data loss, and the more backups there are to store; incremental backups reduce that storage because only changes after the first full copy are backed up.`,[`backup-create-plan`,`backup-what-is`],[`backup-create-plan|In the backup rule configuration section, you will set the backup schedule, window, and lifecycle.`,`backup-create-plan|In the backup frequency menu, choose how often you want this plan to create a backup.`,`backup-what-is|For each successive incremental backup, only the changes to your AWS resources are backed up.`]),n(`A recovery point objective (see Disaster Bunker) sets the frequency. As study guidance, match the policy to the requirement, not to the maximum: a compliance requirement sets the minimum retention, and everything else is cost to be removed. AWS Backup lifecycle policies can move backups that must be kept long-term but rarely restored into a low-cost cold storage tier (Backup Archive and Cold Cellar).`,[`dr-options`,`backup-what-is`],[`dr-options|How often you run your backup will determine your achievable recovery point (which should align to meet your RPO).`,`backup-what-is|AWS Backup enables you to meet compliance requirements while minimizing backup storage costs by storing backups in a low-cost cold storage tier.`,`backup-what-is|You can configure lifecycle policies that automatically transition backups from warm storage to cold storage according to a schedule that you define.`])],services:[`AWS Backup`,`Amazon RDS`],design:[n(`Cue: "restore to any moment in the last few days" → RDS automated backups with point-in-time restore; "centralised policy across several services with scheduled backups" → AWS Backup plan; "reduce backup storage cost" → shorter retention, incremental backups, delete unneeded manual snapshots.`,[`rds-pitr`,`backup-create-plan`,`backup-what-is`],[`rds-pitr|RDS uploads transaction logs for DB instances to Amazon S3 every five minutes.`,`backup-create-plan|In the backup frequency menu, choose how often you want this plan to create a backup.`,`backup-what-is|For each successive incremental backup, only the changes to your AWS resources are backed up.`])]}],cues:[e(`restore the database to a point in time within a retention window`,`RDS automated backups (retention period)`,n(`RDS can recover a DB instance to any point in time during the retention period.`,`rds-automated-backups`,[`If necessary, you can recover your DB instance to any point in time during the backup retention period.`])),e(`keep a database copy until someone deletes it, outside the retention window`,`Manual DB snapshot`,n(`Manual snapshots are not subject to the backup retention period.`,`rds-snapshot-create`,[`Unlike automated backups, manual snapshots aren't subject to the backup retention period.`])),e(`turn off automated backups for a disposable test database`,`Retention period set to 0`,n(`Setting the backup retention period to 0 disables automated backups.`,`rds-backup-retention`,[`Setting the backup retention period to 0 disables automated backups.`])),e(`scheduled backups with lifecycle across services, one policy`,`AWS Backup plan (rule with schedule, window and lifecycle)`,n(`A backup rule sets the schedule, window and lifecycle.`,`backup-create-plan`,[`In the backup rule configuration section, you will set the backup schedule, window, and lifecycle.`])),e(`backups must not be deletable before their retention ends`,`AWS Backup Vault Lock`,n(`Backups in a locked vault cannot be deleted until their lifecycle completes.`,`backup-vault-lock`,[`Because backups in a locked vault cannot be deleted until their lifecycle completes, ensure your retention settings are configured appropriately to avoid unintended storage costs.`]))],examples:[],confuse:[],azure:[{concept:`Azure Backup`,aws:`AWS Backup`,mapping:n(`Learn pairs AWS Backup with Azure Backup, used to back up and recover files, databases, disks and virtual machines.`,[`learn-storage`,`backup-what-is`],[`learn-storage|Backup Azure Backup This option is used to back up and recover files, databases, disks, and virtual machines.`,`backup-what-is|AWS Backup is a fully-managed service that makes it easy to centralize and automate data protection across AWS services, in the cloud, and on premises.`]),breaks:n(`On AWS, RDS has its own retention control: the backup retention period that you set on a DB instance, which manual snapshots are not subject to. Learn pairs AWS Backup with Azure Backup.`,[`rds-backup-retention`,`rds-snapshot-create`,`learn-storage`],[`rds-backup-retention|You can set the backup retention period of a DB instance to between 0 and 35 days.`,`rds-snapshot-create|Unlike automated backups, manual snapshots aren't subject to the backup retention period.`,`learn-storage|Backup Azure Backup This option is used to back up and recover files, databases, disks, and virtual machines.`])}]},v={building:`route-tariff`,overview:[n(`Over a VPC peering connection, data transfer that stays within an Availability Zone is free, while charges apply for transfer that crosses Availability Zones and Regions. A transit gateway charges hourly for each attachment and for the traffic processed, and gateway endpoints have no additional charge. This building covers direction rather than figures: which choice keeps traffic on the cheaper path.`,[`peering-what-is`,`tgw-what-is`,`vpce-gateway`],[`peering-what-is|All data transfer over a VPC peering connection that stays within an Availability Zone is free, even if it's between different accounts.`,`peering-what-is|Charges apply for data transfer over VPC peering connections that cross Availability Zones and Regions.`,`tgw-what-is|You are charged hourly for each attachment on a transit gateway, and you are charged for the amount of traffic processed on the transit gateway.`,`vpce-gateway|There is no additional charge for using gateway endpoints.`])],beyondProject:[n(`Your static site is served by CloudFront. The SAA cost point is that a CDN lowers cost as well as latency. Data transfer between CloudFront and your AWS origins is automatically waived when serving traffic through CloudFront, and cached content served from edge locations means fewer requests hit your origin servers, databases and other services that charge based on usage. A longer cache duration reduces the load on your origin and means files are more likely to be served from the edge cache.`,[`cloudfront-pricing`,`cloudfront-expiration`],[`cloudfront-pricing|Data transfer between CloudFront and your AWS origins is automatically waived when serving traffic through CloudFront, giving you a monthly price for both CloudFront delivery and your AWS origin’s data transfer costs to CloudFront.`,`cloudfront-pricing|you'll see fewer requests hitting your origin servers, databases, and other AWS services that charge based on usage—reducing your costs.`,`cloudfront-expiration|A longer duration also reduces the load on your origin.`])],bullets:[{id:`4.4-K6`,concepts:[n(`VPC peering connects VPCs, which can be in different Regions, so resources communicate using private IP addresses. A peering connection is neither a gateway nor a VPN connection, and does not rely on a separate piece of physical hardware. There is no charge to create a peering connection. Transitive peering relationships are not supported, so a design with many VPCs becomes a mesh of connections.`,[`peering-what-is`,`peering-basics`],[`peering-what-is|The VPCs can be in different Regions (also known as an inter-Region VPC peering connection).`,`peering-what-is|resources in the VPCs (for example, EC2 instances and Lambda functions) in different AWS Regions can communicate with each other using private IP addresses`,`peering-what-is|it is neither a gateway nor a VPN connection, and does not rely on a separate piece of physical hardware.`,`peering-what-is|There is no charge to create a VPC peering connection.`,`peering-basics|You can create multiple VPC peering connections for each VPC that you own, but transitive peering relationships are not supported.`]),n(`Transit Gateway is a network transit hub used to interconnect VPCs and on-premises networks. You attach VPCs, VPN connections, Direct Connect gateways and peering connections to it, and inter-Region peering connects transit gateways across Regions. It is charged hourly for each attachment and for the amount of traffic processed, so the hub costs more per connection than direct peering but replaces a mesh of peering connections.`,[`tgw-what-is`],[`tgw-what-is|AWS Transit Gateway is a network transit hub used to interconnect virtual private clouds (VPCs) and on-premises networks.`,`tgw-what-is|As your cloud infrastructure expands globally, inter-Region peering connects transit gateways together using the AWS Global Infrastructure.`,`tgw-what-is|You are charged hourly for each attachment on a transit gateway, and you are charged for the amount of traffic processed on the transit gateway.`]),n(`PrivateLink interface endpoints give private access to services; an interface endpoint is billed for hourly usage and data processing charges. Gateway endpoints for S3 and DynamoDB have no additional charge. The full comparison with peering and Transit Gateway is in the Don't confuse section of Grid Planning Office.`,[`vpce-interface`,`vpce-gateway`],[`vpce-interface|You are billed for hourly usage and data processing charges.`,`vpce-gateway|There is no additional charge for using gateway endpoints.`])],services:[`AWS Transit Gateway`,`Amazon VPC`,`AWS PrivateLink`],design:[n(`Cue: "a pair of VPCs need to talk, lowest cost" → VPC peering; "many VPCs and on-premises networks, simple routing" → Transit Gateway; "private access to S3 or DynamoDB at no extra charge" → gateway endpoint.`,[`peering-what-is`,`tgw-what-is`,`vpce-gateway`],[`peering-what-is|There is no charge to create a VPC peering connection.`,`tgw-what-is|AWS Transit Gateway is a network transit hub used to interconnect virtual private clouds (VPCs) and on-premises networks.`,`vpce-gateway|There is no additional charge for using gateway endpoints.`])]},{id:`4.4-K7`,concepts:[n(`Amazon Route 53 is a highly available and scalable DNS web service. It performs domain registration, DNS routing and health checking in any combination. When you create a record you choose a routing policy that determines how Route 53 responds to queries, for example latency routing for resources in multiple Regions and failover routing for active-passive failover.`,[`route53-what-is`,`route53-routing`],[`route53-what-is|Amazon Route 53 is a highly available and scalable Domain Name System (DNS) web service.`,`route53-what-is|You can use Route 53 to perform three main functions in any combination: domain registration, DNS routing, and health checking.`,`route53-routing|Latency routing policy – Use when you have resources in multiple AWS Regions and you want to route traffic to the Region that provides the best latency.`,`route53-routing|Failover routing policy – Use when you want to configure active-passive failover.`],{allow:[`three`]}),n(`Alias records route traffic to selected AWS resources such as CloudFront distributions and S3 buckets, and unlike a CNAME record you can create one at the zone apex. Route 53 does not charge for alias queries to AWS resources but does charge for CNAME queries, and its pricing lists hosted zones and records among its pricing components, so the number of hosted zones is a cost item to review.`,[`route53-alias`,`route53-pricing`],[`route53-alias|Alias records let you route traffic to selected AWS resources, such as CloudFront distributions and Amazon S3 buckets.`,`route53-alias|Unlike a CNAME record, you can create an alias record at the top node of a DNS namespace, also known as the zone apex.`,`route53-alias|Route 53 doesn't charge for alias queries to AWS resources.`,`route53-alias|Route 53 charges for CNAME queries.`,`route53-pricing|Authoritative DNS Hosted Zones and Records`])],services:[`Amazon Route 53`],design:[n(`Cue: "send users to the Region with the best latency" → latency routing; "standby in another Region" → failover routing; "root domain pointing at CloudFront or S3" → alias record.`,[`route53-routing`,`route53-alias`],[`route53-routing|Latency routing policy – Use when you have resources in multiple AWS Regions and you want to route traffic to the Region that provides the best latency.`,`route53-alias|Alias records let you route traffic to selected AWS resources, such as CloudFront distributions and Amazon S3 buckets.`])]},{id:`4.4-S3`,concepts:[n(`Availability Zone to Availability Zone: data transfer over a VPC peering connection that stays within an Availability Zone is free, while charges apply for transfer that crosses Availability Zones and Regions. For NAT gateways, keep traffic in the gateway's Availability Zone or run a gateway in each zone (NAT Toll). The same idea applies to any chatty tier: place the pieces that talk the most in the same zone unless availability requires otherwise.`,[`peering-what-is`,`vpc-nat-pricing`],[`peering-what-is|All data transfer over a VPC peering connection that stays within an Availability Zone is free, even if it's between different accounts.`,`peering-what-is|Charges apply for data transfer over VPC peering connections that cross Availability Zones and Regions.`,`vpc-nat-pricing|If your AWS resources send or receive a significant volume of traffic across Availability Zones, ensure that the resources are in the same Availability Zone as the NAT gateway.`]),n(`Region to Region: charges apply for peering traffic that crosses Regions, so replicate or move across Regions only when the requirement (disaster recovery, latency, residency) needs it, and avoid designs where a tier in one Region constantly calls a tier in another.`,`peering-what-is`,[`Charges apply for data transfer over VPC peering connections that cross Availability Zones and Regions.`]),n(`Private to public: send traffic to S3 and DynamoDB through gateway endpoints, which have no additional charge, instead of through a NAT gateway that bills for each gigabyte it processes. Note that traffic destined for S3 or DynamoDB in a different Region goes to the internet gateway because prefix lists are specific to a Region, so the endpoint only helps for the same Region.`,[`vpce-gateway`,`vpc-nat-pricing`],[`vpce-gateway|There is no additional charge for using gateway endpoints.`,`vpce-gateway|Traffic that's destined for the service (Amazon S3 or DynamoDB) in a different Region goes to the internet gateway because prefix lists are specific to a Region.`,`vpc-nat-pricing|When you provision a NAT gateway, you are charged for each hour that your NAT gateway is available and each gigabyte of data that it processes.`]),n(`Global Accelerator is for performance and availability, not for cutting transfer cost: you are charged a fixed hourly fee for every accelerator that is provisioned, plus an incremental charge over standard Data Transfer rates (DT-Premium) on the dominant direction of traffic. Choose it when the requirement is static anycast IP addresses or faster failover; otherwise CloudFront caching is the cheaper way to reduce origin traffic.`,[`ga-pricing`,`ga-what-is`],[`ga-pricing|For every accelerator that is provisioned (both enabled and disabled), you are charged a fixed hourly fee and an incremental charge over your standard Data Transfer rates, also called a Data Transfer-Premium fee (DT-Premium).`,`ga-what-is|The static IP addresses are anycast from the AWS edge network.`])],services:[`Amazon VPC`,`AWS Global Accelerator`,`AWS PrivateLink`],design:[n(`Cue: "private subnets download from S3 through a NAT gateway and the bill is high" → gateway endpoint for S3; "VPC peering connection across Availability Zones" → charges apply, so co-locate or accept the cost for availability; "need static IPs and fast regional failover" → Global Accelerator, knowing it adds a premium charge.`,[`vpce-gateway`,`peering-what-is`,`ga-pricing`],[`vpce-gateway|There is no additional charge for using gateway endpoints.`,`peering-what-is|Charges apply for data transfer over VPC peering connections that cross Availability Zones and Regions.`,`ga-pricing|For every accelerator that is provisioned (both enabled and disabled), you are charged a fixed hourly fee and an incremental charge over your standard Data Transfer rates, also called a Data Transfer-Premium fee (DT-Premium).`])]},{id:`4.4-S4`,concepts:[n(`A CDN is a strategic need when many users repeatedly request the same content from far away, or when you want to protect and offload an origin. CloudFront delivers content through edge locations and retrieves it from the origin only when it is not already in the edge location. That reduces origin requests, origin data transfer and the load on databases behind it.`,[`cloudfront-what-is`,`cloudfront-pricing`],[`cloudfront-what-is|If the content is already in the edge location with the lowest latency, CloudFront delivers it immediately.`,`cloudfront-pricing|you'll see fewer requests hitting your origin servers, databases, and other AWS services that charge based on usage—reducing your costs.`]),n(`Edge caching strategy is mostly about cache duration: you can control how long files stay in a CloudFront cache before CloudFront forwards another request to your origin. A longer duration means better performance and lower origin load, and content that changes constantly gains less from a long duration. After a file expires, the next request makes CloudFront check the origin for the latest version.`,`cloudfront-expiration`,[`You can control how long your files stay in a CloudFront cache before CloudFront forwards another request to your origin.`,`Increasing the duration means that your users get better performance because your files are more likely to be served directly from the edge cache.`,`After it expires, the next time the edge location gets a request for the file, CloudFront forwards the request to the origin to verify that the cache contains the latest version of the file.`]),n(`To update cached content without waiting for expiry, include a version identifier in file or folder names. With versioning you do not have to wait for an object to expire before CloudFront begins to serve a new version of it, and you do not have to pay for object invalidation, so a long cache duration and versioned names work together.`,`cloudfront-versioning`,[`Update existing files using versioned file names When you update existing files in a CloudFront distribution, we recommend that you include some sort of version identifier either in your file names or in your directory names to give yourself better control over your content.`,`With versioning, you don't have to wait for an object to expire before CloudFront begins to serve a new version of it, and you don't have to pay for object invalidation.`]),n(`Price class is a cost lever for how widely CloudFront serves your content. By default CloudFront serves your objects from edge locations in all CloudFront Regions, and the price class setting lets you choose the class that corresponds with the maximum price you want to pay for the service. AWS notes that your choice also affects performance for your distribution.`,`cloudfront-settings`,[`Choose the price class that corresponds with the maximum price that you want to pay for CloudFront service.`,`By default, CloudFront serves your objects from edge locations in all CloudFront Regions.`,`For more information about price classes and about how your choice of price class affects CloudFront performance for your distribution, see CloudFront pricing.`]),n(`CloudFront offers pay-as-you-go pricing and flat-rate pricing plans that combine the CDN with other AWS services into a monthly price with no overage charges. The plans combine the CDN with other AWS services.`,`cloudfront-pricing`,[`CloudFront flat-rate pricing plans combine the Amazon CloudFront global content delivery network (CDN) with multiple AWS services and features into a monthly price with no overage charges.`])],services:[`Amazon CloudFront`],design:[n(`Cue: "global users, mostly static content, reduce origin cost" → CloudFront with a long cache duration; check price class when the question limits where users are; "content changes often" → shorter duration or invalidation; "static IP addresses for the endpoint" → Global Accelerator, whose static IP addresses are anycast from the AWS edge network.`,[`cloudfront-what-is`,`cloudfront-expiration`,`ga-what-is`],[`cloudfront-what-is|If the content is already in the edge location with the lowest latency, CloudFront delivers it immediately.`,`cloudfront-expiration|A longer duration also reduces the load on your origin.`,`ga-what-is|The static IP addresses are anycast from the AWS edge network.`])]}],cues:[e(`connect two VPCs at the lowest cost`,`VPC peering (no charge to create)`,n(`There is no charge to create a VPC peering connection.`,`peering-what-is`,[`There is no charge to create a VPC peering connection.`])),e(`many VPCs and on-premises networks need simple routing through a hub`,`AWS Transit Gateway`,n(`Transit Gateway is a network transit hub, charged per attachment per hour and for traffic processed.`,`tgw-what-is`,[`You are charged hourly for each attachment on a transit gateway, and you are charged for the amount of traffic processed on the transit gateway.`])),e(`private subnets reach S3 and the NAT gateway charges are high`,`S3 gateway endpoint`,n(`There is no additional charge for using gateway endpoints.`,`vpce-gateway`,[`There is no additional charge for using gateway endpoints.`])),e(`reduce traffic and load on the origin for popular static content`,`Amazon CloudFront with a longer cache duration`,n(`A longer cache duration reduces the load on your origin.`,`cloudfront-expiration`,[`A longer duration also reduces the load on your origin.`])),e(`route users to the Region with the best latency`,`Route 53 latency routing`,n(`Latency routing sends traffic to the Region that provides the best latency.`,`route53-routing`,[`Latency routing policy – Use when you have resources in multiple AWS Regions and you want to route traffic to the Region that provides the best latency.`])),e(`root domain name pointing at a CloudFront distribution`,`Route 53 alias record`,n(`You can create an alias record at the zone apex, which a CNAME cannot do.`,`route53-alias`,[`Unlike a CNAME record, you can create an alias record at the top node of a DNS namespace, also known as the zone apex.`]))],examples:[],confuse:[],azure:[{concept:`Virtual network peering`,aws:`VPC peering`,mapping:n(`Learn says both Azure and AWS support virtual network or VPC peering. Azure virtual network peering connects virtual networks through the Azure backbone network, and once peered the networks appear as one for connectivity purposes.`,[`learn-networking`,`peering-what-is`],[`learn-networking|Both Azure and AWS support virtual network / VPC peering.`,`learn-networking|After they're peered, the two virtual networks appear as one for all connectivity purposes.`,`peering-what-is|The VPCs can be in different Regions (also known as an inter-Region VPC peering connection).`]),breaks:n(`On AWS, transitive peering relationships are not supported, and charges apply for data transfer over VPC peering connections that cross Availability Zones and Regions. Learn says that once peered, the Azure virtual networks appear as one for all connectivity purposes.`,[`peering-basics`,`peering-what-is`,`learn-networking`],[`peering-basics|You can create multiple VPC peering connections for each VPC that you own, but transitive peering relationships are not supported.`,`peering-what-is|Charges apply for data transfer over VPC peering connections that cross Availability Zones and Regions.`,`learn-networking|After they're peered, the two virtual networks appear as one for all connectivity purposes.`])},{concept:`Azure Virtual WAN`,aws:`AWS Transit Gateway`,mapping:n(`Learn says both technologies allow more complex peering via Azure Virtual WAN or AWS Transit Gateway.`,[`learn-networking`,`tgw-what-is`],[`learn-networking|Both technologies allow more complex peering via Azure Virtual WAN or AWS Transit Gateway.`,`tgw-what-is|AWS Transit Gateway is a network transit hub used to interconnect virtual private clouds (VPCs) and on-premises networks.`]),breaks:n(`On AWS, you are charged hourly for each attachment on a transit gateway and for the amount of traffic processed on it. Learn describes Azure Virtual WAN and AWS Transit Gateway as allowing more complex peering.`,[`tgw-what-is`,`learn-networking`],[`tgw-what-is|You are charged hourly for each attachment on a transit gateway, and you are charged for the amount of traffic processed on the transit gateway.`,`learn-networking|Both technologies allow more complex peering via Azure Virtual WAN or AWS Transit Gateway.`])},{concept:`Azure DNS`,aws:`Amazon Route 53`,mapping:n(`Learn says Route 53 provides both DNS name management and DNS-level traffic routing and failover, whereas in Azure separate services handle these tasks: Azure DNS for domain and DNS management and Traffic Manager for DNS-level traffic routing, load balancing and failover.`,[`learn-networking`,`route53-what-is`],[`learn-networking|In AWS, Route 53 provides both DNS name management and DNS-level traffic routing and failover services.`,`learn-networking|Azure DNS provides domain and DNS management.`,`learn-networking|Traffic Manager provides DNS-level traffic routing, load balancing, and failover capabilities.`]),breaks:n(`On AWS, one service covers both, and Route 53 offers routing policies such as failover routing. Learn pairs Route 53 with Azure DNS for domain and DNS management and with Traffic Manager for DNS-level traffic routing, load balancing and failover.`,[`route53-routing`,`learn-networking`],[`route53-routing|Failover routing policy – Use when you want to configure active-passive failover.`,`learn-networking|Azure DNS provides domain and DNS management.`,`learn-networking|Traffic Manager provides DNS-level traffic routing, load balancing, and failover capabilities.`])},{concept:`Azure Front Door`,aws:`Amazon CloudFront`,mapping:n(`Learn pairs CloudFront with Azure Front Door, a modern cloud content delivery network service that provides high performance, scalability and secure user experiences for content and applications.`,[`learn-networking`,`cloudfront-what-is`],[`learn-networking|Azure Front Door is a modern cloud content delivery network (CDN) service that provides high performance, scalability, and secure user experiences for your content and applications.`,`cloudfront-what-is|CloudFront delivers your content through a worldwide network of data centers called edge locations.`]),breaks:n(`On AWS, data transfer between CloudFront and your AWS origins is waived when serving traffic through CloudFront. Learn describes Azure Front Door as a content delivery network service providing high performance, scalability and secure user experiences.`,[`cloudfront-pricing`,`learn-networking`],[`cloudfront-pricing|Data transfer between CloudFront and your AWS origins is automatically waived when serving traffic through CloudFront, giving you a monthly price for both CloudFront delivery and your AWS origin’s data transfer costs to CloudFront.`,`learn-networking|Azure Front Door is a modern cloud content delivery network (CDN) service that provides high performance, scalability, and secure user experiences for your content and applications.`])},{concept:`Private Endpoint`,aws:`VPC endpoints (gateway and interface endpoints)`,mapping:n(`Learn pairs VPC endpoints with Azure Private Endpoint, which provides secured, private connectivity to various Azure platform as a service resources over a backbone Microsoft private network.`,[`learn-networking`,`vpce-interface`],[`learn-networking|Private Endpoint provides secured, private connectivity to various Azure platform as a service (PaaS) resources, over a backbone Microsoft private network.`,`vpce-interface|You are billed for hourly usage and data processing charges.`]),breaks:n(`AWS has gateway endpoints for S3 and DynamoDB, which have no additional charge, and interface endpoints, which are billed for hourly usage and data processing. Learn describes Azure Private Endpoint as secured, private connectivity to Azure platform as a service resources.`,[`vpce-gateway`,`vpce-interface`,`learn-networking`],[`vpce-gateway|Gateway VPC endpoints provide reliable connectivity to Amazon S3 and DynamoDB without requiring an internet gateway or a NAT device for your VPC.`,`vpce-gateway|There is no additional charge for using gateway endpoints.`,`vpce-interface|You are billed for hourly usage and data processing charges.`,`learn-networking|Private Endpoint provides secured, private connectivity to various Azure platform as a service (PaaS) resources, over a backbone Microsoft private network.`])}]},y={building:`service-selection-bureau`,overview:[n(`Database cost depends first on picking the right kind of database and then on how its capacity is billed. Express Quarter taught the data models and performance; this building asks which choice costs least for the same job. Serverless options bill for what the workload uses instead of for an always-on server, and AWS offers database options with diverse data models for a variety of workloads, so each workload can be matched to a database built for its data model.`,[`database-decision`,`aurora-serverless`,`dynamodb-ondemand`],[`database-decision|AWS serverless offerings include Amazon Aurora DSQL, Amazon Aurora Serverless, Amazon DynamoDB, Amazon ElastiCache, Amazon Keyspaces (for Apache Cassandra), Amazon Timestream for LiveAnalytics, and Amazon Neptune Serverless.`,`database-decision|AWS offers a growing number of database options (15+) with diverse data models to support a variety of workloads.`,`aurora-serverless|Thus, Aurora serverless can help you to stay within budget and avoid paying for computer resources that you don't use.`,`dynamodb-ondemand|With pay-per-request pricing, you don’t have to worry about idle capacity because you only pay for the throughput you actually use.`])],beyondProject:[n(`Your project uses DynamoDB. The SAA cost question is which capacity mode fits the traffic a table receives. In on-demand mode there is pay-per-request pricing, so you do not worry about idle capacity, and if you drive no traffic to the table you are not charged for any throughput; provisioned mode asks you to specify throughput capacity and lets auto scaling adjust it in response to traffic changes. When you choose on-demand mode, DynamoDB instantly accommodates your workloads as they ramp up or down to any previously reached traffic level. AWS says you can choose provisioned capacity if you have steady workloads with predictable growth, and if you can reliably forecast capacity requirements for your application (Tuning Bay covers the capacity units).`,[`dynamodb-ondemand`,`dynamodb-provisioned`,`dynamodb-capacity`],[`dynamodb-ondemand|With pay-per-request pricing, you don’t have to worry about idle capacity because you only pay for the throughput you actually use.`,`dynamodb-ondemand|If you are driving zero traffic to your table, then with on-demand, you are not charged for any throughput.`,`dynamodb-provisioned|When you create a new provisioned table in DynamoDB, you must specify its provisioned throughput capacity.`,`dynamodb-provisioned|You can use auto scaling to adjust your table’s provisioned capacity automatically in response to traffic changes.`,`dynamodb-ondemand|When you choose on-demand mode, DynamoDB instantly accommodates your workloads as they ramp up or down to any previously reached traffic level.`,`dynamodb-capacity|You can choose to use provisioned capacity if you have steady workloads with predictable growth, and if you can reliably forecast capacity requirements for your application.`],{newer:[`dynamodb-price-cut-2024`]})],bullets:[{id:`4.3-K9`,concepts:[n(`There are relational and non-relational OLTP databases, and a separate analytics need. AWS describes two high-level categories of OLTP databases, relational and non-relational, and offers Amazon Redshift when you need to store and analyse massive amounts of data quickly (an OLAP requirement). Using the category that fits the access pattern avoids paying for features, or for scale, that the workload does not use.`,`database-decision`,[`There are two high-level categories of AWS OLTP databases—relational and non-relational.`,`If you need to store and analyze massive amounts of data quickly and efficiently (a requirement that is typically met by an OLAP application), AWS offers Amazon Redshift.`],{allow:[`two`]}),n(`Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale, which AWS suggests for key-value workloads such as session stores or shopping carts. Amazon Aurora is the relational option for migrating or modernising an on-premises relational workload, or one with less predictable query patterns.`,[`dynamodb-what-is`,`database-decision`],[`dynamodb-what-is|Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale.`,`database-decision|Amazon DynamoDB Key-value Use for workloads such as session stores or shopping carts.`,`database-decision|Amazon Aurora Relational Use when you're migrating or modernizing an on-premises relational workload, or if your workload has less predictable query patterns.`])],services:[`Amazon DynamoDB`,`Amazon RDS`,`Amazon Aurora Serverless`],design:[n(`Cue: "simple key lookups at huge scale, unpredictable traffic, minimal operations" → DynamoDB on-demand; "relational schema, joins, an existing MySQL or PostgreSQL app" → Aurora or RDS; "analytical queries over very large data" → Redshift.`,[`database-decision`,`dynamodb-ondemand`],[`database-decision|Amazon DynamoDB Key-value Use for workloads such as session stores or shopping carts.`,`dynamodb-ondemand|With pay-per-request pricing, you don’t have to worry about idle capacity because you only pay for the throughput you actually use.`])]},{id:`4.3-S3`,concepts:[n(`DynamoDB and RDS bill differently. DynamoDB is serverless and its on-demand mode charges per request: with zero traffic to a table, you are not charged for any throughput. For steady RDS use, a reserved DB instance is a billing discount on certain on-demand DB instances for a one- or three-year term, and a No Upfront reserved DB instance bills a discounted hourly rate for every hour within its term, regardless of usage. As study guidance, the cost question is therefore how steady and how large the load is, not which product is cheaper in general.`,[`dynamodb-ondemand`,`rds-reserved`],[`dynamodb-ondemand|If you are driving zero traffic to your table, then with on-demand, you are not charged for any throughput.`,`dynamodb-ondemand|With pay-per-request pricing, you don’t have to worry about idle capacity because you only pay for the throughput you actually use.`,`rds-reserved|Reserved DB instances are not physical instances, but rather a billing discount applied to the use of certain on-demand DB instances in your account.`,`rds-reserved|Using reserved DB instances, you can reserve a DB instance for a one- or three-year term.`,`rds-reserved|Your No Upfront reserved DB instance bills a discounted hourly rate for every hour within the term, regardless of usage`]),n(`Aurora serverless is an on-demand, autoscaling configuration for Aurora. It automates monitoring the workload and adjusting capacity, which can help you stay within budget and avoid paying for compute resources you do not use. AWS lists development and test systems and environments with highly variable and unpredictable workloads among the cases where it is especially valuable. Capacity is measured in Aurora capacity units (ACUs) and goes up to 256 ACUs on current versions; the capacity range that is supported depends on the engine and platform version.`,[`aurora-serverless`,`aurora-serverless-how`],[`aurora-serverless|Aurora serverless is an on-demand, autoscaling configuration for Amazon Aurora.`,`aurora-serverless|Thus, Aurora serverless can help you to stay within budget and avoid paying for computer resources that you don't use.`,`aurora-serverless|This type of automation is especially valuable for multitenant databases, distributed databases, development and test systems, and other environments with highly variable and unpredictable workloads.`,`aurora-serverless-how|Aurora serverless offers capacity from 0 ACUs to 256 ACUs.`,`aurora-serverless-how|The following table shows the Aurora serverless capacity ranges and engine version support for Aurora MySQL and Aurora PostgreSQL.`]),n(`In recent Aurora MySQL and Aurora PostgreSQL versions, the writer and readers can scale all the way down to zero ACUs, called automatic pause and resume or auto-pause. It is a choice: you allow it by setting the minimum capacity to zero, and with a nonzero minimum the database never pauses.`,`aurora-serverless-how`,[`Scaling to Zero In recent Aurora MySQL and Aurora PostgreSQL versions, Aurora serverless writers and readers can scale all the way down to zero ACUs.`,`We refer to this capability as automatic pause and resume, or auto-pause.`,`You can choose whether to allow this behavior by specifying a zero or nonzero value for the minimum capacity.`],{newer:[`aurora-serverless-v2-scale-to-zero`],allow:[`zero`]}),n(`Older material may describe Aurora Serverless v1, which AWS now calls a deprecated product with a different architecture from the current Aurora serverless. Treat v1 behaviour as history, not as the answer to a new design question.`,`aurora-serverless-how`,[`Platform versions should not be confused with Aurora Serverless v1, which is a deprecated product with a different architecture.`],{status:`deprecated`}),n(`Serverless is not a synonym for cheapest. A steady workload that runs all day may cost less on a provisioned instance with a commitment, since a Database Savings Plan applies to provisioned and serverless usage, and reserved DB instances give a billing discount for the term. Check how steady the load is before choosing.`,[`savings-plans-types`,`rds-reserved`],[`savings-plans-types|These plans automatically apply to the latest provisioned instance generations regardless of engine, instance family, size, Availability Zone (AZ), or Region, and also apply to serverless usage.`,`rds-reserved|Reserved DB instances provide you with a significant discount compared to on-demand DB instance pricing.`],{newer:[`database-savings-plans`]})],services:[`Amazon DynamoDB`,`Amazon RDS`,`Amazon Aurora Serverless`],design:[n(`Cue: "intermittent or unpredictable database use, development and test" → Aurora Serverless or DynamoDB on-demand; "steady, always-on relational workload" → a provisioned instance with a reservation or Database Savings Plan; "key-value access, no servers to manage" → DynamoDB.`,[`aurora-serverless`,`dynamodb-ondemand`,`rds-reserved`],[`aurora-serverless|These range from development and testing environments, to websites and applications that have unpredictable workloads, to the most demanding, business-critical applications that require high scale and availability.`,`dynamodb-ondemand|With pay-per-request pricing, you don’t have to worry about idle capacity because you only pay for the throughput you actually use.`,`rds-reserved|Reserved DB instances provide you with a significant discount compared to on-demand DB instance pricing.`],{newer:[`database-savings-plans`]})]},{id:`4.3-S4`,concepts:[n(`Time series data is a purpose-built type. Amazon Timestream is for large amounts of time series data from sources such as IoT, application metrics and asset tracking. Timestream for LiveAnalytics keeps recent data in memory and moves historical data to a cost optimised storage tier based on user defined policies. AWS's page points to Amazon Timestream for InfluxDB for similar capabilities.`,[`database-decision`,`timestream-what-is`],[`database-decision|Amazon Timestream Time series Use when you have a large amount of time series data, potentially from a number of sources, such as Internet of Things (IoT) data, application metrics, and asset tracking.`,`timestream-what-is|Timestream for LiveAnalytics saves you time and cost in managing the lifecycle of time series data by keeping recent data in memory and moving historical data to a cost optimized storage tier based upon user defined policies.`,`timestream-what-is|For similar capabilities to Amazon Timestream for LiveAnalytics, consider Amazon Timestream for InfluxDB.`]),n(`AWS has closed new customer access to Timestream for LiveAnalytics. Existing customer workloads are not affected, and AWS recommends that new customers evaluate Amazon Timestream for InfluxDB as an alternative. Timestream does not appear on the exam guide's in-scope services list (which that page describes as non-exhaustive), so treat it as context only.`,[`timestream-availability`,`exam-in-scope`],[`timestream-availability|After careful consideration, we have made the decision to close new customer access to Amazon Timestream for LiveAnalytics, effective 6/20/25.`,`timestream-availability|This change will not impact customer workloads running with Amazon Timestream for LiveAnalytics.`,`timestream-availability|We recommend that new customers evaluate Amazon Timestream for InfluxDB as an alternative due to its similar functionality.`,`exam-in-scope|The following list contains AWS services and features that are in scope for the exam.`,`exam-in-scope|This list is non-exhaustive and is subject to change.`],{status:`closed`,allow:[`6/20/25`]}),n(`Columnar format is the analytics type. Amazon Redshift stores tabular data in columns, which AWS describes as an important factor in optimising analytic query performance because it drastically reduces overall disk I/O requirements and reduces the amount of data you need to load from disk. Use it for analytical queries over large data rather than for transactional lookups.`,`redshift-columnar`,[`Columnar storage for database tables is an important factor in optimizing analytic query performance, because it drastically reduces the overall disk I/O requirements.`,`It reduces the amount of data you need to load from disk.`])],services:[`Amazon Redshift`,`Amazon DynamoDB`],design:[n(`Cue: "metrics or IoT readings over time with older data kept cheaply" → a time series database; "analytical queries that scan a few columns of very large tables" → columnar (Redshift); "transactional records with joins" → relational. Putting each data shape in its matching engine is the cost-effective choice because you are not paying a general engine to do a specialised job.`,[`database-decision`,`redshift-columnar`,`timestream-what-is`],[`database-decision|Amazon Timestream Time series Use when you have a large amount of time series data, potentially from a number of sources, such as Internet of Things (IoT) data, application metrics, and asset tracking.`,`redshift-columnar|It reduces the amount of data you need to load from disk.`,`timestream-what-is|Timestream for LiveAnalytics saves you time and cost in managing the lifecycle of time series data by keeping recent data in memory and moving historical data to a cost optimized storage tier based upon user defined policies.`])]}],cues:[e(`pay only for the database throughput actually used; traffic is unpredictable`,`DynamoDB on-demand mode`,n(`On-demand mode has pay-per-request pricing with no idle capacity to worry about.`,`dynamodb-ondemand`,[`With pay-per-request pricing, you don’t have to worry about idle capacity because you only pay for the throughput you actually use.`])),e(`relational database for development/test or highly variable workloads, avoid paying for unused compute`,`Aurora serverless (current; Serverless v1 is deprecated)`,n(`Aurora serverless adjusts capacity to demand and can help avoid paying for compute you do not use.`,`aurora-serverless`,[`Thus, Aurora serverless can help you to stay within budget and avoid paying for computer resources that you don't use.`])),e(`steady relational workload, lower the on-demand cost`,`Reserved DB instance or Database Savings Plan`,n(`Reserved DB instances give a significant discount compared with on-demand DB instance pricing.`,`rds-reserved`,[`Reserved DB instances provide you with a significant discount compared to on-demand DB instance pricing.`])),e(`IoT or metrics time series with older data on cheaper storage`,`A time series database that tiers history (Amazon Timestream, outside the exam guide's in-scope list: context only)`,n(`Timestream moves historical data to a cost optimised storage tier based on policies.`,`timestream-what-is`,[`Timestream for LiveAnalytics saves you time and cost in managing the lifecycle of time series data by keeping recent data in memory and moving historical data to a cost optimized storage tier based upon user defined policies.`])),e(`analytical queries over very large tables, columnar storage`,`Amazon Redshift`,n(`Columnar storage reduces the data loaded from disk for analytic queries.`,`redshift-columnar`,[`It reduces the amount of data you need to load from disk.`])),e(`session store or shopping cart at massive scale`,`Amazon DynamoDB`,n(`AWS suggests DynamoDB for key-value workloads such as session stores or shopping carts.`,`database-decision`,[`Amazon DynamoDB Key-value Use for workloads such as session stores or shopping carts.`]))],examples:[],confuse:[],azure:[{concept:`Azure SQL Database serverless`,aws:`Amazon Aurora Serverless`,mapping:n(`Learn pairs Amazon Aurora Serverless with Azure SQL Database serverless (or SQL Database in Microsoft Fabric), and notes that SQL Database serverless can automatically scale compute and pause during inactivity. Current Aurora serverless can also scale all the way down to zero ACUs with automatic pause and resume in recent Aurora MySQL and Aurora PostgreSQL versions.`,[`learn-databases`,`aurora-serverless`,`aurora-serverless-how`],[`learn-databases|Serverless relational database Amazon Aurora Serverless Azure SQL Database serverless or SQL Database in Microsoft Fabric`,`learn-databases|SQL Database serverless can automatically scale compute and pause during inactivity.`,`aurora-serverless|Aurora serverless is an on-demand, autoscaling configuration for Amazon Aurora.`,`aurora-serverless-how|Scaling to Zero In recent Aurora MySQL and Aurora PostgreSQL versions, Aurora serverless writers and readers can scale all the way down to zero ACUs.`],{newer:[`aurora-serverless-v2-scale-to-zero`],allow:[`zero`]}),breaks:n(`Learn says these services use different scaling and billing models. On Aurora Serverless, capacity is adjusted automatically based on application demand. The smallest Aurora serverless capacity that you can define is 0 ACUs, for Aurora serverless versions that support the auto-pause feature, and whether the database can pause is controlled by the minimum capacity you set.`,[`learn-databases`,`aurora-serverless`,`aurora-serverless-how`],[`learn-databases|These services use different scaling and billing models.`,`aurora-serverless|Capacity is adjusted automatically based on application demand.`,`aurora-serverless|Aurora serverless is an on-demand, autoscaling configuration for Amazon Aurora.`,`aurora-serverless-how|The smallest Aurora serverless capacity that you can define is 0 ACUs, for Aurora serverless versions that support the auto-pause feature.`,`aurora-serverless-how|You can choose whether to allow this behavior by specifying a zero or nonzero value for the minimum capacity.`],{newer:[`aurora-serverless-v2-scale-to-zero`]})},{concept:`Azure Cosmos DB for NoSQL`,aws:`Amazon DynamoDB`,mapping:n(`Learn pairs Amazon DynamoDB with Azure Cosmos DB for NoSQL as a key-value and document database: both distribute data by partition key and provide change streams.`,[`learn-databases`,`dynamodb-what-is`],[`learn-databases|Key-value and document database Amazon DynamoDB Azure Cosmos DB for NoSQL Both services distribute data by partition key and provide change streams.`,`dynamodb-what-is|Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale.`]),breaks:n(`Learn notes that Azure Cosmos DB supports multiple APIs and data models. On AWS, DynamoDB lets you choose between on-demand mode and provisioned mode for your tables.`,[`learn-databases`,`dynamodb-capacity`],[`learn-databases|Azure Cosmos DB supports multiple APIs and data models.`,`dynamodb-capacity|In Amazon DynamoDB, you can choose between on-demand mode and provisioned mode for your tables to accommodate different workload requirements.`])}]},b={building:`storage-market`,overview:[n(`The cost-effective storage service is the one that matches how the data is used, not the one with the cheapest label. Each service has a lower-cost option for data that is read rarely: S3 has Intelligent-Tiering and infrequent-access classes, EFS has Infrequent Access and Archive classes, and FSx has its own Intelligent-Tiering class. The task is to match the access pattern to the service first and then to its cheaper tier.`,[`storage-decision`,`efs-lifecycle`],[`storage-decision|For example, use Amazon S3 Intelligent-Tiering for object data, or the FSx Intelligent-Tiering storage class for Amazon FSx for OpenZFS and Amazon FSx for Lustre workloads.`,`efs-lifecycle|Use lifecycle management to automatically transition data between storage classes according to the lifecycle configuration for the file system.`],{newer:[`efs-archive-class`]})],beyondProject:[n(`Your static site is a good S3 use case, because object storage suits read-heavy workloads such as websites. The SAA question is the comparison: S3 for objects accessed by API, EFS for file data shared by many instances, EBS for a disk attached to one instance, and FSx when a specific file system is required.`,`storage-decision`,[`Object storage provides easy access to data through an application programming interface (API) over the internet and is well-suited to read-heavy workloads (such as streaming applications and services).`])],bullets:[{id:`4.1-K4`,concepts:[n(`Amazon S3 is object storage for any amount of data: data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices and big data analytics.`,`s3-what-is`,[`Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`]),n(`Amazon EFS is serverless, elastic file storage over NFS that you share without provisioning capacity; Amazon EBS is block storage attached to EC2 instances; and the Amazon FSx family offers managed Windows File Server, Lustre, NetApp ONTAP and OpenZFS file systems. The side-by-side comparison is in the Don't confuse section below.`,[`efs-what-is`,`ebs-what-is`,`storage-decision`],[`efs-what-is|Amazon Elastic File System (Amazon EFS) provides serverless, fully elastic file storage so that you can share file data without provisioning or managing storage capacity and performance.`,`ebs-what-is|Amazon Elastic Block Store (Amazon EBS) provides scalable, high-performance block storage resources that can be used with Amazon Elastic Compute Cloud (Amazon EC2) instances.`,`storage-decision|Amazon FSx for NetApp ONTAP supports both NFS and SMB protocols, including concurrent multi-protocol access to the same data.`]),n(`FSx for Windows File Server provides fully managed Windows file servers on a native Windows file system for lift-and-shift of enterprise Windows applications; FSx for Lustre is for workloads where speed matters, such as machine learning, HPC, video processing and financial modeling; FSx for OpenZFS moves data from on-premises ZFS or other Linux-based file servers without changing application code.`,[`fsx-windows`,`fsx-lustre`,`fsx-openzfs`],[`fsx-windows|FSx for Windows File Server has the features, performance, and compatibility to easily lift and shift enterprise applications to the AWS Cloud.`,`fsx-lustre|You use Lustre for workloads where speed matters, such as machine learning, high performance computing (HPC), video processing, and financial modeling.`,`fsx-openzfs|You can do this without changing your application code or how you manage data.`])],services:[`Amazon S3`,`Amazon EFS`,`Amazon EBS`,`Amazon FSx`],design:[n(`Cue: Windows file shares → FSx for Windows File Server; HPC scratch with fast S3-linked storage → FSx for Lustre; NetApp ONTAP features or multi-protocol access → FSx for ONTAP; shared Linux files → EFS; attached disk → EBS; website, backups, data lake → S3.`,[`fsx-windows`,`storage-decision`,`fsx-lustre`,`efs-what-is`,`ebs-what-is`,`s3-what-is`],[`fsx-lustre|When linked to an Amazon S3 bucket, an FSx for Lustre file system transparently presents S3 objects as files.`,`efs-what-is|Amazon Elastic File System (Amazon EFS) provides serverless, fully elastic file storage so that you can share file data without provisioning or managing storage capacity and performance.`,`ebs-what-is|Amazon Elastic Block Store (Amazon EBS) provides scalable, high-performance block storage resources that can be used with Amazon Elastic Compute Cloud (Amazon EC2) instances.`,`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`,`fsx-windows|Amazon FSx for Windows File Server provides fully managed Microsoft Windows file servers, backed by a fully native Windows file system.`,`storage-decision|Amazon FSx for NetApp ONTAP supports both NFS and SMB protocols, including concurrent multi-protocol access to the same data.`])]},{id:`4.1-K9`,concepts:[n(`Choosing storage means matching your access patterns: AWS notes that aligning storage with your access patterns will be critical to achieving the performance, cost, efficiency, security and resiliency you want.`,`storage-decision`,[`ensuring that it aligns with your access patterns will be critical to achieving the performance, cost, efficiency, security, and resiliency you want.`]),n(`Frequent access suits the standard class of each service; infrequent or cold access suits a cheaper tier. For file data that is rarely read, EFS Archive provides lower-cost storage for data you access only a few times a year, and EFS lifecycle management moves files based on when they were last accessed (the default policy transitions data to Archive after 90 days without access).`,[`storage-decision`,`efs-lifecycle`],[`storage-decision|For cold, rarely accessed file data, use the Amazon EFS Archive storage class.`,`storage-decision|This class provides lower-cost storage for data that you access only a few times a year.`,`storage-decision|You enable it through Amazon EFS Lifecycle Management, whose default policy transitions data to Archive after 90 days without access.`,`efs-lifecycle|Transition time is based on when the files were last accessed in the Standard storage class.`],{newer:[`efs-archive-class`]}),n(`EFS lifecycle management moves files through cheaper classes. By default, files that are not accessed in the Standard storage class are moved to Infrequent Access (IA), which is cost-optimized for data accessed only a few times each quarter, and later to Archive, which is cost-optimized for data accessed only a few times each year or less. By default files are not moved back to Standard when they are accessed in IA or Archive.`,`efs-lifecycle`,[`By default, files that are not accessed in Standard storage`,`By default, files that are not accessed in the Standard storage class for 90 days are transitioned in to the Archive storage class.`,`Transition into IA – Instructs lifecycle management when to move files in to the Infrequent Access (IA) storage class, which is cost-optimized for data that is accessed only a few times each quarter.`,`Transition into Archive – Instructs lifecycle management when to move files from the Standard or IA storage class in to the Archive storage class, which is cost-optimized for data that is accessed only a few times each year or less.`,`By default, files are not moved back to the Standard storage class, and they remain in the IA or Archive storage class when they are accessed.`]),n(`More EFS cost details. EFS offers Regional and One Zone file system types: One Zone file systems store data within a single Availability Zone, so data can be lost if all or part of that zone is lost. Throughput mode is billed separately from storage: with Elastic throughput you pay only for the amount of metadata and data read or written, and with Provisioned throughput you are charged for the throughput enabled for the file system.`,[`efs-features`,`efs-performance`],[`efs-features|Amazon EFS offers Regional and One Zone file system types.`,`efs-features|One Zone – One Zone file systems store data within a single Availability Zone.`,`efs-features|In the unlikely case of the loss or damage to all or part of an AWS Availability Zone, data in a One Zone storage class may be lost.`,`efs-performance|You pay only for the amount of metadata and data read or written, and you don't accrue or consume burst credits while using Elastic throughput.`,`efs-performance|For file systems using Provisioned throughput, you are charged for the amount of throughput enabled for the file system.`],{newer:[`efs-elastic-throughput`]}),n(`When the access pattern changes unpredictably, use the automatic tiering options: S3 Intelligent-Tiering for object data, and the FSx Intelligent-Tiering storage class for FSx for OpenZFS and FSx for Lustre, which tiers data across Frequent Access, Infrequent Access and Archive tiers to reduce storage costs for data with changing access patterns.`,`storage-decision`,[`For example, use Amazon S3 Intelligent-Tiering for object data, or the FSx Intelligent-Tiering storage class for Amazon FSx for OpenZFS and Amazon FSx for Lustre workloads.`,`The FSx Intelligent-Tiering storage class automatically tiers data across Frequent Access, Infrequent Access, and Archive tiers to reduce storage costs for data with changing access patterns.`],{newer:[`efs-archive-class`,`fsx-openzfs-intelligent-tiering`]}),n(`Read-heavy object access (streaming, websites) fits S3; fast, consistent low-latency I/O direct-attached to an instance fits block storage; shared read-write access from many instances fits file storage.`,`storage-decision`,[`Object storage provides easy access to data through an application programming interface (API) over the internet and is well-suited to read-heavy workloads (such as streaming applications and services).`,`Block storage offers high-performance storage that is direct-attached to a compute instance with low-latency access, making it suitable for applications that require fast and consistent I/O operations.`])],services:[`Amazon S3`,`Amazon EFS`,`Amazon FSx`],design:[n(`Cue: "access pattern is unknown or changes" → Intelligent-Tiering; "files not touched for months" → EFS lifecycle to IA or Archive; the S3 class details are in Cold Cellar.`,`storage-decision`,[`For example, use Amazon S3 Intelligent-Tiering for object data, or the FSx Intelligent-Tiering storage class for Amazon FSx for OpenZFS and Amazon FSx for Lustre workloads.`])]},{id:`4.1-K11`,concepts:[n(`Object, file and block characteristics: object is API-accessed unstructured data and suits read-heavy workloads; file is a hierarchy of files and folders mountable over NFS or SMB; block is high-performance storage direct-attached to a compute instance. (Cargo Hall has the definitions.)`,`storage-decision`,[`Object — Object storage is a technology that stores and manages data in an unstructured format called objects.`,`File system — File systems store data in a hierarchical structure of files and folders.`,`Block storage offers high-performance storage that is direct-attached to a compute instance with low-latency access, making it suitable for applications that require fast and consistent I/O operations.`])],services:[`Amazon S3`,`Amazon EFS`,`Amazon EBS`],design:[n(`The type affects how you provision: EFS is fully elastic, so you do not provision capacity or performance (Block Warehouse covers how block volumes are provisioned).`,`efs-what-is`,[`Amazon Elastic File System (Amazon EFS) provides serverless, fully elastic file storage so that you can share file data without provisioning or managing storage capacity and performance.`])]},{id:`4.1-S10`,concepts:[n(`To select a cost-effective storage solution, match the storage class to the access pattern. The storage decision guide gives S3 Intelligent-Tiering for object data and the EFS Archive class for cold file data as examples of matching classes to access patterns. As study guidance, settle the access method (API, shared file system, attached disk) and any named file system first, because the cheaper tier only applies within the service that fits.`,[`storage-decision`,`efs-lifecycle`],[`storage-decision|For example, use Amazon S3 Intelligent-Tiering for object data, or the FSx Intelligent-Tiering storage class for Amazon FSx for OpenZFS and Amazon FSx for Lustre workloads.`,`storage-decision|This class provides lower-cost storage for data that you access only a few times a year.`,`efs-lifecycle|Lifecycle policies instruct lifecycle management when to transition files into and out of the EFS Infrequent Access (IA) and EFS Archive storage classes.`],{newer:[`efs-archive-class`]}),n(`Right-size block storage by choosing the lowest-cost type that meets the performance need (Block Warehouse), and use S3 File Gateway to give on-premises systems a cost-effective alternative to on-premises storage with the data in S3.`,[`ebs-volume-types`,`sgw-file-s3`],[`ebs-volume-types|Scenarios where the lowest storage cost is important`,`sgw-file-s3|A S3 File Gateway simplifies file storage in Amazon S3, integrates to existing applications through industry-standard file system protocols, and provides a cost-effective alternative to on-premises storage.`])],services:[`Amazon S3`,`Amazon EFS`,`Amazon EBS`,`Amazon FSx`],design:[n(`Scenario pattern: "shared files rarely touched" → EFS Archive; "the same objects read repeatedly by users around the world" → CloudFront caching in edge locations (S3 classes are in Cold Cellar, block volume types in Block Warehouse).`,[`storage-decision`,`cloudfront-what-is`],[`storage-decision|This class provides lower-cost storage for data that you access only a few times a year.`,`cloudfront-what-is|You also get increased reliability and availability because copies of your files (also known as objects) are now held (or cached) in multiple edge locations around the world.`],{newer:[`efs-archive-class`]})]}],cues:[e(`shared file data, grows automatically, rarely used files should cost less`,`Amazon EFS with lifecycle management (IA and Archive classes)`,n(`EFS lifecycle management moves files to IA and Archive based on last access.`,`efs-lifecycle`,[`Transition time is based on when the files were last accessed in the Standard storage class.`])),e(`object data with unknown or changing access patterns`,`S3 Intelligent-Tiering`,n(`AWS recommends S3 Intelligent-Tiering for object data with changing access patterns.`,`storage-decision`,[`For example, use Amazon S3 Intelligent-Tiering for object data, or the FSx Intelligent-Tiering storage class for Amazon FSx for OpenZFS and Amazon FSx for Lustre workloads.`])),e(`Windows applications need SMB file shares`,`Amazon FSx for Windows File Server`,n(`FSx for Windows File Server provides fully managed Windows file servers.`,`fsx-windows`,[`Amazon FSx for Windows File Server provides fully managed Microsoft Windows file servers, backed by a fully native Windows file system.`])),e(`high-performance computing or machine learning training needing fast file system`,`Amazon FSx for Lustre`,n(`Lustre is for workloads where speed matters.`,`fsx-lustre`,[`You use Lustre for workloads where speed matters, such as machine learning, high performance computing (HPC), video processing, and financial modeling.`])),e(`migrate on-premises NetApp or ZFS file servers without changing applications`,`FSx for NetApp ONTAP / FSx for OpenZFS`,n(`ONTAP supports NFS and SMB and OpenZFS moves data from on-premises ZFS servers without changing application code.`,[`fsx-openzfs`,`storage-decision`],[`You can do this without changing your application code or how you manage data.`,`storage-decision|Amazon FSx for NetApp ONTAP supports both NFS and SMB protocols, including concurrent multi-protocol access to the same data.`,`storage-decision|move data to AWS from on-premises ZFS or other Linux-based file servers`])),e(`block storage for one EC2 instance`,`Amazon EBS`,n(`EBS volumes attach to EC2 instances and are used like local drives.`,`ebs-what-is`,[`Amazon EBS volumes — These are storage volumes that you attach to Amazon EC2 instances.`]))],examples:[],confuse:[`ebs-efs-fsx`],azure:[{concept:`Blob storage`,aws:`Amazon S3`,mapping:n(`Learn pairs Amazon S3 with Azure Blob Storage as object storage, and its cool tier (cheaper than the hot tier for infrequently accessed data that must be available immediately) with S3 Standard-Infrequent Access.`,[`learn-storage`,`s3-what-is`],[`learn-storage|Blob Storage is object storage, so it serves the same purpose as AWS S3.`,`learn-storage|For data that's infrequently accessed but must be available immediately when accessed, the cool tier provides cheaper storage than the hot tier`,`learn-storage|This tier is comparable to S3 Standard-Infrequent Access.`,`s3-what-is|Amazon S3 is an object storage service that stores data as objects, hierarchical data, or tabular data within buckets.`]),breaks:n(`Learn pairs the Azure cool tier with S3 Standard-Infrequent Access. On AWS, S3 also offers Intelligent-Tiering, which AWS gives as an example for object data (Cold Cellar).`,[`storage-decision`,`learn-storage`],[`storage-decision|For example, use Amazon S3 Intelligent-Tiering for object data, or the FSx Intelligent-Tiering storage class for Amazon FSx for OpenZFS and Amazon FSx for Lustre workloads.`,`learn-storage|This tier is comparable to S3 Standard-Infrequent Access.`])},{concept:`Azure Files`,aws:`Amazon EFS and Amazon FSx`,mapping:n(`Learn lists Azure Files for shared file storage and names AWS EFS and the FSx family of managed file systems as the shared storage services on AWS.`,[`learn-storage`,`efs-what-is`],[`learn-storage|Various shared storage services that AWS provides, like Amazon Elastic File System (EFS) and the Amazon FSx family of managed file systems.`,`efs-what-is|Amazon EFS supports the Network File System version 4 (NFSv4.1 and NFSv4.0) protocol, so the applications and tools that you use today work seamlessly with Amazon EFS.`]),breaks:n(`On AWS the shared file services split by protocol and engine: EFS for NFS, and the FSx family, which comes in four options (Windows, Lustre, OpenZFS and ONTAP) that align to widely used file systems and protocols. Learn pairs FSx for Lustre with Azure Managed Lustre and FSx for NetApp ONTAP with Azure NetApp Files, while FSx for Windows File Server and EFS are listed against Azure Files.`,[`efs-what-is`,`fsx-windows`,`storage-decision`,`fsx-lustre`,`fsx-ontap`,`learn-storage`],[`efs-what-is|Amazon EFS supports the Network File System version 4 (NFSv4.1 and NFSv4.0) protocol, so the applications and tools that you use today work seamlessly with Amazon EFS.`,`fsx-windows|Amazon FSx for Windows File Server provides fully managed Microsoft Windows file servers, backed by a fully native Windows file system.`,`fsx-lustre|As a fully managed service, Amazon FSx makes it easier for you to use Lustre for workloads where storage speed matters.`,`fsx-ontap|Amazon FSx for NetApp ONTAP is a fully managed service that provides highly reliable, scalable, high-performing, and feature-rich file storage built on NetApp's popular ONTAP file system.`,`learn-storage|Various shared storage services that AWS provides, like Amazon Elastic File System (EFS) and the Amazon FSx family of managed file systems.`,`learn-storage|Elastic File System (EFS) Azure Files Provides a basic interface for creating and configuring file systems quickly and sharing common files.`,`learn-storage|Amazon FSx for Windows File Server Azure Files Provides a managed SMB file share that can work with Active Directory for access control.`,`storage-decision|Amazon FSx for NetApp ONTAP supports both NFS and SMB protocols, including concurrent multi-protocol access to the same data.`,`storage-decision|services in the Amazon FSx data storage family come in four options that align to widely used file systems and protocols`,`storage-decision|Amazon FSx for OpenZFS a fully managed file storage service that enables you to move data to AWS from on-premises ZFS or other Linux-based file servers.`,`fsx-lustre|You use Lustre for workloads where speed matters, such as machine learning, high performance computing (HPC), video processing, and financial modeling.`,`learn-storage|Amazon FSx for Lustre Azure Managed Lustre Provides a managed Lustre file system that integrates with object storage.`,`learn-storage|Amazon FSx for NetApp ONTAP Azure NetApp Files Provides managed NetApp capabilities in the cloud.`])},{concept:`Azure NetApp Files`,aws:`Amazon FSx for NetApp ONTAP`,mapping:n(`Learn pairs Amazon FSx for NetApp ONTAP with Azure NetApp Files, which provides managed NetApp capabilities in the cloud; on AWS, Amazon FSx for NetApp ONTAP is a fully managed service built on the NetApp ONTAP file system.`,[`learn-storage`,`fsx-ontap`],[`learn-storage|Amazon FSx for NetApp ONTAP Azure NetApp Files Provides managed NetApp capabilities in the cloud.`,`fsx-ontap|Amazon FSx for NetApp ONTAP is a fully managed service that provides highly reliable, scalable, high-performing, and feature-rich file storage built on NetApp's popular ONTAP file system.`]),breaks:n(`Learn also pairs FSx for NetApp ONTAP with Azure Elastic SAN for iSCSI or NVMe/TCP LUNs. On AWS, FSx for NetApp ONTAP supports both NFS and SMB protocols, including concurrent multi-protocol access to the same data.`,[`storage-decision`,`learn-storage`],[`storage-decision|Amazon FSx for NetApp ONTAP supports both NFS and SMB protocols, including concurrent multi-protocol access to the same data.`,`learn-storage|Amazon FSX for NetApp ONTAP iSCSI or NVMe/TCP LUNs Azure Elastic SAN Storage area network (SAN) capabilities in the cloud.`])}]},x={building:`throttle-lb-gate`,overview:[n(`Some network-edge choices change cost. An Application Load Balancer is charged for each hour or partial hour that it is running, so the number and type of load balancers matters; and API throttles are applied on a best-effort basis, as targets rather than guaranteed ceilings. Elastic Load Balancing distributes traffic across targets in one or more Availability Zones, and API Gateway lets you configure throttling and quotas to help protect your APIs from being overwhelmed by too many requests.`,[`elb-what-is`,`elb-pricing`,`apigw-throttling`],[`elb-what-is|Elastic Load Balancing automatically distributes your incoming traffic across multiple targets, such as EC2 instances, containers, and IP addresses, in one or more Availability Zones.`,`elb-pricing|You are charged for each hour or partial hour that an Application Load Balancer is running.`,`apigw-throttling|You can configure throttling and quotas for your APIs to help protect them from being overwhelmed by too many requests.`,`apigw-throttling|Both throttles and quotas are applied on a best-effort basis and should be thought of as targets rather than guaranteed request ceilings.`])],beyondProject:[n(`Your project uses API Gateway. The SAA cost points are the choice of API type and where throttling is applied. REST APIs support more features than HTTP APIs, while HTTP APIs are designed with minimal features so that they can be offered at a lower price; caching is a REST API feature and not an HTTP API feature in the comparison table. Caching reduces the number of calls made to your endpoint.`,[`apigw-http-vs-rest`,`apigw-caching`],[`apigw-http-vs-rest|REST APIs support more features than HTTP APIs, while HTTP APIs are designed with minimal features so that they can be offered at a lower price.`,`apigw-http-vs-rest|Caching Yes No`,`apigw-caching|With caching, you can reduce the number of calls made to your endpoint and also improve the latency of requests to your API.`])],bullets:[{id:`4.4-K3`,concepts:[n(`A load balancer distributes workloads across multiple compute resources, monitors the health of its registered targets and routes traffic only to the healthy ones. Elastic Load Balancing scales the load balancer capacity automatically in response to changes in incoming traffic, so you do not size it yourself.`,`elb-what-is`,[`A load balancer distributes workloads across multiple compute resources, such as virtual servers.`,`It monitors the health of its registered targets, and routes traffic only to the healthy targets.`,`Elastic Load Balancing scales your load balancer capacity automatically in response to changes in incoming traffic.`]),n(`Load balancers are charged by time and by use. For an Application Load Balancer you are charged for each hour or partial hour that it is running, and each partial hour is billed as a full hour, and also for the Load Balancer Capacity Units (LCU) used per minute. The Network Load Balancer and Gateway Load Balancer are billed the same way with their own capacity units. An idle load balancer is still running and so still accrues the hourly charge; Trusted Advisor has a check named Idle Load Balancers.`,[`elb-pricing`,`trusted-advisor-cost-checks`],[`elb-pricing|You are charged for each hour or partial hour that an Application Load Balancer is running.`,`elb-pricing|Each partial Application Load Balancer hour used is billed as a full hour.`,`elb-pricing|You are also charged for the number of Load Balancer Capacity Units (LCU) used per minute.`,`elb-pricing|You are charged for each hour or partial hour that a Network Load Balancer is running.`,`elb-pricing|You are charged for each hour or partial hour that a Gateway Load Balancer is running.`,`elb-pricing|You are also charged for the number of Network Load Balancer Capacity Units (NLCU) used by Network Load Balancer per minute.`,`elb-pricing|You are also charged for the number of Gateway Load Balancer Capacity Units (GLCU) used by Gateway Load Balancer per minute.`,`trusted-advisor-cost-checks|Idle Load Balancers`]),n(`Cross-zone load balancing is a cost detail. With cross-zone load balancing enabled, each load balancer node distributes traffic across the registered targets in all enabled Availability Zones. With Application Load Balancers it is always enabled at the load balancer level, and AWS says you are not charged for that regional data transfer. With Network Load Balancers and Gateway Load Balancers it is disabled by default, and for a Network Load Balancer you are charged for regional data transfer between Availability Zones when you enable it.`,[`elb-how-it-works`,`elb-faqs`],[`elb-how-it-works|When cross-zone load balancing is enabled, each load balancer node distributes traffic across the registered targets in all enabled Availability Zones.`,`elb-how-it-works|With Application Load Balancers, cross-zone load balancing is always enabled at the load balancer level.`,`elb-how-it-works|With Network Load Balancers and Gateway Load Balancers, cross-zone load balancing is disabled by default.`,`elb-faqs|Since cross-zone load balancing is always on with Application Load Balancer, you are not charged for this type of regional data transfer.`,`elb-faqs|Yes, you will be charged for regional data transfer between Availability Zones with Network Load Balancer when cross-zone load balancing is enabled.`]),n(`You can configure listener rules to route requests to different target groups based on the content of the application traffic, so one Application Load Balancer can serve several services.`,`alb-intro`,[`You can configure listener rules to route requests to different target groups based on the content of the application traffic.`])],services:[`Elastic Load Balancing (ELB)`],design:[n(`Cue: "many small web services, reduce load balancer cost" → one Application Load Balancer with listener rules to several target groups; "load balancer with no traffic" → remove it (Trusted Advisor idle check); choose the type for the traffic first (Elastic Mint and Express Interchange), then consolidate.`,[`alb-intro`,`elb-pricing`,`trusted-advisor-cost-checks`],[`alb-intro|You can configure listener rules to route requests to different target groups based on the content of the application traffic.`,`elb-pricing|You are charged for each hour or partial hour that an Application Load Balancer is running.`,`trusted-advisor-cost-checks|Idle Load Balancers`])]},{id:`4.4-S6`,concepts:[n(`API Gateway throttles requests using the token bucket algorithm, where a token counts for a request. It examines the rate and a burst of request submissions against all APIs in your account, per Region, and when submissions exceed the steady-state rate and burst limits it begins to throttle requests. Throttles and quotas are targets applied on a best-effort basis, not guaranteed ceilings.`,`apigw-throttling`,[`API Gateway throttles requests to your API using the token bucket algorithm, where a token counts for a request.`,`Specifically, API Gateway examines the rate and a burst of request submissions against all APIs in your account, per Region.`,`When request submissions exceed the steady-state request rate and burst limits, API Gateway begins to throttle requests.`,`Both throttles and quotas are applied on a best-effort basis and should be thought of as targets rather than guaranteed request ceilings.`]),n(`Per-client limits are a REST API feature. In the API Gateway comparison table, API keys, per-client rate limiting and per-client usage throttling are Yes for REST APIs and No for HTTP APIs, and caching is also REST only. If a question needs per-customer limits or caching, an HTTP API is not enough, even though HTTP APIs are designed with minimal features so that they can be offered at a lower price.`,`apigw-http-vs-rest`,[`Features REST API HTTP API Custom domains Yes Yes API keys Yes No Per-client rate limiting Yes No Per-client usage throttling Yes No Developer portal Yes No`,`Choose REST APIs if you need API management capabilities such as API keys and per-client rate limiting.`,`REST APIs support more features than HTTP APIs, while HTTP APIs are designed with minimal features so that they can be offered at a lower price.`,`Caching Yes No`]),n(`To limit individual clients, use a usage plan. A usage plan specifies who can access one or more deployed API stages and methods, and optionally sets the target request rate to start throttling requests. That protects the backend from one heavy client and ties access to the customers you intend to serve.`,`apigw-usage-plans`,[`A usage plan specifies who can access one or more deployed API stages and methods—and optionally sets the target request rate to start throttling requests.`,`You can configure usage plans and API keys to allow customers to access selected APIs, and begin throttling requests to those APIs based on defined limits and quotas.`]),n(`Cheaper options sit beside throttling. Caching responses reduces the number of calls made to your endpoint. In Lambda, reserved concurrency sets both the maximum and minimum number of concurrent instances allocated to an Lambda function, which caps how far that function can scale, and there is no charge for configuring it; provisioned concurrency incurs additional charges.`,[`apigw-caching`,`lambda-reserved`,`lambda-concurrency`],[`apigw-caching|With caching, you can reduce the number of calls made to your endpoint and also improve the latency of requests to your API.`,`lambda-reserved|Reserved concurrency – This sets both the maximum and minimum number of concurrent instances allocated to your Event Function.`,`lambda-concurrency|There is no charge for configuring reserved concurrency for an Event Function.`,`lambda-concurrency|Configuring provisioned concurrency incurs charges to your AWS account.`])],services:[`Amazon API Gateway`,`AWS Lambda`],design:[n(`Cue: "protect the backend from a traffic spike" → API Gateway throttling; "limit each customer to a request rate" → usage plan; "cap how far a Lambda function scales" → reserved concurrency; "repeated identical requests" → API caching. Clients that exceed the limit receive 429 Too Many Requests responses, so the client side needs retry with backoff.`,[`apigw-throttling`,`apigw-usage-plans`,`lambda-reserved`],[`apigw-throttling|When request submissions exceed the steady-state request rate and burst limits, API Gateway begins to throttle requests.`,`apigw-usage-plans|You can configure usage plans and API keys to allow customers to access selected APIs, and begin throttling requests to those APIs based on defined limits and quotas.`,`lambda-reserved|Reserved concurrency – This sets both the maximum and minimum number of concurrent instances allocated to your Event Function.`,`apigw-throttling|Clients may receive 429 Too Many Requests error responses at this point.`])]}],cues:[e(`many web services on one ALB to avoid paying for several load balancers`,`Application Load Balancer listener rules and target groups`,n(`An ALB routes to different target groups based on the content of the traffic.`,`alb-intro`,[`You can configure listener rules to route requests to different target groups based on the content of the application traffic.`])),e(`load balancer with no traffic still costs money`,`Remove it (Trusted Advisor: Idle Load Balancers)`,n(`A load balancer is charged for each hour or partial hour that it is running.`,`elb-pricing`,[`You are charged for each hour or partial hour that an Application Load Balancer is running.`])),e(`protect the backend from too many API requests`,`API Gateway throttling`,n(`API Gateway throttling and quotas help protect APIs from being overwhelmed.`,`apigw-throttling`,[`You can configure throttling and quotas for your APIs to help protect them from being overwhelmed by too many requests.`])),e(`limit each API customer to an agreed request rate`,`API Gateway usage plan with API keys`,n(`A usage plan optionally sets the target request rate to start throttling requests.`,`apigw-usage-plans`,[`A usage plan specifies who can access one or more deployed API stages and methods—and optionally sets the target request rate to start throttling requests.`])),e(`API needs the lowest price and few features`,`HTTP API`,n(`HTTP APIs are designed with minimal features so that they can be offered at a lower price.`,`apigw-http-vs-rest`,[`REST APIs support more features than HTTP APIs, while HTTP APIs are designed with minimal features so that they can be offered at a lower price.`])),e(`stop one Lambda function consuming all concurrency`,`Reserved concurrency`,n(`Reserved concurrency sets the maximum and minimum number of concurrent instances for an Lambda function.`,`lambda-reserved`,[`Reserved concurrency – This sets both the maximum and minimum number of concurrent instances allocated to your Event Function.`]))],examples:[],confuse:[],azure:[{concept:`Application Gateway`,aws:`Application Load Balancer`,mapping:n(`Learn says Azure Application Gateway provides application-level rule-based routing comparable to that of the AWS Application Load Balancer.`,[`learn-networking`,`alb-intro`],[`learn-networking|Application Gateway provides application-level rule-based routing comparable to that of the AWS Application Load Balancer.`,`alb-intro|You can configure listener rules to route requests to different target groups based on the content of the application traffic.`]),breaks:n(`On AWS, an Application Load Balancer is billed for each hour or partial hour it runs plus the Load Balancer Capacity Units it uses, and it can route requests to different target groups based on the content of the application traffic. Learn describes Application Gateway as comparable application-level rule-based routing.`,[`elb-pricing`,`learn-networking`,`alb-intro`],[`elb-pricing|You are charged for each hour or partial hour that an Application Load Balancer is running.`,`elb-pricing|You are also charged for the number of Load Balancer Capacity Units (LCU) used per minute.`,`learn-networking|Application Gateway provides application-level rule-based routing comparable to that of the AWS Application Load Balancer.`,`alb-intro|You can configure listener rules to route requests to different target groups based on the content of the application traffic.`])},{concept:`Azure API Management`,aws:`Amazon API Gateway`,mapping:n(`The Learn hub pairs Amazon API Gateway with Azure API Management as turnkey services for publishing APIs to internal and external customers.`,[`learn-hub`,`apigw-welcome`],[`learn-hub|Amazon API Gateway Azure API Management These services provide a turnkey solution for publishing APIs to internal and external customers.`,`apigw-welcome|These tasks include traffic management, authorization and access control, monitoring, and API version management.`]),breaks:n(`Learn pairs Amazon API Gateway with Azure API Management as a turnkey solution for publishing APIs. On AWS, API Gateway throttles requests with a token bucket algorithm, and a usage plan can set the target request rate to start throttling requests.`,[`apigw-throttling`,`apigw-usage-plans`,`learn-hub`],[`apigw-throttling|API Gateway throttles requests to your API using the token bucket algorithm, where a token counts for a request.`,`apigw-usage-plans|A usage plan specifies who can access one or more deployed API stages and methods—and optionally sets the target request rate to start throttling requests.`,`learn-hub|Amazon API Gateway Azure API Management These services provide a turnkey solution for publishing APIs to internal and external customers.`])}]},S={building:`transit-tariff`,overview:[n(`Connecting an on-premises network to AWS can use a dedicated line (Direct Connect), an encrypted tunnel over the internet (Site-to-Site VPN), a client-based VPN for individual users (Client VPN), or plain internet connections. They differ in setup time, bandwidth, consistency and how they are billed. Direct Connect has two billing elements, port hours and outbound data transfer, while a Site-to-Site VPN is charged for each VPN connection-hour plus standard data transfer charges.`,[`dx-what-is`,`vpn-pricing`,`client-vpn`],[`dx-what-is|AWS Direct Connect has two billing elements: port hours and outbound data transfer.`,`vpn-pricing|You also incur standard AWS data transfer charges for all data transferred via the VPN connection.`,`client-vpn|AWS Client VPN is a managed client-based VPN service that enables you to securely access your AWS resources and resources in your on-premises network.`])],bullets:[{id:`4.4-K5`,concepts:[n(`Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable. With this connection you can create virtual interfaces to public AWS services or to Amazon VPC, bypassing internet service providers in your network path. It is a private, dedicated line.`,`dx-what-is`,[`Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable.`,`you can create virtual interfaces directly to public AWS services (for example, to Amazon S3) or to Amazon VPC, bypassing internet service providers in your network path.`]),n(`Site-to-Site VPN creates an IPsec VPN connection between your remote network and Amazon VPC over the internet. Each connection includes two tunnels you can use simultaneously for high availability.`,[`connectivity-vpn`,`s2s-vpn`],[`connectivity-vpn|Amazon VPC provides the option of creating an IPsec VPN connection between your remote networks and Amazon VPC over the internet`,`s2s-vpn|Each VPN connection includes two VPN tunnels which you can simultaneously use for high availability.`]),n(`Client VPN is a managed client-based VPN service for individual users, accessed from any location using an OpenVPN-based VPN client. It is the choice for remote users connecting to AWS or the on-premises network, not for connecting two networks to each other.`,`client-vpn`,[`AWS Client VPN is a managed client-based VPN service that enables you to securely access your AWS resources and resources in your on-premises network.`,`With Client VPN, you can access your resources from any location using an OpenVPN-based VPN client.`]),n(`Private lines, dedicated lines and VPNs in exam wording map as follows: Direct Connect is the dedicated line, Site-to-Site VPN is the encrypted tunnel over the internet, and Client VPN is user-to-network access. The full Direct Connect and VPN comparison is in the Don't confuse section below.`,[`dx-what-is`,`connectivity-vpn`,`client-vpn`],[`dx-what-is|Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable.`,`connectivity-vpn|Amazon VPC provides the option of creating an IPsec VPN connection between your remote networks and Amazon VPC over the internet`,`client-vpn|Managed service — Eliminates the operational burden of deploying and maintaining third-party remote access VPN solutions through complete AWS management.`])],services:[`AWS Direct Connect`,`AWS Site-to-Site VPN`,`AWS Client VPN`],design:[n(`Cue: "dedicated, private, consistent network path" → Direct Connect; "encrypted connection quickly over the internet" → Site-to-Site VPN; "remote employees need secure access" → Client VPN.`,[`connectivity-dx`,`connectivity-vpn`,`client-vpn`],[`connectivity-dx|Direct Connect can reduce network costs, increase bandwidth throughput, and provide a more consistent network experience than internet-based connections.`,`connectivity-vpn|Amazon VPC provides the option of creating an IPsec VPN connection between your remote networks and Amazon VPC over the internet`,`client-vpn|With Client VPN, you can access your resources from any location using an OpenVPN-based VPN client.`])]},{id:`4.4-S2`,concepts:[n(`Choose by cost and requirement together. Direct Connect can reduce network costs, increase bandwidth throughput and provide a more consistent network experience than internet-based connections, but it has its own billing: port hours, determined by capacity and connection type, and outbound data transfer. A VPN has no dedicated line, is charged per VPN connection-hour plus data transfer, and can be created over your existing internet connection.`,[`connectivity-dx`,`dx-what-is`,`vpn-pricing`],[`connectivity-dx|Direct Connect can reduce network costs, increase bandwidth throughput, and provide a more consistent network experience than internet-based connections.`,`dx-what-is|Port hour pricing is determined by capacity and connection type (dedicated connection or hosted connection).`,`vpn-pricing|VPN connection-hour that your connection is provisioned and available.`]),n(`A Direct Connect connection is either dedicated, a physical Ethernet connection associated with a single customer that you request through the console, CLI or API, or hosted, a physical Ethernet connection that an AWS Direct Connect Partner provisions on your behalf. Hosted connections are requested from a partner in the Direct Connect Partner Program.`,`dx-connection-types`,[`Dedicated Connection: A physical Ethernet connection associated with a single customer.`,`Hosted Connection: A physical Ethernet connection that an AWS Direct Connect Partner provisions on behalf of a customer.`,`Customers request a hosted connection by contacting a partner in the AWS Direct Connect Partner Program, who provisions the connection.`]),n(`Hosted connections offer more port speeds than dedicated ones, including speeds below one gigabit per second, and for a hosted connection the Direct Connect Partner can change the speed. The rule that the port speed cannot be changed after the request applies to dedicated connections.`,[`dx-hosted`,`dx-dedicated`],[`dx-hosted|Port speed For hosted connections, the possible values are 50 Mbps, 100 Mbps, 200 Mbps, 300 Mbps, 400 Mbps, 500 Mbps, 1 Gbps, 2 Gbps, 5 Gbps, 10 Gbps, and 25 Gbps.`,`dx-dedicated|Port speed The possible values are 1 Gbps, 10 Gbps, 100 Gbps, and 400 Gbps.`,`dx-dedicated|You can't change the port speed after you create the connection request.`,`dx-dedicated|For hosted connections, your AWS Direct Connect Partner can change the speed.`],{allow:[`one`]}),n(`Direct Connect is private but not encrypted. AWS Direct Connect does not encrypt your traffic in transit by default, so a requirement to encrypt traffic over Direct Connect needs a transit encryption option. Combining Direct Connect with a Site-to-Site VPN provides an IPsec-encrypted private connection.`,`dx-encryption`,[`AWS Direct Connect does not encrypt your traffic that is in transit by default.`,`To encrypt the data in transit that traverses AWS Direct Connect, you must use the transit encryption options for that service.`,`This combination provides an IPsec-encrypted private connection that also reduces network costs, increases bandwidth throughput, and provides a more consistent network experience than internet-based VPN connections.`]),n(`For critical workloads Direct Connect resiliency is a cost decision too: maximum resiliency uses separate connections that terminate on separate devices in more than one location, providing resiliency against device, connectivity and complete location failures. As study guidance, a Site-to-Site VPN over the internet is a possible backup path, since it is an IPsec VPN connection between your remote networks and Amazon VPC over the internet.`,[`dx-resiliency`,`connectivity-vpn`],[`dx-resiliency|You can achieve maximum resiliency for critical workloads by using separate connections that terminate on separate devices in more than one location`,`dx-resiliency|This model provides resiliency against device, connectivity, and complete location failures.`,`connectivity-vpn|Amazon VPC provides the option of creating an IPsec VPN connection between your remote networks and Amazon VPC over the internet`]),n(`Setup time is part of the choice. For a Direct Connect connection created with the classic wizard, AWS says it can take up to 72 business hours to review your request and provision a port, and the physical cross-connect is separate. A Site-to-Site VPN is software configuration over an existing internet connection and needs no physical port.`,[`dx-classic-connection`,`connectivity-vpn`],[`dx-classic-connection|It can take up to 72 business hours for AWS to review your request and provision a port for your connection.`,`connectivity-vpn|Amazon VPC provides the option of creating an IPsec VPN connection between your remote networks and Amazon VPC over the internet`])],services:[`AWS Direct Connect`,`AWS Site-to-Site VPN`],design:[n(`Cue: "large, steady data volumes, consistent latency, lower transfer cost over time" → Direct Connect; "temporary or low-volume, needed this week" → VPN; "backup for Direct Connect" → VPN or a second connection. This is study guidance: the exam wording decides.`,[`connectivity-dx`,`dx-resiliency`],[`connectivity-dx|Direct Connect can reduce network costs, increase bandwidth throughput, and provide a more consistent network experience than internet-based connections.`,`dx-resiliency|You can achieve maximum resiliency for critical workloads by using separate connections that terminate on separate devices in more than one location`])]},{id:`4.4-S7`,concepts:[n(`A Site-to-Site VPN has a bandwidth limit per tunnel: up to 1.25 Gbps per standard tunnel, and up to 5 Gbps per Large Bandwidth Tunnel, which is available for VPN connections attached to Transit Gateway or Cloud WAN. To get more bandwidth from standard tunnels, for VPN connections on a transit gateway you can aggregate multiple tunnels using ECMP, which requires dynamic routing and is not supported on VPN connections that use static routing.`,[`vpn-tunnels`,`vpn-quotas`],[`vpn-tunnels|Standard bandwidth: Up to 1.25 Gbps per tunnel (default)`,`vpn-tunnels|Large Bandwidth Tunnel (LBT): Up to 5 Gbps per tunnel`,`vpn-tunnels|Large Bandwidth Tunnels are available only for VPN connections attached to Transit Gateway or Cloud WAN.`,`vpn-quotas|For Site-to-Site VPN connections on a transit gateway, you can use ECMP to get higher VPN bandwidth by aggregating multiple VPN tunnels.`,`vpn-quotas|To use ECMP, the VPN connection must be configured for dynamic routing.`,`vpn-quotas|ECMP is not supported on VPN connections that use static routing.`],{newer:[`vpn-large-bandwidth-tunnel`]}),n(`So "a single VPN compared with multiple VPNs" is a bandwidth question: one VPN connection has two tunnels that are for redundancy, and AWS says it is important to configure both tunnels; more throughput than a standard tunnel allows (standard bandwidth is up to 1.25 Gbps per tunnel) can come from ECMP across VPN tunnels on a transit gateway, which requires dynamic routing, or from a Large Bandwidth Tunnel (up to 5 Gbps per tunnel), which is available only for VPN connections attached to a transit gateway or Cloud WAN. The pricing page states that there is an hourly fee for AWS Site-to-Site VPN, while connections are active, and data transfer out on AWS Site-to-Site VPN incurs data transfer out charges that are explained in the EC2 on-demand pricing page.`,[`vpn-tunnels`,`vpn-quotas`,`vpn-pricing`],[`vpn-tunnels|Each Site-to-Site VPN connection has two tunnels, with each tunnel using a unique public IP address.`,`vpn-tunnels|It is important to configure both tunnels for redundancy.`,`vpn-tunnels|Large Bandwidth Tunnel (LBT): Up to 5 Gbps per tunnel`,`vpn-quotas|For Site-to-Site VPN connections on a transit gateway, you can use ECMP to get higher VPN bandwidth by aggregating multiple VPN tunnels.`,`vpn-quotas|To use ECMP, the VPN connection must be configured for dynamic routing.`,`vpn-tunnels|Standard bandwidth: Up to 1.25 Gbps per tunnel (default)`,`vpn-tunnels|Large Bandwidth Tunnels are available only for VPN connections attached to Transit Gateway or Cloud WAN.`,`vpn-pricing|Data transfer out on AWS Site-to-Site VPN incurs data transfer out charges that are explained in the EC2 on-demand pricing page.`,`vpn-pricing|You also incur standard AWS data transfer charges for all data transferred via the VPN connection.`,`vpn-pricing|There is an hourly fee for AWS Site-to-Site VPN, while connections are active.`],{newer:[`vpn-large-bandwidth-tunnel`]}),n(`Direct Connect speed is chosen from the port speeds offered when you create a dedicated connection, and you cannot change the port speed after you create the connection request; to change it you must create and configure a new connection. Size it to the measured traffic, because port-hour pricing depends on capacity.`,[`dx-dedicated`,`dx-what-is`],[`dx-dedicated|Port speed The possible values are 1 Gbps, 10 Gbps, 100 Gbps, and 400 Gbps.`,`dx-dedicated|You can't change the port speed after you create the connection request.`,`dx-dedicated|To change the port speed, you must create and configure a new connection.`,`dx-what-is|Port hour pricing is determined by capacity and connection type (dedicated connection or hosted connection).`])],services:[`AWS Direct Connect`,`AWS Site-to-Site VPN`],design:[n(`Cue: "need more than a single VPN tunnel can carry" → multiple tunnels with ECMP (VPN on a transit gateway, dynamic routing) or a Large Bandwidth Tunnel on a Transit Gateway attachment; "sustained high bandwidth" → Direct Connect with a port speed that fits the load.`,[`vpn-tunnels`,`vpn-quotas`,`dx-dedicated`],[`vpn-tunnels|Large Bandwidth Tunnel (LBT): Up to 5 Gbps per tunnel`,`vpn-quotas|For Site-to-Site VPN connections on a transit gateway, you can use ECMP to get higher VPN bandwidth by aggregating multiple VPN tunnels.`,`dx-dedicated|Port speed The possible values are 1 Gbps, 10 Gbps, 100 Gbps, and 400 Gbps.`],{newer:[`vpn-large-bandwidth-tunnel`]})]}],cues:[e(`dedicated private line from the data centre to AWS`,`AWS Direct Connect`,n(`Direct Connect links your network to a Direct Connect location over a standard Ethernet fiber-optic cable, bypassing internet service providers.`,`dx-what-is`,[`Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable.`])),e(`encrypted connection to a VPC over the internet, quickly`,`AWS Site-to-Site VPN`,n(`Site-to-Site VPN creates an IPsec VPN connection over the internet.`,`connectivity-vpn`,[`Amazon VPC provides the option of creating an IPsec VPN connection between your remote networks and Amazon VPC over the internet`])),e(`remote employees need secure access to VPC resources`,`AWS Client VPN`,n(`Client VPN is a managed client-based VPN service for secure access from any location.`,`client-vpn`,[`With Client VPN, you can access your resources from any location using an OpenVPN-based VPN client.`])),e(`connection provisioned through an APN partner instead of ordering a physical port`,`Direct Connect hosted connection`,n(`A hosted connection is provisioned by a Direct Connect Partner on behalf of the customer.`,`dx-connection-types`,[`Hosted Connection: A physical Ethernet connection that an AWS Direct Connect Partner provisions on behalf of a customer.`])),e(`VPN throughput exceeds a single tunnel`,`Multiple tunnels with ECMP (VPN on a transit gateway), or a Large Bandwidth Tunnel`,n(`ECMP aggregates multiple VPN tunnels for higher bandwidth on a transit gateway, and needs dynamic routing.`,`vpn-quotas`,[`For Site-to-Site VPN connections on a transit gateway, you can use ECMP to get higher VPN bandwidth by aggregating multiple VPN tunnels.`,`ECMP is not supported on VPN connections that use static routing.`])),e(`Direct Connect port speed needs to change later`,`Create a new connection (port speed cannot be changed)`,n(`You cannot change the port speed after you create the connection request.`,`dx-dedicated`,[`You can't change the port speed after you create the connection request.`]))],examples:[],confuse:[`direct-connect-vs-vpn`],azure:[{concept:`ExpressRoute`,aws:`AWS Direct Connect`,mapping:n(`Learn pairs AWS Direct Connect with Azure ExpressRoute: AWS Direct Connect can link a network directly to AWS, and Azure provides similar site-to-site dedicated connections through ExpressRoute.`,[`learn-networking`,`dx-what-is`],[`learn-networking|AWS Direct Connect can link a network directly to AWS.`,`learn-networking|Azure provides similar site-to-site dedicated connections through ExpressRoute.`,`dx-what-is|Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable.`]),breaks:n(`AWS Direct Connect has two billing elements, port hours and outbound data transfer, and for a dedicated connection you cannot change the port speed after you create the connection request. Learn describes ExpressRoute as similar site-to-site dedicated connections.`,[`dx-what-is`,`dx-dedicated`,`learn-networking`],[`dx-what-is|AWS Direct Connect has two billing elements: port hours and outbound data transfer.`,`dx-dedicated|You can't change the port speed after you create the connection request.`,`learn-networking|Azure provides similar site-to-site dedicated connections through ExpressRoute.`])},{concept:`VPN Gateway`,aws:`AWS Site-to-Site VPN`,mapping:n(`Learn pairs AWS Site-to-Site VPN with Azure VPN Gateway as solutions for connecting on-premises networks to the cloud, and compares their throughput.`,[`learn-networking`,`vpn-tunnels`],[`learn-networking|Both AWS Site-to-Site VPN and Azure VPN Gateway are robust solutions for connecting on-premises networks to the cloud.`,`vpn-tunnels|Each Site-to-Site VPN connection has two tunnels, with each tunnel using a unique public IP address.`]),breaks:n(`Learn says VPN Gateway offers higher throughput for certain configurations than Site-to-Site VPN. The AWS limits are per tunnel, for a standard tunnel and for a Large Bandwidth Tunnel, and using ECMP requires dynamic routing.`,[`learn-networking`,`vpn-tunnels`,`vpn-quotas`],[`learn-networking|VPN Gateway offers higher throughput for certain configurations`,`vpn-tunnels|Standard bandwidth: Up to 1.25 Gbps per tunnel (default)`,`vpn-tunnels|Large Bandwidth Tunnel (LBT): Up to 5 Gbps per tunnel`,`vpn-quotas|To use ECMP, the VPN connection must be configured for dynamic routing.`],{newer:[`vpn-large-bandwidth-tunnel`]})}]},C=Object.values(Object.assign({"../../content/notes/treasury/backup-archive.ts":r,"../../content/notes/treasury/block-warehouse.ts":i,"../../content/notes/treasury/capacity-meter.ts":a,"../../content/notes/treasury/cold-cellar.ts":o,"../../content/notes/treasury/counting-house.ts":s,"../../content/notes/treasury/db-cost-desk.ts":c,"../../content/notes/treasury/distribution-office.ts":l,"../../content/notes/treasury/elastic-mint.ts":u,"../../content/notes/treasury/engine-exchange.ts":d,"../../content/notes/treasury/haul-hybrid-customs.ts":f,"../../content/notes/treasury/instance-foundry.ts":p,"../../content/notes/treasury/ledger-office.ts":m,"../../content/notes/treasury/nat-toll.ts":h,"../../content/notes/treasury/network-cost-audit.ts":g,"../../content/notes/treasury/retention-records.ts":_,"../../content/notes/treasury/route-tariff.ts":v,"../../content/notes/treasury/service-selection-bureau.ts":y,"../../content/notes/treasury/storage-market.ts":b,"../../content/notes/treasury/throttle-lb-gate.ts":x,"../../content/notes/treasury/transit-tariff.ts":S}));export{C as notes};